/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2025_SEED = {"dse/writing/part-b/2025/Q2":[{"front":"the boy I thought would never change","meaning":"我以為永遠不會改變的男孩","examples":[{"en":"Kelvin was the boy I thought would never change.","zh":"Kelvin 是我以為永遠不會改變的男孩。"},{"en":"The boy I thought would never change means a boy I believed would always behave in the same way.","zh":"“The boy I thought would never change” 指我以為行為永遠不會改變的男孩。"},{"en":"Jason was the boy I thought would never change until he apologised to the class.","zh":"Jason 曾是我以為永遠不會改變的男孩，直到他向全班道歉。"},{"en":"People may surprise us because even someone we think will never change can learn from pain or responsibility.","zh":"人可能會令我們意外，因為即使是我們以為不會改變的人，也可能從痛苦或責任中學習。"},{"en":"This phrase shows the writer’s old judgement before discovering Kelvin’s growth.","zh":"這個說法顯示作者在發現 Kelvin 成長前的舊判斷。"}],"source":"2025 Q2.pdf","sourcePage":1},{"front":"the last person I expected to see","meaning":"我最意想不到會見到的人","examples":[{"en":"The last person I expected to see at a theme park was Kelvin Chan.","zh":"在主題公園裏，我最意想不到會見到的人是 Kelvin Chan。"},{"en":"The last person I expected to see means the person whose appearance surprised me most.","zh":"“The last person I expected to see” 指最令我意外出現的人。"},{"en":"The last person I expected to see at the hospital volunteer desk was my old bully.","zh":"在醫院義工櫃枱，我最意想不到會見到的人是以前欺負我的同學。"},{"en":"This phrase is useful when someone appears in a place or role that does not match our memory of them.","zh":"當某人出現在與我們記憶不相符的地方或角色中時，這個說法很有用。"},{"en":"It creates surprise before explaining why the meeting mattered.","zh":"它先製造驚訝，再解釋這次相遇為何重要。"}],"source":"2025 Q2.pdf","sourcePage":1},{"front":"theme park","meaning":"主題公園","examples":[{"en":"I did not expect to see Kelvin at a theme park.","zh":"我沒有預期會在主題公園見到 Kelvin。"},{"en":"A theme park is a large entertainment place with rides, games, shows, and food stalls.","zh":"主題公園是有機動遊戲、遊戲攤位、表演和食物攤的大型娛樂場所。"},{"en":"Families often visit a theme park during holidays to enjoy rides together.","zh":"家庭常在假期到主題公園一起玩機動遊戲。"},{"en":"A theme park can feel noisy and cheerful, which makes a serious meeting there more surprising.","zh":"主題公園感覺嘈雜又愉快，因此在那裏發生嚴肅相遇會更令人意外。"},{"en":"In this story, the theme park becomes the place where the writer sees Kelvin differently.","zh":"在這個故事中，主題公園成為作者重新看待 Kelvin 的地方。"}],"source":"2025 Q2.pdf","sourcePage":1},{"front":"a hot Saturday afternoon","meaning":"一個炎熱的星期六下午","examples":[{"en":"It was a hot Saturday afternoon at the theme park.","zh":"那是主題公園裏一個炎熱的星期六下午。"},{"en":"A hot Saturday afternoon is a warm weekend afternoon, often busy because many people are free.","zh":"一個炎熱的星期六下午，是天氣熱而且很多人有空外出的週末下午。"},{"en":"On a hot Saturday afternoon, the playground was full of children and parents.","zh":"在一個炎熱的星期六下午，遊樂場滿是孩子和家長。"},{"en":"Heat and crowds can make a theme park feel tiring and restless.","zh":"炎熱和人群會令主題公園感覺疲累又躁動。"},{"en":"This phrase sets the time, weather, and lively mood of the scene.","zh":"這個說法交代場景的時間、天氣和熱鬧氣氛。"}],"source":"2025 Q2.pdf","sourcePage":1},{"front":"roller coasters","meaning":"過山車","examples":[{"en":"Roller coasters thundered overhead.","zh":"過山車在頭頂轟隆駛過。"},{"en":"Roller coasters are amusement rides that run quickly along high tracks with drops and turns.","zh":"過山車是在高架路軌上高速行駛、有下墜和轉彎的機動遊戲。"},{"en":"The children screamed as the roller coaster rushed down the steep track.","zh":"過山車衝下陡斜路軌時，孩子們尖叫起來。"},{"en":"Roller coasters create excitement because they mix speed, height, fear, and fun.","zh":"過山車把速度、高度、恐懼和樂趣混在一起，所以令人興奮。"},{"en":"In the scene, roller coasters add noise and movement above the characters.","zh":"在這個場景中，過山車在角色頭上增加聲音和動感。"}],"source":"2025 Q2.pdf","sourcePage":1},{"front":"thundered overhead","meaning":"在頭頂轟隆駛過","examples":[{"en":"Roller coasters thundered overhead.","zh":"過山車在頭頂轟隆駛過。"},{"en":"Thundered overhead means moved noisily and powerfully above someone’s head.","zh":"“Thundered overhead” 指在某人頭頂上方嘈雜而有力地移動。"},{"en":"The train thundered overhead as we walked under the bridge.","zh":"我們走在橋底時，火車在頭頂轟隆駛過。"},{"en":"A ride thundering overhead can make a place feel loud, fast, and slightly frightening.","zh":"機動遊戲在頭頂轟隆駛過，會令地方感覺吵鬧、快速而有點可怕。"},{"en":"This phrase helps the reader hear the theme park before seeing Kelvin.","zh":"這個說法幫助讀者在看見 Kelvin 前先聽見主題公園。"}],"source":"2025 Q2.pdf","sourcePage":1},{"front":"music blasted from","meaning":"音樂從……大聲播放","examples":[{"en":"Music blasted from loudspeakers around the park.","zh":"音樂從公園四周的擴音器大聲播放。"},{"en":"Music blasted from somewhere means music played very loudly from that place.","zh":"“Music blasted from” 指音樂從某處非常大聲地播放出來。"},{"en":"Pop music blasted from the shop speakers during the sale.","zh":"減價期間，流行音樂從店舖喇叭大聲播放。"},{"en":"Loud music can make a public place feel energetic but also overwhelming.","zh":"大聲音樂可以令公共地方充滿活力，但也可能令人覺得壓迫。"},{"en":"This phrase adds to the noisy background of the theme park.","zh":"這個說法增加主題公園嘈雜的背景。"}],"source":"2025 Q2.pdf","sourcePage":1},{"front":"loudspeakers","meaning":"擴音器","examples":[{"en":"Music blasted from loudspeakers.","zh":"音樂從擴音器大聲播放。"},{"en":"Loudspeakers are devices that make recorded or live sound louder for many people to hear.","zh":"擴音器是把錄音或現場聲音放大，讓很多人聽見的裝置。"},{"en":"The school used loudspeakers to announce the start of sports day.","zh":"學校用擴音器宣布運動會開始。"},{"en":"Loudspeakers can spread music or messages across a crowded place.","zh":"擴音器可以把音樂或訊息傳遍擠迫地方。"},{"en":"In the story, loudspeakers help create the busy sound of the park.","zh":"在故事中，擴音器幫助營造主題公園繁忙的聲音。"}],"source":"2025 Q2.pdf","sourcePage":1},{"front":"smelled of","meaning":"有……的氣味","examples":[{"en":"The air smelled of popcorn and sunscreen.","zh":"空氣中有爆谷和防曬霜的氣味。"},{"en":"Smelled of means had the smell of something.","zh":"“Smelled of” 指帶有某種氣味。"},{"en":"The kitchen smelled of fresh bread after breakfast.","zh":"早餐後，廚房有新鮮麵包的氣味。"},{"en":"A place can smell of food, weather, or people’s activities.","zh":"一個地方可以有食物、天氣或人們活動留下的氣味。"},{"en":"This phrase uses smell to make a scene feel real.","zh":"這個說法透過氣味令場景更真實。"}],"source":"2025 Q2.pdf","sourcePage":1},{"front":"popcorn and sunscreen","meaning":"爆谷和防曬霜","examples":[{"en":"The air smelled of popcorn and sunscreen.","zh":"空氣中有爆谷和防曬霜的氣味。"},{"en":"Popcorn and sunscreen suggest a day of outdoor entertainment, snacks, heat, and crowds.","zh":"爆谷和防曬霜暗示戶外娛樂、小食、炎熱天氣和人群。"},{"en":"At the beach fair, the air smelled of popcorn and sunscreen.","zh":"在海灘嘉年華，空氣中有爆谷和防曬霜的氣味。"},{"en":"These smells can remind people of holidays, queues, and family outings.","zh":"這些氣味可以令人想起假期、排隊和家庭外出。"},{"en":"In the story, popcorn and sunscreen quickly place us inside a busy theme park.","zh":"在故事中，爆谷和防曬霜很快把我們帶入繁忙的主題公園。"}],"source":"2025 Q2.pdf","sourcePage":1},{"front":"step out of a queue","meaning":"從隊伍中走出來","examples":[{"en":"I had just stepped out of a queue when I noticed a crying girl.","zh":"我剛從隊伍中走出來，便注意到一個哭泣的小女孩。"},{"en":"To step out of a queue means to leave a line of waiting people.","zh":"“Step out of a queue” 指離開正在排隊的人龍。"},{"en":"I stepped out of the queue to answer an urgent phone call.","zh":"我從隊伍中走出來，接聽一個緊急電話。"},{"en":"Someone may step out of a queue when they notice a problem nearby.","zh":"當有人注意到附近有問題時，可能會從隊伍中走出來。"},{"en":"This phrase shows the writer moving away from ordinary waiting into an important moment.","zh":"這個說法顯示作者從普通等待走向一個重要時刻。"}],"source":"2025 Q2.pdf","sourcePage":2},{"front":"noticed","meaning":"注意到","examples":[{"en":"I noticed a little girl crying outside a souvenir shop.","zh":"我注意到一個小女孩在紀念品店外哭。"},{"en":"Noticed means saw, heard, or became aware of something.","zh":"“Noticed” 指看見、聽見或意識到某事。"},{"en":"I noticed that my classmate looked upset after lunch.","zh":"午飯後，我注意到同學看起來不開心。"},{"en":"People who notice small signs of trouble can help before a problem grows worse.","zh":"能注意到麻煩小跡象的人，可以在問題惡化前幫忙。"},{"en":"This word shows attention to details that others might miss.","zh":"這個詞顯示對別人可能忽略的細節有所留意。"}],"source":"2025 Q2.pdf","sourcePage":2},{"front":"souvenir shop","meaning":"紀念品店","examples":[{"en":"A little girl was crying outside a souvenir shop.","zh":"一個小女孩在紀念品店外哭。"},{"en":"A souvenir shop is a store that sells gifts or objects people buy to remember a place or event.","zh":"紀念品店是售賣讓人紀念某地方或活動的禮物和物件的店舖。"},{"en":"Visitors bought key rings and postcards from the souvenir shop.","zh":"遊客在紀念品店買鎖匙扣和明信片。"},{"en":"A child may get lost near a souvenir shop because crowds stop to look at gifts.","zh":"孩子可能在紀念品店附近走失，因為人群會停下來看禮物。"},{"en":"This phrase gives a specific and believable theme-park location.","zh":"這個說法提供一個具體而可信的主題公園地點。"}],"source":"2025 Q2.pdf","sourcePage":2},{"front":"before I could move","meaning":"我還未來得及行動","examples":[{"en":"Before I could move, a young man crouched beside her.","zh":"我還未來得及行動，一名年輕男子已蹲在她旁邊。"},{"en":"Before I could move means before I had time to act or respond.","zh":"“Before I could move” 指我還未有時間行動或回應。"},{"en":"Before I could move, the teacher had already picked up the fallen books.","zh":"我還未來得及行動，老師已經撿起掉下的書。"},{"en":"This phrase shows that someone else acted more quickly than the speaker.","zh":"這個說法顯示別人比說話者更快行動。"},{"en":"It creates a sudden moment that reveals Kelvin’s changed behaviour.","zh":"它製造一個突然時刻，揭示 Kelvin 改變了的行為。"}],"source":"2025 Q2.pdf","sourcePage":2},{"front":"crouched beside","meaning":"蹲在……旁邊","examples":[{"en":"A young man crouched beside the little girl.","zh":"一名年輕男子蹲在小女孩旁邊。"},{"en":"To crouch beside someone means to bend low next to them, often to speak gently or help.","zh":"“Crouch beside” 指在某人旁邊彎低身體，常是為了溫柔說話或幫忙。"},{"en":"The nurse crouched beside the child so they were at the same eye level.","zh":"護士蹲在孩子旁邊，讓自己和孩子視線同高。"},{"en":"Crouching beside a frightened child can make the adult seem less threatening.","zh":"蹲在受驚孩子旁邊，可以令成人看起來沒那麼具威脅性。"},{"en":"This action shows care because Kelvin lowers himself to the girl’s level.","zh":"這個動作顯示關心，因為 Kelvin 降低身體到女孩的高度。"}],"source":"2025 Q2.pdf","sourcePage":2},{"front":"spoke gently","meaning":"溫柔地說話","examples":[{"en":"Kelvin spoke gently to the crying girl.","zh":"Kelvin 溫柔地對哭泣的小女孩說話。"},{"en":"Spoke gently means talked in a soft, calm, and kind way.","zh":"“Spoke gently” 指以柔和、冷靜和善意的方式說話。"},{"en":"The teacher spoke gently to the nervous student before the presentation.","zh":"匯報前，老師溫柔地對緊張的學生說話。"},{"en":"Speaking gently can calm someone who is scared or upset.","zh":"溫柔地說話可以安撫害怕或難過的人。"},{"en":"This phrase shows Kelvin using kindness instead of force.","zh":"這個說法顯示 Kelvin 使用善意，而不是強硬。"}],"source":"2025 Q2.pdf","sourcePage":2},{"front":"handed her a tissue","meaning":"遞給她一張紙巾","examples":[{"en":"He handed the little girl a tissue.","zh":"他遞給小女孩一張紙巾。"},{"en":"Handed her a tissue means gave her a piece of tissue paper, usually to wipe tears or clean something.","zh":"“Handed her a tissue” 指給她一張紙巾，通常用來擦眼淚或清潔。"},{"en":"My friend handed me a tissue when I started crying after the interview.","zh":"面試後我開始哭時，朋友遞給我一張紙巾。"},{"en":"Giving a tissue is a small action, but it can show quiet care.","zh":"遞紙巾是一個小動作，但可以顯示安靜的關心。"},{"en":"In the scene, the tissue makes Kelvin’s kindness practical and visible.","zh":"在場景中，紙巾令 Kelvin 的善意變得實際而可見。"}],"source":"2025 Q2.pdf","sourcePage":2},{"front":"turned around","meaning":"轉過身來","examples":[{"en":"Then he turned around, and I recognised him.","zh":"然後他轉過身來，我認出了他。"},{"en":"Turned around means changed direction so that he faced another way.","zh":"“Turned around” 指改變身體方向，面向另一邊。"},{"en":"She turned around when someone called her name.","zh":"有人叫她名字時，她轉過身來。"},{"en":"In a story, a person turning around can reveal an identity or surprise.","zh":"在故事中，人物轉過身來可以揭示身份或帶來驚訝。"},{"en":"This phrase marks the moment when the writer realises the helper is Kelvin.","zh":"這個說法標示作者發現幫忙的人是 Kelvin 的一刻。"}],"source":"2025 Q2.pdf","sourcePage":2},{"front":"notorious for","meaning":"因……而臭名遠播","examples":[{"en":"At school, Kelvin had been notorious for all the wrong reasons.","zh":"在學校，Kelvin 曾因各種不好的原因而臭名遠播。"},{"en":"Notorious for means widely known for something bad or unpleasant.","zh":"“Notorious for” 指因壞事或令人不快的行為而廣為人知。"},{"en":"The student was notorious for interrupting lessons and laughing at others.","zh":"那名學生因打斷課堂和嘲笑別人而臭名遠播。"},{"en":"Being notorious for bad behaviour can make people expect the worst from someone.","zh":"因壞行為而臭名遠播，會令人對某人有最壞期望。"},{"en":"This phrase explains why Kelvin’s kindness shocks the writer.","zh":"這個說法解釋為何 Kelvin 的善意令作者震驚。"}],"source":"2025 Q2.pdf","sourcePage":2},{"front":"for all the wrong reasons","meaning":"因為不好的原因","examples":[{"en":"Kelvin had been notorious for all the wrong reasons.","zh":"Kelvin 曾因為不好的原因而臭名遠播。"},{"en":"For all the wrong reasons means known for negative, shameful, or undesirable behaviour.","zh":"“For all the wrong reasons” 指因負面、羞恥或不受歡迎的行為而出名。"},{"en":"The shop became famous for all the wrong reasons after several rude service complaints.","zh":"那間店在多宗服務無禮投訴後，因為不好的原因而出名。"},{"en":"A student known for all the wrong reasons may find it hard to rebuild trust.","zh":"因不好原因出名的學生，可能很難重建信任。"},{"en":"This phrase makes clear that Kelvin’s old reputation was not admirable.","zh":"這個說法清楚指出 Kelvin 舊日名聲並不值得欣賞。"}],"source":"2025 Q2.pdf","sourcePage":2},{"front":"mocked weaker students","meaning":"嘲笑較弱的學生","examples":[{"en":"Kelvin mocked weaker students at school.","zh":"Kelvin 在學校嘲笑較弱的學生。"},{"en":"Mocked weaker students means made fun of students who seemed less confident, less able, or easier to hurt.","zh":"“Mocked weaker students” 指取笑看起來較沒自信、能力較弱或較容易受傷的學生。"},{"en":"A bully mocked weaker students when they answered questions wrongly.","zh":"有個欺凌者在學生答錯問題時嘲笑較弱的學生。"},{"en":"Mocking weaker students can damage confidence and make classrooms unsafe.","zh":"嘲笑較弱的學生會傷害自信，令課室變得不安全。"},{"en":"This phrase shows Kelvin’s old cruelty towards vulnerable classmates.","zh":"這個說法顯示 Kelvin 舊日對脆弱同學的殘酷。"}],"source":"2025 Q2.pdf","sourcePage":3},{"front":"hid people’s belongings","meaning":"藏起別人的物品","examples":[{"en":"He hid people’s belongings for fun.","zh":"他為了好玩而藏起別人的物品。"},{"en":"Hid people’s belongings means secretly put others’ things somewhere they could not easily find them.","zh":"“Hid people’s belongings” 指偷偷把別人的東西放到他們不容易找到的地方。"},{"en":"The boys hid a classmate’s pencil case behind the cupboard.","zh":"那些男孩把同學的筆袋藏在櫃後。"},{"en":"Hiding people’s belongings may look like a joke to the bully but feel frightening to the victim.","zh":"藏起別人的物品對欺凌者來說可能像玩笑，但對受害者來說可能很可怕。"},{"en":"This phrase shows careless cruelty disguised as play.","zh":"這個說法顯示被偽裝成玩樂的粗心殘酷。"}],"source":"2025 Q2.pdf","sourcePage":3},{"front":"for fun","meaning":"為了好玩","examples":[{"en":"Kelvin used to hide people’s belongings for fun.","zh":"Kelvin 以前為了好玩而藏起別人的物品。"},{"en":"For fun means for amusement or enjoyment, not for a serious purpose.","zh":"“For fun” 指為了娛樂或享受，而不是為了嚴肅目的。"},{"en":"Children played football in the park for fun after school.","zh":"孩子放學後在公園踢足球，只是為了好玩。"},{"en":"Doing something for fun is not acceptable if it hurts or embarrasses others.","zh":"如果一件事會傷害或羞辱別人，即使是為了好玩也不可接受。"},{"en":"In Kelvin’s case, “for fun” shows how selfish his old behaviour was.","zh":"就 Kelvin 而言，“for fun” 顯示他舊日行為多麼自私。"}],"source":"2025 Q2.pdf","sourcePage":3},{"front":"in front of the whole class","meaning":"在全班面前","examples":[{"en":"He once made a girl cry in front of the whole class.","zh":"他曾經在全班面前弄哭一個女孩。"},{"en":"In front of the whole class means while all classmates were watching or listening.","zh":"“In front of the whole class” 指在所有同學觀看或聆聽的情況下。"},{"en":"Being corrected in front of the whole class can feel embarrassing for a shy student.","zh":"害羞學生在全班面前被糾正，可能會感到尷尬。"},{"en":"Hurting someone in front of the whole class makes the pain public and harder to forget.","zh":"在全班面前傷害別人，會令痛苦變得公開並更難忘記。"},{"en":"This phrase shows how humiliating Kelvin’s behaviour was.","zh":"這個說法顯示 Kelvin 的行為多麼羞辱人。"}],"source":"2025 Q2.pdf","sourcePage":3},{"front":"seemed to enjoy","meaning":"似乎享受……","examples":[{"en":"He seemed to enjoy making others feel small.","zh":"他似乎享受令別人覺得渺小。"},{"en":"Seemed to enjoy means appeared to take pleasure in something.","zh":"“Seemed to enjoy” 指看起來從某事中得到快感。"},{"en":"The boy seemed to enjoy interrupting others during group work.","zh":"那個男孩似乎享受在小組活動中打斷別人。"},{"en":"When someone seems to enjoy hurting others, classmates may feel unsafe around them.","zh":"當某人似乎享受傷害別人，同學在他身邊可能會感到不安全。"},{"en":"This phrase describes how Kelvin’s behaviour looked to other students.","zh":"這個說法描述 Kelvin 的行為在其他學生眼中是怎樣的。"}],"source":"2025 Q2.pdf","sourcePage":3},{"front":"make others feel small","meaning":"令別人覺得渺小","examples":[{"en":"Kelvin seemed to enjoy making others feel small.","zh":"Kelvin 似乎享受令別人覺得渺小。"},{"en":"To make others feel small means to make people feel weak, ashamed, unimportant, or inferior.","zh":"“Make others feel small” 指令別人覺得軟弱、羞愧、不重要或低人一等。"},{"en":"Laughing at a classmate’s mistake can make others feel small.","zh":"嘲笑同學的錯誤會令別人覺得渺小。"},{"en":"People who make others feel small often do it to feel powerful themselves.","zh":"令別人覺得渺小的人，常是為了讓自己感覺強大。"},{"en":"This phrase shows emotional harm, not just ordinary teasing.","zh":"這個說法顯示情感傷害，而不只是普通打趣。"}],"source":"2025 Q2.pdf","sourcePage":3},{"front":"the Kelvin in front of me","meaning":"我眼前的 Kelvin","examples":[{"en":"The Kelvin in front of me looked completely different.","zh":"我眼前的 Kelvin 看起來完全不同。"},{"en":"The Kelvin in front of me means the version of Kelvin the writer was seeing at that moment.","zh":"“The Kelvin in front of me” 指作者在那一刻親眼看見的 Kelvin。"},{"en":"The Kelvin in front of me was calm, gentle, and nothing like the boy I remembered.","zh":"我眼前的 Kelvin 冷靜、溫柔，完全不像我記憶中的男孩。"},{"en":"This phrase contrasts present reality with old memory.","zh":"這個說法把眼前現實與舊記憶作對比。"},{"en":"It shows that the writer is beginning to reconsider Kelvin.","zh":"它顯示作者開始重新看待 Kelvin。"}],"source":"2025 Q2.pdf","sourcePage":3},{"front":"completely different","meaning":"完全不同","examples":[{"en":"The Kelvin in front of me looked completely different.","zh":"我眼前的 Kelvin 看起來完全不同。"},{"en":"Completely different means not the same at all in appearance, behaviour, or character.","zh":"“Completely different” 指在外表、行為或性格上完全不一樣。"},{"en":"After volunteering for a year, he seemed completely different from the selfish boy I knew.","zh":"做了一年義工後，他看起來與我認識的自私男孩完全不同。"},{"en":"A person can look completely different when their actions show maturity.","zh":"當一個人的行動顯示成熟時，他可以看起來完全不同。"},{"en":"This phrase emphasises the strength of Kelvin’s change.","zh":"這個說法強調 Kelvin 改變的程度。"}],"source":"2025 Q2.pdf","sourcePage":3},{"front":"stayed with","meaning":"留在……身邊","examples":[{"en":"Kelvin stayed with the little girl until a staff member arrived.","zh":"Kelvin 留在小女孩身邊，直到職員到來。"},{"en":"Stayed with means remained beside someone to help, comfort, or protect them.","zh":"“Stayed with” 指留在某人旁邊，以幫助、安慰或保護對方。"},{"en":"The teacher stayed with the injured student until the nurse came.","zh":"老師留在受傷學生身邊，直到護士到來。"},{"en":"Staying with a frightened child can stop them from feeling abandoned.","zh":"留在受驚孩子身邊，可以避免他們感到被拋下。"},{"en":"This phrase shows Kelvin’s patience and responsibility.","zh":"這個說法顯示 Kelvin 的耐性和責任感。"}],"source":"2025 Q2.pdf","sourcePage":3},{"front":"staff member","meaning":"職員","examples":[{"en":"A staff member arrived to help the little girl.","zh":"一名職員到來幫助小女孩。"},{"en":"A staff member is a worker employed by an organisation, shop, school, or public place.","zh":"職員是受僱於機構、店舖、學校或公共場所的工作人員。"},{"en":"A theme park staff member helped the lost child find her mother.","zh":"一名主題公園職員幫助走失的孩子找回媽媽。"},{"en":"Staff members are important in public places because visitors may need help quickly.","zh":"職員在公共地方很重要，因為訪客可能很快需要協助。"},{"en":"This phrase identifies the official helper who takes over from Kelvin.","zh":"這個說法指出接手 Kelvin 的官方幫助者。"}],"source":"2025 Q2.pdf","sourcePage":3},{"front":"reassuring smile","meaning":"令人安心的微笑","examples":[{"en":"Kelvin gave the little girl a reassuring smile.","zh":"Kelvin 給了小女孩一個令人安心的微笑。"},{"en":"A reassuring smile is a kind smile that makes someone feel safer or less worried.","zh":"令人安心的微笑是讓人感到較安全或較少擔心的善意笑容。"},{"en":"The nurse gave the child a reassuring smile before the injection.","zh":"打針前，護士給孩子一個令人安心的微笑。"},{"en":"A reassuring smile can calm a frightened person without many words.","zh":"一個令人安心的微笑不用很多說話，也可以安撫受驚的人。"},{"en":"This phrase shows Kelvin’s gentle way of helping.","zh":"這個說法顯示 Kelvin 溫柔幫人的方式。"}],"source":"2025 Q2.pdf","sourcePage":4},{"front":"recognised me","meaning":"認出我","examples":[{"en":"Kelvin recognised me and looked surprised.","zh":"Kelvin 認出我，並顯得很驚訝。"},{"en":"Recognised me means knew who I was after seeing or hearing me.","zh":"“Recognised me” 指看見或聽見我後知道我是誰。"},{"en":"My old primary school teacher recognised me at the station.","zh":"我的舊小學老師在車站認出我。"},{"en":"Recognising someone from the past can bring back old memories suddenly.","zh":"認出過去認識的人，可以突然喚起舊回憶。"},{"en":"This phrase begins the direct meeting between Kelvin and the writer.","zh":"這個說法開始 Kelvin 與作者的直接相遇。"}],"source":"2025 Q2.pdf","sourcePage":4},{"front":"long time no see","meaning":"好耐冇見","examples":[{"en":"Kelvin said, “Long time no see.”","zh":"Kelvin 說：「好耐冇見。」"},{"en":"Long time no see is an informal greeting used when people have not met for a long time.","zh":"“Long time no see” 是很久沒有見面時使用的非正式問候語。"},{"en":"“Long time no see,” my old classmate said when we met at the café.","zh":"我們在咖啡店相遇時，舊同學說：「好耐冇見。」"},{"en":"This phrase can sound friendly, but it may also feel awkward if the past was difficult.","zh":"這句話可以聽起來友善，但如果過去不愉快，也可能令人尷尬。"},{"en":"In this scene, the greeting opens an uncomfortable but honest conversation.","zh":"在這個場景中，這句問候開啟了一段尷尬但誠實的對話。"}],"source":"2025 Q2.pdf","sourcePage":4},{"front":"sitting on a bench","meaning":"坐在長椅上","examples":[{"en":"We were soon sitting on a bench near the Ferris wheel.","zh":"我們很快坐在摩天輪附近的一張長椅上。"},{"en":"Sitting on a bench means resting on a long seat often found in parks or public places.","zh":"“Sitting on a bench” 指坐在公園或公共地方常見的長椅上休息。"},{"en":"We were sitting on a bench outside the library when the rain stopped.","zh":"雨停時，我們正坐在圖書館外的長椅上。"},{"en":"Sitting together on a bench can create a quieter space for conversation.","zh":"一起坐在長椅上，可以營造較安靜的談話空間。"},{"en":"This phrase slows the scene after the noisy theme park moment.","zh":"這個說法在嘈雜的主題公園場景後放慢節奏。"}],"source":"2025 Q2.pdf","sourcePage":4},{"front":"Ferris wheel","meaning":"摩天輪","examples":[{"en":"We sat on a bench near the Ferris wheel.","zh":"我們坐在摩天輪附近的長椅上。"},{"en":"A Ferris wheel is a large upright wheel with passenger cabins that move slowly in a circle.","zh":"摩天輪是一個大型直立輪狀機動遊戲，乘客艙會慢慢繞圈移動。"},{"en":"From the Ferris wheel, visitors could see the whole theme park.","zh":"從摩天輪上，遊客可以看見整個主題公園。"},{"en":"A Ferris wheel often feels calmer than faster rides such as roller coasters.","zh":"摩天輪通常比過山車等快速機動遊戲更平靜。"},{"en":"In the story, it provides a clear landmark for the conversation.","zh":"在故事中，它為這段對話提供清楚地標。"}],"source":"2025 Q2.pdf","sourcePage":4},{"front":"cups of lemonade","meaning":"幾杯檸檬水","examples":[{"en":"We sat with cups of lemonade in our hands.","zh":"我們手中拿着幾杯檸檬水坐着。"},{"en":"Cups of lemonade are cups filled with a sweet lemon drink.","zh":"幾杯檸檬水是盛着甜檸檬飲品的杯子。"},{"en":"After walking in the hot sun, we bought cups of lemonade from a stall.","zh":"在烈日下走了一會兒後，我們從攤位買了幾杯檸檬水。"},{"en":"Holding cups of lemonade can make a serious conversation feel more ordinary and natural.","zh":"手拿檸檬水可以令嚴肅對話感覺更日常和自然。"},{"en":"This detail reminds readers of the heat and casual setting.","zh":"這個細節提醒讀者天氣炎熱和場景輕鬆。"}],"source":"2025 Q2.pdf","sourcePage":4},{"front":"awkward updates","meaning":"尷尬的近況分享","examples":[{"en":"We exchanged a few awkward updates about university and work.","zh":"我們尷尬地分享了一些關於大學和工作的近況。"},{"en":"Awkward updates are uncomfortable pieces of news shared when people do not know how to talk naturally.","zh":"尷尬的近況分享，是人們不知道如何自然交談時分享的不自在消息。"},{"en":"At the reunion, we gave awkward updates about jobs, studies, and families.","zh":"在重聚中，我們尷尬地分享工作、學業和家庭近況。"},{"en":"Awkward updates often happen when old classmates meet after a difficult past.","zh":"當有困難過去的舊同學重遇時，常會出現尷尬的近況分享。"},{"en":"This phrase shows the tension before the honest conversation begins.","zh":"這個說法顯示坦誠對話開始前的緊張。"}],"source":"2025 Q2.pdf","sourcePage":4},{"front":"what I had been thinking","meaning":"我一直在想的事","examples":[{"en":"I finally said what I had been thinking.","zh":"我終於說出我一直在想的事。"},{"en":"What I had been thinking means the thought or question that had stayed in my mind.","zh":"“What I had been thinking” 指一直留在我心中的想法或問題。"},{"en":"After a long silence, I finally said what I had been thinking about his apology.","zh":"沉默良久後，我終於說出自己一直在想的關於他道歉的事。"},{"en":"Saying what we have been thinking can feel risky when the topic is personal.","zh":"當話題很個人時，說出一直在想的事可能令人覺得冒險。"},{"en":"This phrase marks the moment when the writer stops avoiding the truth.","zh":"這個說法標示作者不再逃避真相的一刻。"}],"source":"2025 Q2.pdf","sourcePage":4},{"front":"looked down","meaning":"低頭望下","examples":[{"en":"Kelvin looked down and gave a faint smile.","zh":"Kelvin 低頭望下，淡淡一笑。"},{"en":"Looked down means lowered his eyes or face, often because of embarrassment, sadness, or reflection.","zh":"“Looked down” 指垂下眼睛或面部，常因尷尬、傷心或反思。"},{"en":"She looked down when the teacher mentioned her mistake.","zh":"老師提到她的錯誤時，她低頭望下。"},{"en":"Looking down can show that someone is thinking seriously or feeling ashamed.","zh":"低頭望下可以顯示某人正在認真思考或感到羞愧。"},{"en":"This phrase shows Kelvin’s quieter, more humble reaction.","zh":"這個說法顯示 Kelvin 較安靜和謙卑的反應。"}],"source":"2025 Q2.pdf","sourcePage":4},{"front":"gave a faint smile","meaning":"淡淡一笑","examples":[{"en":"Kelvin looked down and gave a faint smile.","zh":"Kelvin 低頭望下，淡淡一笑。"},{"en":"Gave a faint smile means smiled slightly, often with sadness, embarrassment, or gentleness.","zh":"“Gave a faint smile” 指微微一笑，常帶有傷感、尷尬或溫柔。"},{"en":"He gave a faint smile when someone praised the person he used to be angry with.","zh":"有人稱讚他以前生氣的那個人時，他淡淡一笑。"},{"en":"A faint smile can show complicated feelings that are not easy to explain.","zh":"淡淡一笑可以顯示難以解釋的複雜感受。"},{"en":"This phrase suggests Kelvin feels both regretful and calm.","zh":"這個說法暗示 Kelvin 既有悔意，也變得平靜。"}],"source":"2025 Q2.pdf","sourcePage":4},{"front":"changed me","meaning":"改變了我","examples":[{"en":"Kelvin said that last year had changed him.","zh":"Kelvin 說去年改變了他。"},{"en":"Changed me means affected me deeply and made me behave or think differently.","zh":"“Changed me” 指深深影響我，令我的行為或想法變得不同。"},{"en":"Volunteering at the hospital changed me because I learned to be more patient.","zh":"在醫院做義工改變了我，因為我學會更有耐性。"},{"en":"A painful experience can change someone by forcing them to see life differently.","zh":"痛苦經歷可以透過迫使人以不同方式看人生而改變一個人。"},{"en":"This phrase introduces the reason behind Kelvin’s transformation.","zh":"這個說法引出 Kelvin 轉變背後的原因。"}],"source":"2025 Q2.pdf","sourcePage":5},{"front":"one night, during a typhoon","meaning":"在一個颱風夜晚","examples":[{"en":"One night, during a typhoon, Kelvin’s father suddenly collapsed.","zh":"在一個颱風夜晚，Kelvin 的父親突然昏倒。"},{"en":"One night, during a typhoon sets a dangerous time when strong wind and rain were affecting the city.","zh":"“One night, during a typhoon” 交代一個強風大雨影響城市的危險時間。"},{"en":"One night, during a typhoon, the power failed and the streets became empty.","zh":"在一個颱風夜晚，電力中斷，街道變得空蕩。"},{"en":"A crisis during a typhoon feels worse because help may be delayed.","zh":"在颱風中發生危機會感覺更嚴重，因為援助可能延誤。"},{"en":"This phrase creates a tense setting for Kelvin’s turning point.","zh":"這個說法為 Kelvin 的轉捩點營造緊張背景。"}],"source":"2025 Q2.pdf","sourcePage":5},{"front":"suddenly collapsed","meaning":"突然昏倒","examples":[{"en":"Kelvin’s father suddenly collapsed at home.","zh":"Kelvin 的父親在家中突然昏倒。"},{"en":"Suddenly collapsed means fell down or became unable to stand without warning.","zh":"“Suddenly collapsed” 指毫無預警地倒下或不能站立。"},{"en":"The old man suddenly collapsed while waiting for the lift.","zh":"那位老人等升降機時突然昏倒。"},{"en":"When someone suddenly collapses, people nearby must react quickly and calmly.","zh":"當有人突然昏倒，附近的人必須迅速而冷靜地反應。"},{"en":"This phrase marks the start of the emergency.","zh":"這個說法標示緊急情況的開始。"}],"source":"2025 Q2.pdf","sourcePage":5},{"front":"one minute…the next…","meaning":"前一刻……下一刻……","examples":[{"en":"One minute he was talking; the next, he could not move.","zh":"前一刻他還在說話，下一刻他已不能動。"},{"en":"One minute…the next… shows a sudden and frightening change from one state to another.","zh":"“One minute…the next…” 顯示由一種狀態突然可怕地變成另一種狀態。"},{"en":"One minute the classroom was noisy; the next, everyone was silent.","zh":"前一刻課室還很嘈吵，下一刻所有人都沉默了。"},{"en":"This structure makes a change feel immediate and shocking.","zh":"這個結構令轉變感覺即時而震撼。"},{"en":"It is useful when life changes faster than people can prepare for.","zh":"當人生變化快得令人來不及準備時，這個說法很有用。"}],"source":"2025 Q2.pdf","sourcePage":5},{"front":"the right side of his body","meaning":"身體右邊","examples":[{"en":"He could not move the right side of his body.","zh":"他不能移動身體右邊。"},{"en":"The right side of his body means the arm, leg, face, or other body parts on his right.","zh":"“The right side of his body” 指他右邊的手、腳、臉或其他身體部位。"},{"en":"After the accident, she felt pain down the right side of her body.","zh":"意外後，她身體右邊一直疼痛。"},{"en":"Not being able to move one side of the body can signal a serious medical emergency.","zh":"不能移動身體一邊，可能代表嚴重醫療緊急情況。"},{"en":"This phrase makes Kelvin’s father’s condition concrete and frightening.","zh":"這個說法令 Kelvin 父親的情況具體而可怕。"}],"source":"2025 Q2.pdf","sourcePage":5},{"front":"panicked","meaning":"驚慌失措","examples":[{"en":"Kelvin’s mother panicked when his father collapsed.","zh":"Kelvin 的父親昏倒時，他的母親驚慌失措。"},{"en":"Panicked means became extremely frightened and unable to think calmly.","zh":"“Panicked” 指變得非常害怕，無法冷靜思考。"},{"en":"The child panicked when she could not find her parents in the crowd.","zh":"那孩子在人群中找不到父母時驚慌失措。"},{"en":"People may panic in emergencies when they do not know what to do.","zh":"人們在緊急情況中不知道該怎樣做時，可能會驚慌失措。"},{"en":"This word shows how frightening the situation was for Kelvin’s family.","zh":"這個詞顯示 Kelvin 一家的處境多麼可怕。"}],"source":"2025 Q2.pdf","sourcePage":5},{"front":"froze","meaning":"呆住；不知所措","examples":[{"en":"Kelvin froze during the emergency.","zh":"緊急情況中，Kelvin 呆住了。"},{"en":"Froze means suddenly stopped moving or thinking clearly because of fear or shock.","zh":"“Froze” 指因恐懼或震驚而突然停止動作，或無法清楚思考。"},{"en":"I froze when the teacher asked me to speak without preparation.","zh":"老師突然叫我即場發言時，我呆住了。"},{"en":"In a crisis, a person may freeze even if they usually act confident.","zh":"在危機中，即使平時很自信的人也可能不知所措。"},{"en":"This word shows that Kelvin’s old swagger could not help him.","zh":"這個詞顯示 Kelvin 舊日的神氣幫不了他。"}],"source":"2025 Q2.pdf","sourcePage":5},{"front":"lost power","meaning":"停電","examples":[{"en":"The building had lost power during the typhoon.","zh":"大廈在颱風期間停電。"},{"en":"Lost power means the electricity stopped working.","zh":"“Lost power” 指電力停止供應。"},{"en":"The estate lost power after the storm damaged the cables.","zh":"暴風雨損壞電纜後，屋苑停電。"},{"en":"When a building loses power, lifts, lights, and some communication systems may stop working.","zh":"當大廈停電，升降機、燈光和部分通訊系統可能停止運作。"},{"en":"This phrase makes the emergency more difficult and dangerous.","zh":"這個說法令緊急情況更困難和危險。"}],"source":"2025 Q2.pdf","sourcePage":5},{"front":"stopped working","meaning":"停止運作","examples":[{"en":"The lift had stopped working.","zh":"升降機已停止運作。"},{"en":"Stopped working means no longer functioned or operated properly.","zh":"“Stopped working” 指不再正常發揮功能或運作。"},{"en":"My phone stopped working just when I needed to call home.","zh":"我正需要打電話回家時，手機停止運作。"},{"en":"A lift that stops working during an emergency can delay help.","zh":"升降機在緊急情況中停止運作，可能會延誤救援。"},{"en":"This phrase explains why carrying Kelvin’s father downstairs became necessary.","zh":"這個說法解釋為何需要把 Kelvin 的父親抬下樓。"}],"source":"2025 Q2.pdf","sourcePage":5},{"front":"the ambulance was delayed","meaning":"救護車延誤","examples":[{"en":"The ambulance was delayed because of the weather.","zh":"救護車因為天氣而延誤。"},{"en":"The ambulance was delayed means the emergency vehicle arrived later than expected.","zh":"“The ambulance was delayed” 指緊急救護車比預期更遲到達。"},{"en":"The ambulance was delayed by blocked roads after the storm.","zh":"暴風雨後道路受阻，救護車延誤了。"},{"en":"When an ambulance is delayed, people nearby may need to provide help first.","zh":"當救護車延誤時，附近的人可能需要先提供幫助。"},{"en":"This phrase increases the tension of the emergency.","zh":"這個說法增加緊急情況的緊張感。"}],"source":"2025 Q2.pdf","sourcePage":5},{"front":"because of the weather","meaning":"因為天氣","examples":[{"en":"The ambulance was delayed because of the weather.","zh":"救護車因為天氣而延誤。"},{"en":"Because of the weather means due to conditions such as rain, wind, heat, or storms.","zh":"“Because of the weather” 指由於雨、風、高溫或暴風雨等天氣情況。"},{"en":"The school picnic was cancelled because of the weather.","zh":"學校野餐因為天氣而取消。"},{"en":"Emergency services may be slower because of the weather when roads are dangerous.","zh":"當道路危險時，緊急服務可能因為天氣而較慢。"},{"en":"This phrase gives the reason for the delay.","zh":"這個說法交代延誤原因。"}],"source":"2025 Q2.pdf","sourcePage":6},{"front":"for the first time in his life","meaning":"他人生中第一次","examples":[{"en":"For the first time in his life, Kelvin realised his swagger meant nothing.","zh":"Kelvin 人生中第一次意識到他的神氣毫無意義。"},{"en":"For the first time in his life means something happened or was understood for the very first time.","zh":"“For the first time in his life” 指某事或某種理解在人生中第一次出現。"},{"en":"For the first time in his life, he understood how helpless fear could feel.","zh":"他人生中第一次明白無助的恐懼是甚麼感覺。"},{"en":"This phrase highlights a major turning point in someone’s experience.","zh":"這個說法突顯人生經歷中的重大轉捩點。"},{"en":"It shows that Kelvin’s crisis taught him something completely new.","zh":"它顯示 Kelvin 的危機教會他全新的事情。"}],"source":"2025 Q2.pdf","sourcePage":6},{"front":"swagger","meaning":"神氣；自大姿態","examples":[{"en":"Kelvin realised that all his swagger meant nothing in a real crisis.","zh":"Kelvin 意識到他所有的神氣在真正危機中毫無意義。"},{"en":"Swagger is an overconfident way of behaving that tries to look powerful or important.","zh":"“Swagger” 是一種過分自信、試圖顯得有力量或重要的行為方式。"},{"en":"His swagger disappeared when he had to ask for help.","zh":"當他需要求助時，他的神氣消失了。"},{"en":"Swagger may impress people in ordinary moments, but it cannot solve real problems.","zh":"神氣在普通時刻或許能令人留下印象，但不能解決真正問題。"},{"en":"This word describes Kelvin’s old false strength.","zh":"這個詞描述 Kelvin 舊日虛假的強大。"}],"source":"2025 Q2.pdf","sourcePage":6},{"front":"meant nothing","meaning":"毫無意義","examples":[{"en":"His swagger meant nothing in a real crisis.","zh":"他的神氣在真正危機中毫無意義。"},{"en":"Meant nothing means had no value, use, or importance.","zh":"“Meant nothing” 指沒有價值、用途或重要性。"},{"en":"His expensive shoes meant nothing when he had to run through the rain to help someone.","zh":"當他要冒雨跑去幫人時，昂貴鞋子毫無意義。"},{"en":"In emergencies, appearance may mean nothing compared with calm action.","zh":"在緊急情況中，外表與冷靜行動相比可能毫無意義。"},{"en":"This phrase shows Kelvin realising that false confidence is useless.","zh":"這個說法顯示 Kelvin 意識到虛假自信毫無用處。"}],"source":"2025 Q2.pdf","sourcePage":6},{"front":"in a real crisis","meaning":"在真正危機中","examples":[{"en":"Kelvin realised that swagger meant nothing in a real crisis.","zh":"Kelvin 意識到神氣在真正危機中毫無意義。"},{"en":"In a real crisis means during a truly serious and dangerous situation.","zh":"“In a real crisis” 指在真正嚴重和危險的情況中。"},{"en":"In a real crisis, people need calm judgement more than loud confidence.","zh":"在真正危機中，人們需要冷靜判斷，多於響亮自信。"},{"en":"A person’s character is tested in a real crisis because action matters more than image.","zh":"人的品格會在真正危機中受到考驗，因為行動比形象更重要。"},{"en":"This phrase separates everyday showing off from genuine difficulty.","zh":"這個說法把日常逞強與真正困難區分開。"}],"source":"2025 Q2.pdf","sourcePage":6},{"front":"knocked on the door","meaning":"敲門","examples":[{"en":"Then someone knocked on the door.","zh":"然後有人敲門。"},{"en":"Knocked on the door means hit the door lightly to let people inside know someone is there.","zh":"“Knocked on the door” 指輕敲門，讓裏面的人知道有人在外面。"},{"en":"The neighbour knocked on the door when she heard shouting inside.","zh":"鄰居聽到屋內有人大叫時便敲門。"},{"en":"A knock on the door during an emergency can bring unexpected help.","zh":"緊急情況中的敲門聲可以帶來意想不到的幫助。"},{"en":"This phrase introduces Mr Leung’s arrival.","zh":"這個說法引出梁先生的到來。"}],"source":"2025 Q2.pdf","sourcePage":6},{"front":"elderly security guard","meaning":"年長保安員","examples":[{"en":"Mr Leung was the elderly security guard from Kelvin’s estate.","zh":"梁先生是 Kelvin 屋苑的年長保安員。"},{"en":"An elderly security guard is an older person whose job is to protect a building or estate.","zh":"年長保安員是年紀較大、負責保護大廈或屋苑的人。"},{"en":"The elderly security guard checked the lobby every night.","zh":"那位年長保安員每晚巡查大堂。"},{"en":"People may overlook an elderly security guard, but he may carry deep experience and courage.","zh":"人們可能忽視年長保安員，但他可能有豐富經驗和勇氣。"},{"en":"In the story, the elderly security guard becomes the strongest person in the crisis.","zh":"在故事中，年長保安員成為危機中最強大的人。"}],"source":"2025 Q2.pdf","sourcePage":6},{"front":"from their estate","meaning":"來自他們屋苑","examples":[{"en":"Mr Leung was the security guard from their estate.","zh":"梁先生是來自他們屋苑的保安員。"},{"en":"From their estate means connected with or working in the housing estate where they lived.","zh":"“From their estate” 指與他們居住的屋苑有關，或在那裏工作。"},{"en":"The cleaner from their estate knew many families by name.","zh":"來自他們屋苑的清潔工認得許多家庭的名字。"},{"en":"Someone from their estate may seem ordinary until a crisis reveals their kindness.","zh":"來自他們屋苑的人可能看似普通，直到危機顯露出他的善良。"},{"en":"This phrase shows that help came from someone close to home.","zh":"這個說法顯示幫助來自家附近的人。"}],"source":"2025 Q2.pdf","sourcePage":6},{"front":"admitted that","meaning":"承認","examples":[{"en":"Kelvin admitted that he had once ignored Mr Leung.","zh":"Kelvin 承認他曾經忽視梁先生。"},{"en":"Admitted that means accepted or confessed that something was true.","zh":"“Admitted that” 指接受或坦白某事是真的。"},{"en":"She admitted that she had judged her classmate unfairly.","zh":"她承認自己曾不公平地評價同學。"},{"en":"Admitting a past mistake is often the first step towards change.","zh":"承認過去的錯誤，常是改變的第一步。"},{"en":"This phrase shows Kelvin’s honesty about his old behaviour.","zh":"這個說法顯示 Kelvin 對自己舊日行為的誠實。"}],"source":"2025 Q2.pdf","sourcePage":6},{"front":"before that night","meaning":"在那晚之前","examples":[{"en":"Before that night, Kelvin would probably not have noticed him.","zh":"在那晚之前，Kelvin 大概不會留意到他。"},{"en":"Before that night means during the time before the important night being described.","zh":"“Before that night” 指在所描述的重要夜晚之前的一段時間。"},{"en":"Before that night, I had never thought seriously about emergency workers.","zh":"在那晚之前，我從未認真想過緊急救援人員。"},{"en":"This phrase marks a clear divide between Kelvin’s old attitude and new understanding.","zh":"這個說法清楚劃分 Kelvin 的舊態度和新理解。"},{"en":"It shows that the typhoon night became a turning point.","zh":"它顯示颱風夜成為一個轉捩點。"}],"source":"2025 Q2.pdf","sourcePage":6},{"front":"not even have noticed","meaning":"甚至不會留意到","examples":[{"en":"Kelvin would probably not even have noticed Mr Leung before.","zh":"Kelvin 以前大概甚至不會留意到梁先生。"},{"en":"Not even have noticed means would have failed completely to pay attention to someone or something.","zh":"“Not even have noticed” 指完全沒有留意某人或某事。"},{"en":"Before volunteering, he would not even have noticed the cleaner working late.","zh":"做義工前，他甚至不會留意到那位工作到很晚的清潔工。"},{"en":"This phrase shows how careless or proud someone used to be.","zh":"這個說法顯示某人以前多麼粗心或自傲。"},{"en":"It emphasises Kelvin’s past blindness towards quiet people.","zh":"它強調 Kelvin 過去對安靜的人視而不見。"}],"source":"2025 Q2.pdf","sourcePage":7},{"front":"looked down on","meaning":"看不起","examples":[{"en":"Kelvin had always looked down on people he considered weak.","zh":"Kelvin 一直看不起他認為軟弱的人。"},{"en":"Looked down on means thought someone was less important, less capable, or less worthy of respect.","zh":"“Looked down on” 指認為某人較不重要、較無能力或不值得尊重。"},{"en":"Some students looked down on classmates who spoke softly.","zh":"有些學生看不起說話細聲的同學。"},{"en":"Looking down on others often reveals insecurity rather than real strength.","zh":"看不起別人常顯示不安，而不是真正強大。"},{"en":"This phrase describes Kelvin’s old arrogance.","zh":"這個說法描述 Kelvin 舊日的傲慢。"}],"source":"2025 Q2.pdf","sourcePage":7},{"front":"considered weak","meaning":"認為是軟弱的","examples":[{"en":"Kelvin looked down on people he considered weak or unimportant.","zh":"Kelvin 看不起他認為是軟弱或不重要的人。"},{"en":"Considered weak means judged someone as lacking strength, courage, or importance.","zh":"“Considered weak” 指判斷某人缺乏力量、勇氣或重要性。"},{"en":"He considered quiet classmates weak because they did not answer back.","zh":"他認為安靜的同學很軟弱，因為他們不反駁。"},{"en":"People may be wrongly considered weak when they are simply gentle or patient.","zh":"人們可能被錯誤地認為軟弱，其實他們只是溫柔或有耐性。"},{"en":"This phrase shows how Kelvin misread kindness and quietness.","zh":"這個說法顯示 Kelvin 如何誤解善良和安靜。"}],"source":"2025 Q2.pdf","sourcePage":7},{"front":"quiet or unimportant","meaning":"安靜或不重要","examples":[{"en":"Kelvin used to ignore people he considered quiet or unimportant.","zh":"Kelvin 以前會忽視他認為安靜或不重要的人。"},{"en":"Quiet or unimportant describes people who seem soft-spoken, ordinary, or easy to overlook.","zh":"“Quiet or unimportant” 形容看似沉默、普通或容易被忽略的人。"},{"en":"The quiet or unimportant worker became the person everyone depended on during the blackout.","zh":"那位看似安靜或不重要的工人在停電時成為大家依靠的人。"},{"en":"People who seem quiet or unimportant may show great strength when help is needed.","zh":"看似安靜或不重要的人，在需要幫忙時可能展現巨大力量。"},{"en":"This phrase challenges Kelvin’s old way of judging people.","zh":"這個說法挑戰 Kelvin 舊日評價別人的方式。"}],"source":"2025 Q2.pdf","sourcePage":7},{"front":"what Kelvin could not","meaning":"Kelvin 做不到的事","examples":[{"en":"Mr Leung did what Kelvin could not.","zh":"梁先生做了 Kelvin 做不到的事。"},{"en":"What Kelvin could not means the action Kelvin was unable to do in that moment.","zh":"“What Kelvin could not” 指 Kelvin 在那一刻無法做到的行動。"},{"en":"In the emergency, the nurse did what the frightened family could not.","zh":"在緊急情況中，護士做了受驚家人做不到的事。"},{"en":"This phrase highlights the gap between Kelvin’s image of strength and real ability.","zh":"這個說法突顯 Kelvin 的強大形象與真正能力之間的差距。"},{"en":"It shows why Mr Leung’s actions changed Kelvin’s view of strength.","zh":"它顯示為何梁先生的行動改變了 Kelvin 對力量的看法。"}],"source":"2025 Q2.pdf","sourcePage":7},{"front":"checked his father’s breathing","meaning":"檢查他父親的呼吸","examples":[{"en":"Mr Leung checked Kelvin’s father’s breathing.","zh":"梁先生檢查 Kelvin 父親的呼吸。"},{"en":"Checked his father’s breathing means examined whether his father was still breathing normally.","zh":"“Checked his father’s breathing” 指查看他的父親是否仍然正常呼吸。"},{"en":"The first-aid volunteer checked the injured man’s breathing before calling for help.","zh":"急救義工在求助前檢查受傷男子的呼吸。"},{"en":"Checking breathing is important because it tells helpers how urgent the situation is.","zh":"檢查呼吸很重要，因為它能告訴施救者情況有多緊急。"},{"en":"This phrase shows Mr Leung’s calm and practical response.","zh":"這個說法顯示梁先生冷靜而實際的反應。"}],"source":"2025 Q2.pdf","sourcePage":7},{"front":"called the ambulance again","meaning":"再次致電救護車","examples":[{"en":"Mr Leung called the ambulance again.","zh":"梁先生再次致電救護車。"},{"en":"Called the ambulance again means phoned emergency medical services another time.","zh":"“Called the ambulance again” 指再次致電緊急醫療服務。"},{"en":"When the patient’s condition worsened, the neighbour called the ambulance again.","zh":"病人情況惡化時，鄰居再次致電救護車。"},{"en":"Calling again can be necessary if help is delayed or new information is available.","zh":"如果救援延誤或有新資訊，再次致電可能是必要的。"},{"en":"This phrase shows persistence during an emergency.","zh":"這個說法顯示緊急情況中的堅持。"}],"source":"2025 Q2.pdf","sourcePage":7},{"front":"paramedics","meaning":"救護員","examples":[{"en":"The paramedics finally arrived during the typhoon.","zh":"救護員終於在颱風中到達。"},{"en":"Paramedics are trained medical workers who give emergency care before or during transport to hospital.","zh":"救護員是受過訓練的醫療人員，在送院前或途中提供緊急護理。"},{"en":"The paramedics checked the patient’s pulse and prepared him for the ambulance.","zh":"救護員檢查病人的脈搏，並準備把他送上救護車。"},{"en":"Paramedics are important because they provide urgent care outside the hospital.","zh":"救護員很重要，因為他們在醫院以外提供緊急護理。"},{"en":"This word marks the arrival of professional medical help.","zh":"這個詞標示專業醫療援助到來。"}],"source":"2025 Q2.pdf","sourcePage":7},{"front":"helped carry","meaning":"幫忙抬","examples":[{"en":"Mr Leung helped carry Kelvin’s father down the stairs.","zh":"梁先生幫忙把 Kelvin 的父親抬下樓梯。"},{"en":"Helped carry means assisted in lifting and moving someone or something.","zh":"“Helped carry” 指協助抬起並移動某人或某物。"},{"en":"Two neighbours helped carry the injured child to a safer place.","zh":"兩位鄰居幫忙把受傷孩子抬到較安全地方。"},{"en":"Helping carry a sick person requires strength, care, and coordination.","zh":"幫忙抬病人需要力量、細心和協調。"},{"en":"This phrase shows Mr Leung taking physical action, not only giving advice.","zh":"這個說法顯示梁先生不只是給意見，而是親身行動。"}],"source":"2025 Q2.pdf","sourcePage":7},{"front":"down seventeen flights of stairs","meaning":"走下十七層樓梯","examples":[{"en":"They carried Kelvin’s father down seventeen flights of stairs.","zh":"他們把 Kelvin 的父親抬下十七層樓梯。"},{"en":"Down seventeen flights of stairs means from a high floor down many levels by stairway.","zh":"“Down seventeen flights of stairs” 指從高樓層經樓梯下到很多層。"},{"en":"During the blackout, residents walked down seventeen flights of stairs with torches.","zh":"停電期間，居民拿着電筒走下十七層樓梯。"},{"en":"Carrying someone down so many stairs is physically difficult and risky.","zh":"把人抬下這麼多層樓梯既辛苦又有風險。"},{"en":"This phrase makes Mr Leung’s effort feel concrete and impressive.","zh":"這個說法令梁先生的努力具體而令人佩服。"}],"source":"2025 Q2.pdf","sourcePage":7},{"front":"out of order","meaning":"壞了；不能使用","examples":[{"en":"The lift was still out of order.","zh":"升降機仍然壞了，不能使用。"},{"en":"Out of order means not working properly and unavailable for use.","zh":"“Out of order” 指不能正常運作，因此不能使用。"},{"en":"The vending machine was out of order, so students could not buy drinks.","zh":"自動售賣機壞了，所以學生買不到飲品。"},{"en":"When a lift is out of order, elderly or injured people may face serious difficulty.","zh":"當升降機壞了，長者或傷者可能面對嚴重困難。"},{"en":"This phrase explains why the stairs had to be used.","zh":"這個說法解釋為何必須使用樓梯。"}],"source":"2025 Q2.pdf","sourcePage":8},{"front":"even then","meaning":"即使那樣","examples":[{"en":"Even then, Mr Leung did not leave.","zh":"即使那樣，梁先生仍沒有離開。"},{"en":"Even then means despite everything that had already happened.","zh":"“Even then” 指儘管之前已發生那麼多事。"},{"en":"The work was tiring and dangerous; even then, the volunteer stayed.","zh":"工作又累又危險；即使那樣，義工仍留下來。"},{"en":"This phrase emphasises that someone continued helping beyond what was expected.","zh":"這個說法強調某人繼續提供超出預期的幫助。"},{"en":"It shows Mr Leung’s kindness and responsibility.","zh":"它顯示梁先生的善良和責任感。"}],"source":"2025 Q2.pdf","sourcePage":8},{"front":"emergency room","meaning":"急症室","examples":[{"en":"Kelvin and his mother sat outside the emergency room in shock.","zh":"Kelvin 和母親驚魂未定地坐在急症室外。"},{"en":"An emergency room is the hospital department where urgent medical cases are treated.","zh":"急症室是醫院中處理緊急醫療個案的部門。"},{"en":"Families waited outside the emergency room for news from the doctor.","zh":"家屬在急症室外等候醫生消息。"},{"en":"The emergency room is often connected with fear, waiting, and uncertainty.","zh":"急症室常與恐懼、等待和不確定性相連。"},{"en":"This phrase places Kelvin at the emotional centre of the crisis.","zh":"這個說法把 Kelvin 放在危機的情感中心。"}],"source":"2025 Q2.pdf","sourcePage":8},{"front":"in shock","meaning":"驚魂未定","examples":[{"en":"Kelvin and his mother sat outside the emergency room in shock.","zh":"Kelvin 和母親驚魂未定地坐在急症室外。"},{"en":"In shock means feeling stunned, frightened, or unable to react normally after something serious happens.","zh":"“In shock” 指嚴重事情發生後感到震驚、害怕或無法正常反應。"},{"en":"After the accident, the driver sat by the road in shock.","zh":"意外後，司機驚魂未定地坐在路邊。"},{"en":"People in shock may speak very little because their minds are still processing what happened.","zh":"驚魂未定的人可能很少說話，因為腦中仍在處理發生的事。"},{"en":"This phrase shows the emotional force of the typhoon night.","zh":"這個說法顯示颱風夜帶來的情感衝擊。"}],"source":"2025 Q2.pdf","sourcePage":8},{"front":"stayed with them","meaning":"留下來陪著他們","examples":[{"en":"Mr Leung stayed with them until early morning.","zh":"梁先生留下來陪着他們，直到清晨。"},{"en":"Stayed with them means remained beside them to offer support and company.","zh":"“Stayed with them” 指留在他們身邊，提供支持和陪伴。"},{"en":"The neighbour stayed with the family until the doctor gave an update.","zh":"鄰居留下來陪着那家人，直到醫生提供最新消息。"},{"en":"Staying with people after a crisis can comfort them even without many words.","zh":"危機後留下來陪伴別人，即使沒有很多說話，也能安慰他們。"},{"en":"This phrase shows that Mr Leung’s help continued beyond the emergency action.","zh":"這個說法顯示梁先生的幫助不止於緊急行動。"}],"source":"2025 Q2.pdf","sourcePage":8},{"front":"barely knew us","meaning":"幾乎不認識我們","examples":[{"en":"Kelvin said that Mr Leung barely knew his family.","zh":"Kelvin 說梁先生幾乎不認識他們一家。"},{"en":"Barely knew us means knew us only a little or hardly at all.","zh":"“Barely knew us” 指只很少認識我們，甚至幾乎完全不認識。"},{"en":"The volunteer barely knew us, but she still waited until help arrived.","zh":"那位義工幾乎不認識我們，但她仍然等到援助到來。"},{"en":"Help from someone who barely knows us can feel especially moving.","zh":"來自幾乎不認識我們的人的幫助，會特別令人感動。"},{"en":"This phrase makes Mr Leung’s kindness seem even more generous.","zh":"這個說法令梁先生的善意顯得更加慷慨。"}],"source":"2025 Q2.pdf","sourcePage":8},{"front":"the moment everything changed","meaning":"一切改變的時刻","examples":[{"en":"That was the moment everything changed.","zh":"那就是一切改變的時刻。"},{"en":"The moment everything changed is the specific time when someone’s life, thinking, or behaviour began to become different.","zh":"“The moment everything changed” 是某人的人生、想法或行為開始變得不同的特定時刻。"},{"en":"Losing the competition was the moment everything changed because she finally learned humility.","zh":"輸掉比賽是一切改變的時刻，因為她終於學會謙卑。"},{"en":"A turning point often feels ordinary at first but later explains a major change.","zh":"轉捩點起初可能看似普通，但之後會解釋重大改變。"},{"en":"This phrase identifies the central turning point in Kelvin’s story.","zh":"這個說法指出 Kelvin 故事中的核心轉捩點。"}],"source":"2025 Q2.pdf","sourcePage":8},{"front":"hospital corridor","meaning":"醫院走廊","examples":[{"en":"Kelvin sat in the hospital corridor and saw himself clearly.","zh":"Kelvin 坐在醫院走廊，清楚看見自己。"},{"en":"A hospital corridor is a long passage inside a hospital connecting rooms and wards.","zh":"醫院走廊是醫院內連接房間和病房的長通道。"},{"en":"Families waited quietly in the hospital corridor outside the emergency room.","zh":"家屬安靜地在急症室外的醫院走廊等候。"},{"en":"A hospital corridor can feel lonely because people are often waiting for difficult news.","zh":"醫院走廊可能令人感到孤單，因為人們常在那裏等候艱難消息。"},{"en":"This phrase creates a quiet setting for Kelvin’s self-reflection.","zh":"這個說法為 Kelvin 的自我反思營造安靜場景。"}],"source":"2025 Q2.pdf","sourcePage":8},{"front":"saw himself clearly","meaning":"清楚看見自己","examples":[{"en":"Kelvin suddenly saw himself clearly.","zh":"Kelvin 突然清楚看見自己。"},{"en":"Saw himself clearly means understood his own behaviour, weakness, or character honestly.","zh":"“Saw himself clearly” 指誠實地理解自己的行為、弱點或品格。"},{"en":"After hurting his friend, he finally saw himself clearly.","zh":"傷害朋友後，他終於清楚看見自己。"},{"en":"People often see themselves clearly when a crisis strips away excuses.","zh":"當危機剝走藉口時，人們常會清楚看見自己。"},{"en":"This phrase shows Kelvin facing the truth about who he had been.","zh":"這個說法顯示 Kelvin 面對自己曾經是怎樣的人。"}],"source":"2025 Q2.pdf","sourcePage":8},{"front":"spent years trying to","meaning":"花了多年試圖","examples":[{"en":"Kelvin had spent years trying to look powerful.","zh":"Kelvin 花了多年試圖看起來強大。"},{"en":"Spent years trying to means used a long time making an effort to do something.","zh":"“Spent years trying to” 指用了很長時間努力做某事。"},{"en":"She spent years trying to please everyone before learning to be honest.","zh":"她花了多年試圖討好所有人，後來才學會誠實。"},{"en":"Spending years trying to look strong can hide fear or insecurity.","zh":"花多年試圖顯得強大，可能是在隱藏恐懼或不安。"},{"en":"This phrase shows that Kelvin’s old image was built over time.","zh":"這個說法顯示 Kelvin 舊日形象是長時間建立出來的。"}],"source":"2025 Q2.pdf","sourcePage":8},{"front":"look powerful","meaning":"看起來強大","examples":[{"en":"Kelvin had tried to look powerful by humiliating others.","zh":"Kelvin 曾試圖透過羞辱別人令自己看起來強大。"},{"en":"To look powerful means to appear strong, important, or in control.","zh":"“Look powerful” 指外表上顯得強、有地位或能控制局面。"},{"en":"Some students try to look powerful by speaking loudly over others.","zh":"有些學生透過大聲壓過別人來試圖看起來強大。"},{"en":"Looking powerful is not the same as being truly strong or kind.","zh":"看起來強大並不等於真正堅強或善良。"},{"en":"This phrase shows Kelvin’s false idea of strength.","zh":"這個說法顯示 Kelvin 對力量的錯誤理解。"}],"source":"2025 Q2.pdf","sourcePage":9},{"front":"humiliating others","meaning":"羞辱別人","examples":[{"en":"Kelvin had tried to look powerful by humiliating others.","zh":"Kelvin 曾試圖透過羞辱別人令自己看起來強大。"},{"en":"Humiliating others means making other people feel ashamed, embarrassed, or small.","zh":"“Humiliating others” 指令別人感到羞愧、尷尬或渺小。"},{"en":"Laughing at a classmate’s mistake in public is humiliating others.","zh":"在公開場合嘲笑同學的錯誤，就是羞辱別人。"},{"en":"People who humiliate others may feel powerful for a moment but damage trust deeply.","zh":"羞辱別人的人可能一時感到強大，卻會深深破壞信任。"},{"en":"This phrase shows the harm Kelvin caused before he changed.","zh":"這個說法顯示 Kelvin 改變前造成的傷害。"}],"source":"2025 Q2.pdf","sourcePage":9},{"front":"real trouble","meaning":"真正的麻煩；真正危機","examples":[{"en":"When real trouble came, Mr Leung was the strongest person in the room.","zh":"當真正危機來臨時，梁先生是房間裏最強大的人。"},{"en":"Real trouble means a serious problem that cannot be solved by showing off or pretending.","zh":"“Real trouble” 指不能靠逞強或假裝解決的嚴重問題。"},{"en":"When real trouble came during the fire alarm, the quiet teacher stayed calm.","zh":"火警鐘響起、真正麻煩來臨時，那位安靜的老師保持冷靜。"},{"en":"Real trouble reveals who can actually help, not who only looks confident.","zh":"真正危機會顯示誰真的能幫忙，而不是誰只是看起來自信。"},{"en":"This phrase contrasts Kelvin’s old bullying with Mr Leung’s real strength.","zh":"這個說法把 Kelvin 舊日欺凌與梁先生真正的力量作對比。"}],"source":"2025 Q2.pdf","sourcePage":9},{"front":"the strongest person in the room","meaning":"房間裏最強大的人","examples":[{"en":"The strongest person in the room was the old man Kelvin had once ignored.","zh":"房間裏最強大的人，是 Kelvin 曾經忽視的那位老人。"},{"en":"The strongest person in the room means the person with the greatest courage, calmness, or usefulness in that situation.","zh":"“The strongest person in the room” 指在該情況中最有勇氣、冷靜或能幫上忙的人。"},{"en":"During the emergency, the strongest person in the room was the quiet nurse.","zh":"緊急情況中，房間裏最強大的人是那位安靜的護士。"},{"en":"Strength may belong to the person who acts calmly, not the person who talks loudly.","zh":"力量可能屬於冷靜行動的人，而不是說話最大聲的人。"},{"en":"This phrase changes Kelvin’s understanding of what strength means.","zh":"這個說法改變 Kelvin 對力量的理解。"}],"source":"2025 Q2.pdf","sourcePage":9},{"front":"survived","meaning":"活了下來","examples":[{"en":"Kelvin’s father survived, though recovery was slow.","zh":"Kelvin 的父親活了下來，雖然康復過程緩慢。"},{"en":"Survived means continued to live after danger, illness, or a serious event.","zh":"“Survived” 指在危險、疾病或嚴重事件後繼續活着。"},{"en":"The patient survived the operation and slowly regained strength.","zh":"病人手術後活了下來，並慢慢恢復力量。"},{"en":"Surviving a crisis does not mean life returns to normal immediately.","zh":"活過危機不代表生活立即回復正常。"},{"en":"This word brings relief while still leaving room for difficulty.","zh":"這個詞帶來安心，同時仍保留困難。"}],"source":"2025 Q2.pdf","sourcePage":9},{"front":"recovery was slow","meaning":"康復過程緩慢","examples":[{"en":"His father survived, though recovery was slow.","zh":"他的父親活了下來，雖然康復過程緩慢。"},{"en":"Recovery was slow means the process of becoming healthy again took a long time.","zh":"“Recovery was slow” 指恢復健康的過程需時很長。"},{"en":"After the injury, recovery was slow because she needed months of therapy.","zh":"受傷後，她因需要數月治療，康復過程緩慢。"},{"en":"Slow recovery can test a family’s patience, time, and love.","zh":"緩慢康復會考驗家庭的耐性、時間和愛。"},{"en":"This phrase shows that the crisis continued after the hospital emergency.","zh":"這個說法顯示危機在醫院急救後仍然持續。"}],"source":"2025 Q2.pdf","sourcePage":9},{"front":"over the following months","meaning":"在接下來幾個月","examples":[{"en":"Over the following months, Kelvin accompanied his father to physiotherapy.","zh":"在接下來幾個月，Kelvin 陪父親去做物理治療。"},{"en":"Over the following months means during the months after the event just described.","zh":"“Over the following months” 指在剛才描述的事件之後幾個月中。"},{"en":"Over the following months, she visited her grandmother every weekend.","zh":"在接下來幾個月，她每個週末探望祖母。"},{"en":"This phrase shows that change happened gradually, not only in one night.","zh":"這個說法顯示改變是逐漸發生的，不只是那一晚。"},{"en":"It connects the crisis with Kelvin’s continued responsibility.","zh":"它把危機與 Kelvin 持續承擔責任連接起來。"}],"source":"2025 Q2.pdf","sourcePage":9},{"front":"accompanied him to","meaning":"陪同他去……","examples":[{"en":"Kelvin accompanied his father to physiotherapy sessions.","zh":"Kelvin 陪同父親去物理治療療程。"},{"en":"Accompanied him to means went with him to a place to support, help, or keep him company.","zh":"“Accompanied him to” 指陪他去某個地方，以支持、幫助或陪伴他。"},{"en":"I accompanied my grandfather to the clinic because he walked slowly.","zh":"我陪同祖父去診所，因為他走得很慢。"},{"en":"Accompanying someone to treatment shows care through time and presence.","zh":"陪同某人去治療，是透過時間和陪伴表達關心。"},{"en":"This phrase shows Kelvin becoming dependable in daily life.","zh":"這個說法顯示 Kelvin 在日常生活中變得可靠。"}],"source":"2025 Q2.pdf","sourcePage":9},{"front":"physiotherapy sessions","meaning":"物理治療療程","examples":[{"en":"Kelvin accompanied his father to physiotherapy sessions.","zh":"Kelvin 陪父親去物理治療療程。"},{"en":"Physiotherapy sessions are treatment meetings that help patients recover movement, strength, and physical function.","zh":"物理治療療程是幫助病人恢復活動能力、力量和身體功能的治療時段。"},{"en":"After the stroke, his father attended physiotherapy sessions twice a week.","zh":"中風後，他的父親每星期接受兩次物理治療療程。"},{"en":"Physiotherapy sessions require patience because progress may be slow.","zh":"物理治療療程需要耐性，因為進步可能很慢。"},{"en":"This phrase shows the long practical work behind recovery.","zh":"這個說法顯示康復背後長期而實際的努力。"}],"source":"2025 Q2.pdf","sourcePage":9},{"front":"helped more at home","meaning":"在家中幫忙更多","examples":[{"en":"Kelvin helped more at home after his father became ill.","zh":"父親生病後，Kelvin 在家中幫忙更多。"},{"en":"Helped more at home means took on more household duties or family responsibilities.","zh":"“Helped more at home” 指承擔更多家務或家庭責任。"},{"en":"After his mother injured her hand, he helped more at home by cooking dinner.","zh":"母親弄傷手後，他在家中幫忙更多，負責煮晚飯。"},{"en":"Helping more at home can show maturity because care becomes part of daily routine.","zh":"在家中幫忙更多可以顯示成熟，因為照顧成為日常習慣。"},{"en":"This phrase shows Kelvin’s change through ordinary actions.","zh":"這個說法透過普通行動顯示 Kelvin 的改變。"}],"source":"2025 Q2.pdf","sourcePage":9},{"front":"began volunteering","meaning":"開始做義工","examples":[{"en":"Kelvin began volunteering at a community centre on weekends.","zh":"Kelvin 開始在週末到社區中心做義工。"},{"en":"Began volunteering means started giving time and effort to help others without being paid.","zh":"“Began volunteering” 指開始無償付出時間和努力去幫助別人。"},{"en":"She began volunteering at an animal shelter after school.","zh":"她放學後開始在動物收容所做義工。"},{"en":"Volunteering can change people because they meet others’ needs directly.","zh":"做義工可以改變人，因為人會直接接觸別人的需要。"},{"en":"This phrase shows Kelvin moving from selfishness towards service.","zh":"這個說法顯示 Kelvin 由自私走向服務他人。"}],"source":"2025 Q2.pdf","sourcePage":10},{"front":"community centre","meaning":"社區中心","examples":[{"en":"Kelvin volunteered at a community centre on weekends.","zh":"Kelvin 週末在社區中心做義工。"},{"en":"A community centre is a local place where residents can join activities, receive help, or meet others.","zh":"社區中心是居民可以參加活動、獲得幫助或認識他人的本地場所。"},{"en":"The community centre offers homework classes and elderly support programmes.","zh":"社區中心提供功課班和長者支援服務。"},{"en":"Community centres help people connect across age, income, and background.","zh":"社區中心幫助不同年齡、收入和背景的人建立連繫。"},{"en":"This phrase shows where Kelvin learns to serve others.","zh":"這個說法顯示 Kelvin 學習服務別人的地方。"}],"source":"2025 Q2.pdf","sourcePage":10},{"front":"on weekends","meaning":"在週末","examples":[{"en":"Kelvin began volunteering on weekends.","zh":"Kelvin 開始在週末做義工。"},{"en":"On weekends means on Saturdays and Sundays.","zh":"“On weekends” 指在星期六和星期日。"},{"en":"Many students work part-time or join activities on weekends.","zh":"許多學生在週末兼職或參加活動。"},{"en":"Volunteering on weekends shows commitment because it uses personal free time.","zh":"在週末做義工顯示承諾，因為這使用了個人空閒時間。"},{"en":"This phrase tells us when Kelvin continued his service.","zh":"這個說法告訴我們 Kelvin 何時持續服務。"}],"source":"2025 Q2.pdf","sourcePage":10},{"front":"a way of apologising","meaning":"一種道歉的方式","examples":[{"en":"At first, volunteering was almost a way of apologising.","zh":"起初，做義工幾乎是一種道歉的方式。"},{"en":"A way of apologising means an action used to express regret, even without saying sorry directly.","zh":"“A way of apologising” 指用行動表達悔意，即使沒有直接說對不起。"},{"en":"Helping the class clean up was his way of apologising for the trouble he had caused.","zh":"他幫全班收拾，是為自己造成的麻煩道歉的一種方式。"},{"en":"Sometimes people apologise through changed behaviour rather than words.","zh":"有時人們不是用說話，而是用改變了的行為來道歉。"},{"en":"This phrase shows Kelvin trying to repair his past indirectly.","zh":"這個說法顯示 Kelvin 正嘗試間接修補過去。"}],"source":"2025 Q2.pdf","sourcePage":10},{"front":"became a habit","meaning":"變成習慣","examples":[{"en":"Volunteering later became a habit.","zh":"做義工後來變成習慣。"},{"en":"Became a habit means turned into something done regularly and naturally.","zh":"“Became a habit” 指變成定期而自然會做的事情。"},{"en":"Reading before bed became a habit after I did it for a month.","zh":"睡前閱讀做了一個月後變成習慣。"},{"en":"A helpful action becomes more meaningful when it becomes a habit instead of a one-time act.","zh":"當幫人的行動變成習慣，而不是一次性行為，它會更有意義。"},{"en":"This phrase shows Kelvin’s change becoming stable.","zh":"這個說法顯示 Kelvin 的改變變得穩定。"}],"source":"2025 Q2.pdf","sourcePage":10},{"front":"helped children with homework","meaning":"幫助小朋友做功課","examples":[{"en":"Kelvin helped children with homework at the community centre.","zh":"Kelvin 在社區中心幫助小朋友做功課。"},{"en":"Helped children with homework means guided younger students as they completed schoolwork.","zh":"“Helped children with homework” 指指導年幼學生完成學校功課。"},{"en":"The volunteer helped children with homework by explaining difficult maths questions.","zh":"義工透過解釋困難數學題，幫助小朋友做功課。"},{"en":"Helping children with homework requires patience because each child learns differently.","zh":"幫助小朋友做功課需要耐性，因為每個孩子學習方式不同。"},{"en":"This phrase shows Kelvin using his time to support weaker learners instead of mocking them.","zh":"這個說法顯示 Kelvin 用時間支持較弱的學習者，而不是嘲笑他們。"}],"source":"2025 Q2.pdf","sourcePage":10},{"front":"accompanied elderly people to appointments","meaning":"陪長者赴約","examples":[{"en":"Kelvin accompanied elderly people to appointments.","zh":"Kelvin 陪長者赴約。"},{"en":"Accompanied elderly people to appointments means went with older people to medical or service meetings to help them.","zh":"“Accompanied elderly people to appointments” 指陪年長人士去醫療或服務預約，並提供幫助。"},{"en":"Volunteers accompanied elderly people to clinic appointments on rainy days.","zh":"雨天時，義工陪長者去診所赴約。"},{"en":"This work is helpful because older people may feel anxious travelling alone.","zh":"這項工作有幫助，因為長者獨自出行可能會感到焦慮。"},{"en":"This phrase shows Kelvin learning care through patient, practical service.","zh":"這個說法顯示 Kelvin 透過有耐性的實際服務學習關心。"}],"source":"2025 Q2.pdf","sourcePage":10},{"front":"discovered that","meaning":"發現","examples":[{"en":"Kelvin discovered that real maturity was about being dependable.","zh":"Kelvin 發現真正成熟是關於可靠。"},{"en":"Discovered that means came to understand something, often after experience.","zh":"“Discovered that” 指通常經歷某事後明白某個道理。"},{"en":"She discovered that leadership was more about listening than giving orders.","zh":"她發現領導更關乎聆聽，而不是發號施令。"},{"en":"People often discover important truths after facing difficulty.","zh":"人們常在面對困難後發現重要真相。"},{"en":"This phrase introduces Kelvin’s new understanding of maturity.","zh":"這個說法引出 Kelvin 對成熟的新理解。"}],"source":"2025 Q2.pdf","sourcePage":10},{"front":"real maturity","meaning":"真正成熟","examples":[{"en":"Kelvin discovered what real maturity meant.","zh":"Kelvin 發現真正成熟的意思。"},{"en":"Real maturity means genuine emotional growth, responsibility, and the ability to care for others.","zh":"真正成熟指真實的情感成長、責任感，以及照顧別人的能力。"},{"en":"Real maturity is shown when a person admits mistakes and changes behaviour.","zh":"當一個人承認錯誤並改變行為時，就顯示真正成熟。"},{"en":"Real maturity is not about looking older, but acting with responsibility.","zh":"真正成熟不是看起來年長，而是負責任地行動。"},{"en":"This phrase shows the deeper lesson Kelvin learned.","zh":"這個說法顯示 Kelvin 學到的深層教訓。"}],"source":"2025 Q2.pdf","sourcePage":10},{"front":"being noticed","meaning":"被注意","examples":[{"en":"Real maturity was not about being noticed.","zh":"真正成熟不是關於被注意。"},{"en":"Being noticed means being seen, recognised, or given attention by others.","zh":"“Being noticed” 指被別人看見、認出或給予注意。"},{"en":"Some students act loudly because they want being noticed more than being understood.","zh":"有些學生表現得很大聲，因為他們想被注意多於被理解。"},{"en":"Wanting to be noticed can become unhealthy if it leads someone to hurt others.","zh":"如果渴望被注意令人傷害別人，這種需要就可能變得不健康。"},{"en":"This phrase contrasts attention-seeking with real maturity.","zh":"這個說法把尋求注意與真正成熟作對比。"}],"source":"2025 Q2.pdf","sourcePage":10},{"front":"being dependable","meaning":"可靠；值得依靠","examples":[{"en":"Real maturity was about being dependable.","zh":"真正成熟是關於可靠。"},{"en":"Being dependable means being reliable enough for others to trust and rely on.","zh":"“Being dependable” 指可靠到讓別人能信任和依靠。"},{"en":"A dependable friend keeps promises and shows up when help is needed.","zh":"可靠的朋友會守承諾，並在需要幫忙時出現。"},{"en":"Kelvin became dependable when he helped his father and served others regularly.","zh":"Kelvin 在幫助父親和定期服務別人時變得可靠。"},{"en":"This phrase shows maturity as quiet responsibility.","zh":"這個說法把成熟呈現為安靜的責任感。"}],"source":"2025 Q2.pdf","sourcePage":11},{"front":"used to think","meaning":"以前認為","examples":[{"en":"Kelvin used to think strength meant being feared.","zh":"Kelvin 以前認為力量意味着令人害怕。"},{"en":"Used to think means once believed something in the past but may not believe it now.","zh":"“Used to think” 指過去曾相信某事，但現在可能不再相信。"},{"en":"I used to think confidence meant speaking louder than everyone else.","zh":"我以前認為自信就是比所有人說話更大聲。"},{"en":"This phrase is useful when describing a changed belief.","zh":"當描述已改變的信念時，這個說法很有用。"},{"en":"It shows that Kelvin’s understanding of strength has moved on.","zh":"它顯示 Kelvin 對力量的理解已經前進。"}],"source":"2025 Q2.pdf","sourcePage":11},{"front":"being feared","meaning":"令人害怕","examples":[{"en":"Kelvin used to think strength meant being feared.","zh":"Kelvin 以前認為力量意味着令人害怕。"},{"en":"Being feared means making others feel afraid of you.","zh":"“Being feared” 指令別人害怕自己。"},{"en":"A bully may enjoy being feared because it gives him control.","zh":"欺凌者可能享受令人害怕，因為這給他控制感。"},{"en":"Being feared is not true strength because it depends on hurting or threatening others.","zh":"令人害怕不是真正力量，因為它依靠傷害或威脅別人。"},{"en":"This phrase shows Kelvin’s old mistaken idea of power.","zh":"這個說法顯示 Kelvin 舊日對權力的錯誤想法。"}],"source":"2025 Q2.pdf","sourcePage":11},{"front":"being useful","meaning":"有用；能幫上忙","examples":[{"en":"Kelvin now thinks strength means being useful.","zh":"Kelvin 現在認為力量意味着有用、能幫上忙。"},{"en":"Being useful means being able to help, support, or solve problems in a practical way.","zh":"“Being useful” 指能以實際方式幫助、支持或解決問題。"},{"en":"During the blackout, the most useful person was the neighbour with a torch and first-aid skills.","zh":"停電時，最能幫上忙的人是有電筒和急救知識的鄰居。"},{"en":"Being useful is a kinder form of strength because it serves others.","zh":"能幫上忙是一種更善良的力量，因為它服務別人。"},{"en":"This phrase shows Kelvin’s new understanding of power.","zh":"這個說法顯示 Kelvin 對力量的新理解。"}],"source":"2025 Q2.pdf","sourcePage":11},{"front":"just then","meaning":"就在那時","examples":[{"en":"Just then, the little girl from earlier walked past.","zh":"就在那時，之前那個小女孩走過。"},{"en":"Just then means at exactly that moment in the story.","zh":"“Just then” 指在故事中的那一刻正好。"},{"en":"Just then, the teacher entered and everyone stopped talking.","zh":"就在那時，老師走進來，所有人停止說話。"},{"en":"This phrase often introduces a timely interruption or meaningful coincidence.","zh":"這個說法常引出合時的打斷或有意義的巧合。"},{"en":"It brings the earlier girl back into the scene.","zh":"它把之前的小女孩再次帶回場景。"}],"source":"2025 Q2.pdf","sourcePage":11},{"front":"walked past","meaning":"走過","examples":[{"en":"The little girl walked past with her mother.","zh":"那個小女孩和媽媽一起走過。"},{"en":"Walked past means moved by someone or something without stopping for long.","zh":"“Walked past” 指從某人或某物旁邊走過，而沒有停留很久。"},{"en":"I waved when my neighbour walked past the café.","zh":"鄰居走過咖啡店時，我向他揮手。"},{"en":"Someone walking past can briefly reconnect different parts of a story.","zh":"有人走過，可以短暫地把故事不同部分重新連接起來。"},{"en":"This phrase creates a small moment that confirms Kelvin’s kindness.","zh":"這個說法製造一個小時刻，確認 Kelvin 的善意。"}],"source":"2025 Q2.pdf","sourcePage":11},{"front":"spotted Kelvin","meaning":"看見 Kelvin","examples":[{"en":"The little girl spotted Kelvin and waved shyly.","zh":"小女孩看見 Kelvin，並害羞地揮手。"},{"en":"Spotted Kelvin means noticed or recognised Kelvin suddenly.","zh":"“Spotted Kelvin” 指突然注意到或認出 Kelvin。"},{"en":"I spotted my old teacher across the station platform.","zh":"我在車站月台對面看見舊老師。"},{"en":"A child spotting a helper again may feel safe enough to respond warmly.","zh":"孩子再次看見幫助過她的人，可能會安心地回應。"},{"en":"This phrase shows that the girl remembers Kelvin’s kindness.","zh":"這個說法顯示小女孩記得 Kelvin 的善意。"}],"source":"2025 Q2.pdf","sourcePage":11},{"front":"waved shyly","meaning":"害羞地揮手","examples":[{"en":"The little girl waved shyly at Kelvin.","zh":"小女孩害羞地向 Kelvin 揮手。"},{"en":"Waved shyly means moved the hand in greeting while feeling a little timid or embarrassed.","zh":"“Waved shyly” 指帶點膽怯或不好意思地揮手打招呼。"},{"en":"The new student waved shyly when her classmates said hello.","zh":"新同學聽到同學問好時，害羞地揮手。"},{"en":"A shy wave can show gratitude without many words.","zh":"害羞地揮手可以不用很多說話，也表達感謝。"},{"en":"This phrase makes the girl’s response gentle and believable.","zh":"這個說法令小女孩的反應溫柔而可信。"}],"source":"2025 Q2.pdf","sourcePage":11},{"front":"waved back","meaning":"揮手回應","examples":[{"en":"Kelvin waved back with natural warmth.","zh":"Kelvin 帶着自然的溫暖揮手回應。"},{"en":"Waved back means returned someone’s wave as a friendly response.","zh":"“Waved back” 指以揮手回應別人的揮手。"},{"en":"The teacher waved back when the children greeted her from the bus.","zh":"孩子們在巴士上向老師打招呼時，老師揮手回應。"},{"en":"Waving back shows that a person has noticed and accepted the greeting.","zh":"揮手回應顯示一個人注意到並接受了問候。"},{"en":"This phrase shows Kelvin responding kindly and naturally.","zh":"這個說法顯示 Kelvin 自然友善地回應。"}],"source":"2025 Q2.pdf","sourcePage":11},{"front":"natural warmth","meaning":"自然的溫暖","examples":[{"en":"Kelvin waved back with natural warmth.","zh":"Kelvin 帶着自然的溫暖揮手回應。"},{"en":"Natural warmth means kindness that feels genuine and unforced.","zh":"自然的溫暖指感覺真誠而不勉強的善意。"},{"en":"The nurse spoke with natural warmth, so the child stopped crying.","zh":"護士帶着自然的溫暖說話，所以孩子停止哭泣。"},{"en":"Natural warmth is different from politeness that feels artificial.","zh":"自然的溫暖不同於感覺做作的禮貌。"},{"en":"This phrase shows that Kelvin’s kindness now seems real.","zh":"這個說法顯示 Kelvin 的善意現在看起來真實。"}],"source":"2025 Q2.pdf","sourcePage":11},{"front":"for a second","meaning":"有一秒鐘","examples":[{"en":"For a second, I forgot that Kelvin was the same person I had once disliked.","zh":"有一秒鐘，我忘記 Kelvin 是我曾經討厭的同一個人。"},{"en":"For a second means for a very short moment.","zh":"“For a second” 指在非常短的一刻。"},{"en":"For a second, the noisy park seemed completely quiet.","zh":"有一秒鐘，嘈雜的公園似乎完全安靜下來。"},{"en":"A short moment can change how we see someone from the past.","zh":"短短一刻可以改變我們如何看待過去認識的人。"},{"en":"This phrase shows a brief break in the writer’s old judgement.","zh":"這個說法顯示作者舊有判斷短暫中斷。"}],"source":"2025 Q2.pdf","sourcePage":12},{"front":"disliked so intensely","meaning":"曾經那麼強烈地討厭","examples":[{"en":"I had once disliked Kelvin so intensely.","zh":"我曾經那麼強烈地討厭 Kelvin。"},{"en":"Disliked so intensely means hated or disliked someone very strongly.","zh":"“Disliked so intensely” 指非常強烈地不喜歡甚至討厭某人。"},{"en":"She disliked the bully so intensely that she avoided the playground.","zh":"她曾經那麼強烈地討厭那個欺凌者，以致避開操場。"},{"en":"Strong dislike can last for years when someone has been hurt publicly.","zh":"當一個人曾被公開傷害，強烈厭惡可能會持續多年。"},{"en":"This phrase shows how difficult it is for the writer to accept Kelvin’s change.","zh":"這個說法顯示作者要接受 Kelvin 的改變有多困難。"}],"source":"2025 Q2.pdf","sourcePage":12},{"front":"as evening fell","meaning":"隨著黃昏降臨","examples":[{"en":"As evening fell, the lights of the park flickered on.","zh":"隨着黃昏降臨，公園的燈光閃爍亮起。"},{"en":"As evening fell means while day slowly turned into evening.","zh":"“As evening fell” 指白日慢慢轉為黃昏的時候。"},{"en":"As evening fell, families began leaving the beach.","zh":"隨着黃昏降臨，家庭開始離開海灘。"},{"en":"This phrase often gives a scene a quieter, more reflective mood.","zh":"這個說法常令場景變得較安靜和適合反思。"},{"en":"It marks the movement from a noisy afternoon to a thoughtful ending.","zh":"它標示由嘈雜下午轉向沉思結尾。"}],"source":"2025 Q2.pdf","sourcePage":12},{"front":"flickered on","meaning":"閃爍亮起","examples":[{"en":"The lights of the park flickered on.","zh":"公園的燈光閃爍亮起。"},{"en":"Flickered on means lights began to shine with a small quick movement or glow.","zh":"“Flickered on” 指燈光開始閃動或微微發亮。"},{"en":"The street lamps flickered on as the sky became dark.","zh":"天色變暗時，街燈閃爍亮起。"},{"en":"Lights flickering on can signal evening and a change in mood.","zh":"燈光閃爍亮起可以標示黃昏和氣氛轉變。"},{"en":"This phrase adds a gentle visual detail to the ending.","zh":"這個說法為結尾加入溫柔的視覺細節。"}],"source":"2025 Q2.pdf","sourcePage":12},{"front":"realised that","meaning":"意識到","examples":[{"en":"I realised that some people do change.","zh":"我意識到有些人真的會改變。"},{"en":"Realised that means came to understand something clearly.","zh":"“Realised that” 指清楚明白某件事。"},{"en":"I realised that my old classmate had become much kinder.","zh":"我意識到舊同學已變得善良得多。"},{"en":"People may realise a truth after seeing evidence that challenges their old beliefs.","zh":"當人看見挑戰舊信念的證據時，可能會意識到真相。"},{"en":"This phrase shows the writer’s new understanding of Kelvin.","zh":"這個說法顯示作者對 Kelvin 的新理解。"}],"source":"2025 Q2.pdf","sourcePage":12},{"front":"time softens them","meaning":"時間使他們變得溫和","examples":[{"en":"Some people change not because time softens them.","zh":"有些人改變，不是因為時間使他們變得溫和。"},{"en":"Time softens them means time makes people gentler, less harsh, or less angry.","zh":"“Time softens them” 指時間令人變得較溫柔、較不尖銳或較少憤怒。"},{"en":"Years apart may soften old classmates who once argued every day.","zh":"多年分開可能使曾天天爭吵的舊同學變得溫和。"},{"en":"Time can soften people, but sometimes change comes from a sudden crisis instead.","zh":"時間可以使人變得溫和，但有時改變來自突如其來的危機。"},{"en":"This phrase introduces a contrast between slow change and forced change.","zh":"這個說法引出緩慢改變與被迫改變之間的對比。"}],"source":"2025 Q2.pdf","sourcePage":12},{"front":"forces them to confront","meaning":"迫使他們面對","examples":[{"en":"Life sometimes forces people to confront the truth.","zh":"人生有時會迫使人面對真相。"},{"en":"Forces them to confront means makes people face something difficult directly, even if they do not want to.","zh":"“Forces them to confront” 指令人在不情願下直接面對困難事情。"},{"en":"Failure forced him to confront the truth about his poor preparation.","zh":"失敗迫使他面對自己準備不足的真相。"},{"en":"A crisis can force people to confront weaknesses they usually hide.","zh":"危機可以迫使人面對平日隱藏的弱點。"},{"en":"This phrase shows that Kelvin’s change was painful but necessary.","zh":"這個說法顯示 Kelvin 的改變痛苦但必要。"}],"source":"2025 Q2.pdf","sourcePage":12},{"front":"confront the truth","meaning":"面對真相","examples":[{"en":"Kelvin had been forced to confront the truth.","zh":"Kelvin 被迫面對真相。"},{"en":"To confront the truth means to face a reality honestly instead of avoiding it.","zh":"“Confront the truth” 指誠實面對現實，而不是逃避。"},{"en":"She had to confront the truth that her words had hurt her friend.","zh":"她必須面對真相：自己的說話傷害了朋友。"},{"en":"Confronting the truth can be painful, but it can begin real change.","zh":"面對真相可能痛苦，但可以開始真正改變。"},{"en":"This phrase shows Kelvin facing his false idea of strength.","zh":"這個說法顯示 Kelvin 面對自己對力量的錯誤理解。"}],"source":"2025 Q2.pdf","sourcePage":12},{"front":"in Kelvin’s case","meaning":"就 Kelvin 而言","examples":[{"en":"In Kelvin’s case, the truth was that kindness is not weakness.","zh":"就 Kelvin 而言，真相是善良不是軟弱。"},{"en":"In Kelvin’s case means specifically for Kelvin or in Kelvin’s situation.","zh":"“In Kelvin’s case” 指特別就 Kelvin 或 Kelvin 的情況而言。"},{"en":"In my brother’s case, moving schools helped him become more confident.","zh":"就我哥哥而言，轉校幫助他變得更有信心。"},{"en":"This phrase narrows a general idea to one particular person’s experience.","zh":"這個說法把一般想法收窄到某一個人的經歷。"},{"en":"It helps explain exactly what lesson Kelvin learned.","zh":"它幫助清楚說明 Kelvin 學到的教訓。"}],"source":"2025 Q2.pdf","sourcePage":12},{"front":"kindness is not weakness","meaning":"善良不是軟弱","examples":[{"en":"Kelvin learned that kindness is not weakness.","zh":"Kelvin 學會善良不是軟弱。"},{"en":"Kindness is not weakness means being gentle or caring does not mean being powerless.","zh":"“Kindness is not weakness” 指溫柔或關心別人並不等於沒有力量。"},{"en":"Mr Leung proved that kindness is not weakness when he acted calmly in the emergency.","zh":"梁先生在緊急情況中冷靜行動，證明善良不是軟弱。"},{"en":"Some people mistake kindness for weakness because they only respect loud confidence.","zh":"有些人把善良誤認為軟弱，因為他們只尊重大聲的自信。"},{"en":"This phrase expresses the central lesson of Kelvin’s transformation.","zh":"這個說法表達 Kelvin 轉變的核心教訓。"}],"source":"2025 Q2.pdf","sourcePage":12},{"front":"character reveals itself","meaning":"品格會顯露出來","examples":[{"en":"Character reveals itself most clearly in moments of crisis.","zh":"品格在危機時刻最清楚地顯露出來。"},{"en":"Character reveals itself means a person’s true qualities become visible through action.","zh":"“Character reveals itself” 指一個人的真正特質透過行動變得可見。"},{"en":"During the blackout, the teacher’s patience revealed itself.","zh":"停電期間，那位老師的耐性顯露出來。"},{"en":"Character reveals itself when people choose whether to help, panic, or walk away.","zh":"當人選擇幫忙、驚慌或離開時，品格便會顯露出來。"},{"en":"This phrase shows that real personality is proved by behaviour.","zh":"這個說法顯示真正性格由行為證明。"}],"source":"2025 Q2.pdf","sourcePage":13},{"front":"moments of crisis","meaning":"危機時刻","examples":[{"en":"Character is revealed most clearly in moments of crisis.","zh":"品格在危機時刻最清楚地顯露出來。"},{"en":"Moments of crisis are times of serious danger, difficulty, or pressure.","zh":"危機時刻是有嚴重危險、困難或壓力的時間。"},{"en":"In moments of crisis, people often show whether they are calm, selfish, or brave.","zh":"在危機時刻，人們常會顯示自己是冷靜、自私還是勇敢。"},{"en":"Kelvin changed because a moment of crisis exposed what real strength looked like.","zh":"Kelvin 之所以改變，是因為危機時刻顯示真正力量是甚麼。"},{"en":"This phrase highlights situations that test people deeply.","zh":"這個說法突顯深深考驗人的情境。"}],"source":"2025 Q2.pdf","sourcePage":13},{"front":"stood up to leave","meaning":"站起來準備離開","examples":[{"en":"We stood up to leave the theme park.","zh":"我們站起來準備離開主題公園。"},{"en":"Stood up to leave means rose from a seat because it was time to go.","zh":"“Stood up to leave” 指從座位站起來，因為是時候離開。"},{"en":"After the long conversation, we stood up to leave the café.","zh":"長談後，我們站起來準備離開咖啡店。"},{"en":"Standing up to leave often marks the end of a meeting or scene.","zh":"站起來準備離開常標示一次見面或一個場景的結束。"},{"en":"This phrase moves the story towards its conclusion.","zh":"這個說法把故事推向結尾。"}],"source":"2025 Q2.pdf","sourcePage":13},{"front":"felt as though","meaning":"感覺好像","examples":[{"en":"I felt as though I had met two versions of the same person.","zh":"我感覺好像遇見了同一個人的兩個版本。"},{"en":"Felt as though means had the feeling that something was true, even if it was not literally true.","zh":"“Felt as though” 指感覺某事是真的，即使未必字面上完全如此。"},{"en":"I felt as though I was speaking to a stranger when my old friend sounded so different.","zh":"舊朋友聽起來那麼不同時，我感覺好像正在跟陌生人說話。"},{"en":"This phrase helps describe a strong emotional impression.","zh":"這個說法幫助描述強烈情感印象。"},{"en":"It shows how deeply Kelvin’s change affected the writer.","zh":"它顯示 Kelvin 的改變多麼深地影響作者。"}],"source":"2025 Q2.pdf","sourcePage":13},{"front":"two versions of the same person","meaning":"同一個人的兩個版本","examples":[{"en":"I had met two versions of the same person.","zh":"我遇見了同一個人的兩個版本。"},{"en":"Two versions of the same person means the old and new sides of one person seem almost like different people.","zh":"“Two versions of the same person” 指一個人的舊一面和新一面幾乎像不同人。"},{"en":"After hearing her apology, I felt I had seen two versions of the same person.","zh":"聽到她道歉後，我覺得自己看見了同一個人的兩個版本。"},{"en":"People can change so much that their past and present selves seem difficult to connect.","zh":"人可以改變得很大，以致過去和現在的自己似乎難以連接。"},{"en":"This phrase captures the contrast between Kelvin the bully and Kelvin the helper.","zh":"這個說法捕捉欺凌者 Kelvin 和幫助者 Kelvin 之間的對比。"}],"source":"2025 Q2.pdf","sourcePage":13},{"front":"standing before me","meaning":"站在我面前","examples":[{"en":"The man standing before me had learned compassion.","zh":"站在我面前的男子已學會同情與體恤。"},{"en":"Standing before me means being physically present in front of me at that moment.","zh":"“Standing before me” 指在那一刻實際站在我面前。"},{"en":"The student standing before me was no longer the careless boy I remembered.","zh":"站在我面前的學生已不再是我記憶中粗心的男孩。"},{"en":"This phrase makes the contrast between memory and present reality immediate.","zh":"這個說法令記憶與眼前現實的對比變得即時。"},{"en":"It shows that the writer can see Kelvin’s change directly.","zh":"它顯示作者能直接看見 Kelvin 的改變。"}],"source":"2025 Q2.pdf","sourcePage":13},{"front":"wanted attention","meaning":"想得到注意","examples":[{"en":"The boy I had known at school had wanted attention.","zh":"我在學校認識的那個男孩曾想得到注意。"},{"en":"Wanted attention means desired others to notice, watch, or react to him.","zh":"“Wanted attention” 指希望別人留意、觀看或回應自己。"},{"en":"He made loud jokes because he wanted attention from his classmates.","zh":"他大聲講笑，因為他想得到同學注意。"},{"en":"Wanting attention can lead to hurtful behaviour if someone seeks it in the wrong way.","zh":"如果以錯誤方式尋求注意，可能會導致傷人的行為。"},{"en":"This phrase explains part of Kelvin’s old bullying behaviour.","zh":"這個說法解釋 Kelvin 舊日欺凌行為的一部分。"}],"source":"2025 Q2.pdf","sourcePage":13},{"front":"learned compassion","meaning":"學會同情與體恤","examples":[{"en":"The man standing before me had learned compassion.","zh":"站在我面前的男子已學會同情與體恤。"},{"en":"Learned compassion means became able to understand and care about other people’s pain.","zh":"“Learned compassion” 指變得能理解和關心別人的痛苦。"},{"en":"After caring for his father, Kelvin learned compassion through daily responsibility.","zh":"照顧父親後，Kelvin 透過日常責任學會同情與體恤。"},{"en":"People often learn compassion when they see suffering closely.","zh":"人們常在近距離看見痛苦時學會同情與體恤。"},{"en":"This phrase shows Kelvin’s emotional growth.","zh":"這個說法顯示 Kelvin 的情感成長。"}],"source":"2025 Q2.pdf","sourcePage":13},{"front":"somehow","meaning":"不知怎的","examples":[{"en":"Somehow, that quiet change seemed remarkable.","zh":"不知怎的，那種靜靜的改變顯得很了不起。"},{"en":"Somehow means in a way that is difficult to explain clearly.","zh":"“Somehow” 指以一種難以清楚解釋的方式。"},{"en":"Somehow, the short conversation made me feel lighter.","zh":"不知怎的，那段短短對話令我感到輕鬆了一點。"},{"en":"This word is useful when a feeling is strong but not easy to analyse.","zh":"當感受強烈但不容易分析時，這個詞很有用。"},{"en":"It shows the writer’s quiet wonder at Kelvin’s change.","zh":"它顯示作者對 Kelvin 改變的安靜驚嘆。"}],"source":"2025 Q2.pdf","sourcePage":13},{"front":"in the middle of","meaning":"在……中間","examples":[{"en":"The quiet change happened in the middle of a noisy theme park.","zh":"那種靜靜的改變發生在嘈雜主題公園中間。"},{"en":"In the middle of means at the centre of a place, event, or situation.","zh":"“In the middle of” 指在某地方、事件或情況的中心。"},{"en":"We had a serious conversation in the middle of a crowded shopping mall.","zh":"我們在擠迫商場中間進行了一段嚴肅對話。"},{"en":"A quiet realisation can feel stronger when it happens in the middle of noise.","zh":"當安靜領悟發生在嘈雜之中，它可能顯得更強烈。"},{"en":"This phrase contrasts inner reflection with the busy setting.","zh":"這個說法把內心反思與繁忙環境作對比。"}],"source":"2025 Q2.pdf","sourcePage":13},{"front":"noisy theme park","meaning":"嘈雜的主題公園","examples":[{"en":"The quiet change felt remarkable in the noisy theme park.","zh":"那種靜靜的改變在嘈雜的主題公園中顯得了不起。"},{"en":"A noisy theme park is a loud amusement place full of music, rides, crowds, and announcements.","zh":"嘈雜的主題公園是充滿音樂、機動遊戲、人群和廣播聲的吵鬧娛樂場所。"},{"en":"The noisy theme park made it difficult to hear quiet conversations.","zh":"嘈雜的主題公園令人難以聽清安靜對話。"},{"en":"A serious emotional moment can stand out strongly inside a noisy theme park.","zh":"嚴肅的情感時刻可以在嘈雜主題公園中顯得特別突出。"},{"en":"This phrase highlights the contrast between outer excitement and inner change.","zh":"這個說法突顯外在興奮與內在改變之間的對比。"}],"source":"2025 Q2.pdf","sourcePage":14},{"front":"quiet change","meaning":"靜靜的改變","examples":[{"en":"Kelvin’s quiet change seemed more remarkable than any ride.","zh":"Kelvin 靜靜的改變似乎比任何機動遊戲都更了不起。"},{"en":"Quiet change means a deep personal transformation that happens without drama or loud attention.","zh":"靜靜的改變指沒有戲劇性或大聲宣告，卻深刻的人格轉變。"},{"en":"Her quiet change appeared in the way she listened instead of interrupting.","zh":"她靜靜的改變出現在她開始聆聽，而不是打斷別人。"},{"en":"Quiet change can be powerful because it is shown through steady behaviour.","zh":"靜靜的改變可以很有力量，因為它透過穩定行為顯示出來。"},{"en":"This phrase shows that Kelvin’s growth is gentle but meaningful.","zh":"這個說法顯示 Kelvin 的成長溫和但有意義。"}],"source":"2025 Q2.pdf","sourcePage":14},{"front":"more remarkable than","meaning":"比……更了不起","examples":[{"en":"Kelvin’s change seemed more remarkable than any ride around us.","zh":"Kelvin 的改變似乎比我們周圍任何機動遊戲都更了不起。"},{"en":"More remarkable than means more unusual, impressive, or worth noticing than something else.","zh":"“More remarkable than” 指比另一件事更不尋常、更令人佩服或更值得注意。"},{"en":"Her apology was more remarkable than the prize she won.","zh":"她的道歉比她贏得的獎項更了不起。"},{"en":"A person’s quiet growth can be more remarkable than a dramatic public success.","zh":"一個人靜靜的成長，可以比戲劇性的公開成功更了不起。"},{"en":"This phrase compares emotional change with the exciting rides nearby.","zh":"這個說法把情感改變與附近刺激的機動遊戲作比較。"}],"source":"2025 Q2.pdf","sourcePage":14},{"front":"any ride around us","meaning":"我們周圍任何機動遊戲","examples":[{"en":"Kelvin’s change was more remarkable than any ride around us.","zh":"Kelvin 的改變比我們周圍任何機動遊戲都更了不起。"},{"en":"Any ride around us means any amusement ride nearby in the theme park.","zh":"“Any ride around us” 指主題公園中附近任何一項機動遊戲。"},{"en":"The roller coaster was exciting, but the conversation mattered more than any ride around us.","zh":"過山車很刺激，但那段對話比我們周圍任何機動遊戲都更重要。"},{"en":"Comparing Kelvin’s change with the rides shows that inner transformation can outshine entertainment.","zh":"把 Kelvin 的改變與機動遊戲比較，顯示內在轉變可以比娛樂更耀眼。"},{"en":"This phrase ends the scene by making personal growth bigger than the theme park itself.","zh":"這個說法在結尾令個人成長比主題公園本身更大。"}],"source":"2025 Q2.pdf","sourcePage":14}],"dse/writing/part-b/2025/Q4":[{"front":"making teamwork work","meaning":"令團隊合作發揮作用","examples":[{"en":"The essay discusses how to make teamwork work in the modern workplace.","zh":"這篇文章討論如何在現代職場令團隊合作發揮作用。"},{"en":"Making teamwork work means helping group work become useful, fair, and effective.","zh":"making teamwork work 的意思是令小組工作變得有用、公平和有效。"},{"en":"Managers make teamwork work when they set clear roles and expectations.","zh":"當管理者訂立清晰角色和期望時，就是令團隊合作發揮作用。"},{"en":"Teamwork does not work automatically just because people are put together.","zh":"團隊合作不會因為人們被放在一起就自動有效。"},{"en":"This phrase focuses on turning cooperation from an idea into real results.","zh":"這個短語聚焦把合作由概念變成真正成果。"}],"source":"2025 Q4.pdf","sourcePage":1},{"front":"overcoming hidden difficulties","meaning":"克服隱藏困難","examples":[{"en":"Good management can help teams overcome hidden difficulties.","zh":"良好管理可以幫助團隊克服隱藏困難。"},{"en":"Overcoming hidden difficulties means dealing successfully with problems that are not obvious at first.","zh":"overcoming hidden difficulties 的意思是成功處理一開始不明顯的問題。"},{"en":"A team can overcome hidden difficulties by discussing unfair workload early.","zh":"團隊可以透過及早討論工作量不公平來克服隱藏困難。"},{"en":"Hidden problems become easier to solve when leaders make them visible.","zh":"當領袖令隱藏問題變得可見時，問題會較容易解決。"},{"en":"This phrase shows that teamwork needs careful management beneath the surface.","zh":"這個短語顯示團隊合作在表面以下需要細心管理。"}],"source":"2025 Q4.pdf","sourcePage":1},{"front":"hidden difficulties","meaning":"隱藏困難","examples":[{"en":"Group work often involves hidden difficulties.","zh":"小組工作常涉及隱藏困難。"},{"en":"Hidden difficulties are problems that are not immediately visible but still affect success.","zh":"hidden difficulties 是不會立即看見，但仍影響成功的問題。"},{"en":"Unequal effort and unclear expectations can be hidden difficulties in a project.","zh":"付出不均和期望不清都可以是項目中的隱藏困難。"},{"en":"Teams may fail if hidden difficulties are ignored until conflict appears.","zh":"如果隱藏困難被忽視到衝突出現，團隊可能會失敗。"},{"en":"This phrase reminds readers that group work can look simple but be complicated.","zh":"這個短語提醒讀者，小組工作看似簡單，但其實複雜。"}],"source":"2025 Q4.pdf","sourcePage":1},{"front":"in today’s workplace","meaning":"在今天的職場","examples":[{"en":"In today’s workplace, few important tasks are completed by one employee alone.","zh":"在今天的職場，很少重要任務只由一名員工獨自完成。"},{"en":"In today’s workplace means in the modern working environment.","zh":"in today’s workplace 的意思是在現代工作環境中。"},{"en":"In today’s workplace, employees often cooperate across departments and time zones.","zh":"在今天的職場，員工常跨部門和跨時區合作。"},{"en":"Teamwork matters more in today’s workplace because problems are more complex.","zh":"在今天的職場，團隊合作更重要，因為問題更複雜。"},{"en":"This phrase sets the discussion in a modern professional context.","zh":"這個短語把討論放在現代專業背景中。"}],"source":"2025 Q4.pdf","sourcePage":1},{"front":"few important tasks","meaning":"很少重要任務","examples":[{"en":"Few important tasks are completed by one employee alone.","zh":"很少重要任務只由一名員工獨自完成。"},{"en":"Few important tasks means not many serious or valuable pieces of work.","zh":"few important tasks 的意思是不多嚴肅或有價值的工作。"},{"en":"Few important tasks in a company can be done without input from several people.","zh":"公司中很少重要任務可以在沒有幾個人參與下完成。"},{"en":"Product launches, reports, and crisis responses usually need more than one worker.","zh":"產品推出、報告和危機應對通常需要多於一名員工。"},{"en":"This phrase explains why teamwork has become necessary.","zh":"這個短語解釋為何團隊合作變得必要。"}],"source":"2025 Q4.pdf","sourcePage":1},{"front":"by one employee alone","meaning":"只由一名員工獨自完成","examples":[{"en":"Important tasks are rarely completed by one employee alone.","zh":"重要任務很少只由一名員工獨自完成。"},{"en":"By one employee alone means by a single worker without help from others.","zh":"by one employee alone 的意思是由一名員工在沒有他人幫助下完成。"},{"en":"A major presentation is difficult to finish by one employee alone.","zh":"重大匯報很難只由一名員工獨自完成。"},{"en":"Modern projects often require research, design, communication, and decision-making from different people.","zh":"現代項目常需要不同人負責研究、設計、溝通和決策。"},{"en":"This phrase highlights the limits of individual work.","zh":"這個短語突顯個人工作的限制。"}],"source":"2025 Q4.pdf","sourcePage":1},{"front":"deal with increasingly complex problems","meaning":"處理越來越複雜的問題","examples":[{"en":"Companies deal with increasingly complex problems.","zh":"公司處理越來越複雜的問題。"},{"en":"To deal with increasingly complex problems means to handle problems that are becoming more difficult and connected.","zh":"deal with increasingly complex problems 的意思是處理變得更困難和更互相關連的問題。"},{"en":"Companies deal with complex problems when they manage customer needs, costs, and technology at once.","zh":"當公司同時管理顧客需要、成本和科技時，就是處理複雜問題。"},{"en":"Such problems often require people with different expertise to work together.","zh":"這類問題常需要具不同專業知識的人合作。"},{"en":"This phrase explains why organisations depend on teams.","zh":"這個短語解釋為何機構依賴團隊。"}],"source":"2025 Q4.pdf","sourcePage":1},{"front":"increasingly complex problems","meaning":"越來越複雜的問題","examples":[{"en":"Companies rely on group work to solve increasingly complex problems.","zh":"公司依賴小組工作來解決越來越複雜的問題。"},{"en":"Increasingly complex problems are problems that become more complicated over time.","zh":"increasingly complex problems 是隨時間變得更複雜的問題。"},{"en":"A company may face increasingly complex problems as markets, technology, and customer demands change.","zh":"隨着市場、科技和顧客需求改變，公司可能面對越來越複雜的問題。"},{"en":"These problems are hard to solve with only one person’s knowledge.","zh":"這些問題難以只靠一個人的知識解決。"},{"en":"This phrase shows why combined expertise is useful.","zh":"這個短語顯示結合專業知識為何有用。"}],"source":"2025 Q4.pdf","sourcePage":1},{"front":"from product design to crisis management","meaning":"由產品設計到危機管理","examples":[{"en":"Companies face complex problems, from product design to crisis management.","zh":"公司面對複雜問題，由產品設計到危機管理。"},{"en":"From product design to crisis management means across a wide range of business tasks.","zh":"from product design to crisis management 的意思是涵蓋一系列廣泛的商業任務。"},{"en":"Teamwork is needed from product design to crisis management because different skills are involved.","zh":"由產品設計到危機管理都需要團隊合作，因為涉及不同技能。"},{"en":"This phrase shows that cooperation is useful in both creative and urgent situations.","zh":"這個短語顯示合作在創意和緊急情況中都很有用。"},{"en":"It helps readers understand the broad importance of teamwork.","zh":"它幫助讀者理解團隊合作的廣泛重要性。"}],"source":"2025 Q4.pdf","sourcePage":1},{"front":"product design","meaning":"產品設計","examples":[{"en":"Product design often requires teamwork.","zh":"產品設計常需要團隊合作。"},{"en":"Product design is the process of planning how a product looks, works, and meets users’ needs.","zh":"product design 是規劃產品外觀、功能和如何滿足用戶需要的過程。"},{"en":"Designers, engineers, marketers, and customers may all influence product design.","zh":"設計師、工程師、市場人員和顧客都可能影響產品設計。"},{"en":"Good product design needs both creativity and practical testing.","zh":"良好產品設計需要創意，也需要實際測試。"},{"en":"This phrase describes a task that benefits from different expertise.","zh":"這個短語描述一項受益於不同專業知識的任務。"}],"source":"2025 Q4.pdf","sourcePage":1},{"front":"crisis management","meaning":"危機管理","examples":[{"en":"Crisis management often requires cooperation across departments.","zh":"危機管理常需要跨部門合作。"},{"en":"Crisis management is the process of handling a serious unexpected problem.","zh":"crisis management 是處理嚴重突發問題的過程。"},{"en":"A company may need crisis management after a product failure or public complaint.","zh":"公司在產品故障或公眾投訴後可能需要危機管理。"},{"en":"During crisis management, teams must communicate quickly and clearly.","zh":"在危機管理期間，團隊必須快速而清晰地溝通。"},{"en":"This phrase describes urgent teamwork under pressure.","zh":"這個短語描述壓力下的緊急團隊合作。"}],"source":"2025 Q4.pdf","sourcePage":2},{"front":"come to rely heavily on","meaning":"逐漸非常依賴","examples":[{"en":"Companies have come to rely heavily on group work.","zh":"公司已逐漸非常依賴小組工作。"},{"en":"Come to rely heavily on means gradually become very dependent on something.","zh":"come to rely heavily on 的意思是逐漸變得非常依靠某事物。"},{"en":"Modern businesses have come to rely heavily on digital project-management tools.","zh":"現代企業已逐漸非常依賴數碼項目管理工具。"},{"en":"Companies rely on teams because one employee rarely has all the necessary skills.","zh":"公司依賴團隊，因為一名員工很少擁有所有所需技能。"},{"en":"This phrase shows a gradual change in working habits.","zh":"這個短語顯示工作習慣的逐漸改變。"}],"source":"2025 Q4.pdf","sourcePage":2},{"front":"group work","meaning":"小組工作；團隊工作","examples":[{"en":"Group work is essential in the modern workplace.","zh":"小組工作在現代職場中不可或缺。"},{"en":"Group work means people working together to complete a shared task.","zh":"group work 的意思是人們一起完成共同任務。"},{"en":"Group work can combine different skills, ideas, and experiences.","zh":"小組工作可以結合不同技能、想法和經驗。"},{"en":"Poorly managed group work may become unfair or confusing.","zh":"管理不善的小組工作可能變得不公平或混亂。"},{"en":"This phrase describes both an opportunity and a challenge.","zh":"這個短語同時描述機會和挑戰。"}],"source":"2025 Q4.pdf","sourcePage":2},{"front":"in order to","meaning":"為了","examples":[{"en":"Companies use group work in order to combine expertise.","zh":"公司使用小組工作，為了結合專業知識。"},{"en":"In order to means for the purpose of doing something.","zh":"in order to 的意思是為了做某事。"},{"en":"Teams hold regular meetings in order to avoid misunderstanding.","zh":"團隊定期開會，為了避免誤解。"},{"en":"This phrase clearly explains why an action is taken.","zh":"這個短語清楚解釋為何採取某行動。"},{"en":"It is useful in essays when linking methods to goals.","zh":"在文章中把方法與目標連繫起來時，它很有用。"}],"source":"2025 Q4.pdf","sourcePage":2},{"front":"combine expertise","meaning":"結合專業知識","examples":[{"en":"Group work allows companies to combine expertise.","zh":"小組工作讓公司結合專業知識。"},{"en":"To combine expertise means to bring together different people’s professional knowledge and skills.","zh":"combine expertise 的意思是把不同人的專業知識和技能集合起來。"},{"en":"A product team combines expertise from design, finance, and marketing.","zh":"產品團隊結合設計、財務和市場推廣方面的專業知識。"},{"en":"Combining expertise can lead to better decisions than relying on one viewpoint.","zh":"結合專業知識可以比依賴單一觀點帶來更好決策。"},{"en":"This phrase explains a major advantage of teamwork.","zh":"這個短語解釋團隊合作的一個主要優點。"}],"source":"2025 Q4.pdf","sourcePage":2},{"front":"improve decision-making","meaning":"改善決策","examples":[{"en":"Teamwork can improve decision-making.","zh":"團隊合作可以改善決策。"},{"en":"To improve decision-making means to make choices more accurate, balanced, and informed.","zh":"improve decision-making 的意思是令選擇更準確、更平衡和更有資訊支持。"},{"en":"A team improves decision-making when members share different risks and possible solutions.","zh":"當成員分享不同風險和可能解決方案時，團隊就能改善決策。"},{"en":"Better decision-making happens when people challenge weak assumptions respectfully.","zh":"當人們尊重地挑戰薄弱假設時，決策會更好。"},{"en":"This phrase describes a practical benefit of collaboration.","zh":"這個短語描述合作的實際好處。"}],"source":"2025 Q4.pdf","sourcePage":2},{"front":"produce stronger results","meaning":"產生更佳成果","examples":[{"en":"Group work can help teams produce stronger results.","zh":"小組工作可以幫助團隊產生更佳成果。"},{"en":"To produce stronger results means to achieve better, more reliable, or more creative outcomes.","zh":"produce stronger results 的意思是取得更好、更可靠或更有創意的成果。"},{"en":"A team may produce stronger results when researchers, designers, and presenters work together.","zh":"當研究人員、設計師和匯報者合作時，團隊可能產生更佳成果。"},{"en":"Stronger results require fair contribution and clear communication.","zh":"更佳成果需要公平貢獻和清晰溝通。"},{"en":"This phrase shows what good teamwork should lead to.","zh":"這個短語顯示良好團隊合作應帶來甚麼。"}],"source":"2025 Q4.pdf","sourcePage":2},{"front":"despite its recognised value","meaning":"儘管其價值獲得承認","examples":[{"en":"Despite its recognised value, teamwork is often met with reluctance.","zh":"儘管其價值獲得承認，團隊合作仍常遭到不情願的反應。"},{"en":"Despite its recognised value means although people generally know it is useful.","zh":"despite its recognised value 的意思是雖然人們普遍知道它有用。"},{"en":"Despite its recognised value, group work may still make employees nervous.","zh":"儘管小組工作的價值獲得承認，它仍可能令員工緊張。"},{"en":"This phrase introduces a contrast between theory and real feelings.","zh":"這個短語引入理論與真實感受之間的對比。"},{"en":"It helps explain why a valuable practice can still be unpopular.","zh":"它幫助解釋為何有價值的做法仍可能不受歡迎。"}],"source":"2025 Q4.pdf","sourcePage":2},{"front":"recognised value","meaning":"公認價值","examples":[{"en":"Teamwork has recognised value in the workplace.","zh":"團隊合作在職場中有公認價值。"},{"en":"Recognised value means usefulness or importance that is generally accepted.","zh":"recognised value 是普遍被接受的有用性或重要性。"},{"en":"The recognised value of teamwork lies in shared expertise and stronger decisions.","zh":"團隊合作的公認價值在於共享專業知識和更佳決策。"},{"en":"Even with recognised value, teamwork can fail if it is poorly managed.","zh":"即使有公認價值，如果管理不善，團隊合作仍會失敗。"},{"en":"This phrase separates the idea’s value from its practical difficulties.","zh":"這個短語把概念本身的價值與實際困難分開。"}],"source":"2025 Q4.pdf","sourcePage":2},{"front":"be met with reluctance","meaning":"遭到不情願的反應","examples":[{"en":"Teamwork is often met with reluctance rather than enthusiasm.","zh":"團隊合作常遭到不情願的反應，而不是熱情。"},{"en":"Be met with reluctance means receive an unwilling or hesitant response.","zh":"be met with reluctance 的意思是得到不願意或猶豫的反應。"},{"en":"A new group project may be met with reluctance if workers expect unfair workload.","zh":"如果員工預期工作量不公平，新的小組項目可能遭到不情願的反應。"},{"en":"Reluctance often appears when past teamwork has felt frustrating.","zh":"當過去的團隊合作令人沮喪時，不情願常會出現。"},{"en":"This phrase describes a negative reaction to a proposal or task.","zh":"這個短語描述對建議或任務的負面反應。"}],"source":"2025 Q4.pdf","sourcePage":2},{"front":"rather than enthusiasm","meaning":"而不是熱情","examples":[{"en":"Teamwork is often met with reluctance rather than enthusiasm.","zh":"團隊合作常遭到不情願的反應，而不是熱情。"},{"en":"Rather than enthusiasm means instead of excitement, willingness, or positive energy.","zh":"rather than enthusiasm 的意思是而不是興奮、願意或正面能量。"},{"en":"Employees may show caution rather than enthusiasm if group work previously felt unfair.","zh":"如果過去的小組工作感覺不公平，員工可能表現出謹慎而不是熱情。"},{"en":"This phrase contrasts the expected positive reaction with the actual negative one.","zh":"這個短語把預期的正面反應與實際負面反應作對比。"},{"en":"It helps explain why teamwork needs better management.","zh":"它幫助解釋為何團隊合作需要更好管理。"}],"source":"2025 Q4.pdf","sourcePage":3},{"front":"associate something with","meaning":"把……與……聯繫起來","examples":[{"en":"Many workers associate group work with wasted time.","zh":"許多員工把小組工作與浪費時間聯繫起來。"},{"en":"To associate something with something else means to connect them in your mind.","zh":"associate something with something else 的意思是在心中把兩件事連在一起。"},{"en":"Employees may associate meetings with boredom if meetings rarely solve problems.","zh":"如果會議很少解決問題，員工可能把會議與沉悶聯繫起來。"},{"en":"If workers associate teamwork with unfairness, they may resist new projects.","zh":"如果員工把團隊合作與不公平聯繫起來，他們可能抗拒新項目。"},{"en":"This phrase shows how past experience shapes attitudes.","zh":"這個短語顯示過去經驗如何塑造態度。"}],"source":"2025 Q4.pdf","sourcePage":3},{"front":"wasted time","meaning":"浪費時間","examples":[{"en":"Many workers associate group work with wasted time.","zh":"許多員工把小組工作與浪費時間聯繫起來。"},{"en":"Wasted time is time used without useful progress or meaningful result.","zh":"wasted time 是沒有帶來有用進展或有意義結果的時間。"},{"en":"A long meeting with no decision can feel like wasted time.","zh":"一場沒有決定的長會議可能感覺像浪費時間。"},{"en":"Group work becomes frustrating when employees feel their hours are wasted.","zh":"當員工覺得自己的時間被浪費，小組工作就會令人沮喪。"},{"en":"This phrase describes one reason people dislike poorly managed teamwork.","zh":"這個短語描述人們不喜歡管理不善的團隊合作的其中一個原因。"}],"source":"2025 Q4.pdf","sourcePage":3},{"front":"uneven effort","meaning":"付出不均","examples":[{"en":"Workers may dislike group work because of uneven effort.","zh":"員工可能因付出不均而不喜歡小組工作。"},{"en":"Uneven effort means some people work much harder than others.","zh":"uneven effort 的意思是有些人比其他人付出多很多。"},{"en":"Uneven effort appears when one member researches for hours while another contributes little.","zh":"當一名成員花數小時研究，而另一人貢獻很少時，就出現付出不均。"},{"en":"Teams become unfair when uneven effort is ignored.","zh":"當付出不均被忽視，團隊就會變得不公平。"},{"en":"This phrase describes a common cause of resentment in teamwork.","zh":"這個短語描述團隊合作中造成不滿的常見原因。"}],"source":"2025 Q4.pdf","sourcePage":3},{"front":"unnecessary conflict","meaning":"不必要的衝突","examples":[{"en":"Group work can lead to unnecessary conflict.","zh":"小組工作可以導致不必要的衝突。"},{"en":"Unnecessary conflict is disagreement or tension that could have been avoided.","zh":"unnecessary conflict 是原本可以避免的分歧或緊張。"},{"en":"Unclear roles can create unnecessary conflict between hardworking team members.","zh":"不清晰的角色可以在勤奮成員之間造成不必要的衝突。"},{"en":"Conflict is unnecessary when better communication could prevent it.","zh":"如果更好溝通本可防止衝突，該衝突就是不必要的。"},{"en":"This phrase describes avoidable tension in teams.","zh":"這個短語描述團隊中可避免的緊張。"}],"source":"2025 Q4.pdf","sourcePage":3},{"front":"essential in the modern workplace","meaning":"在現代職場中不可或缺","examples":[{"en":"Group work is essential in the modern workplace.","zh":"小組工作在現代職場中不可或缺。"},{"en":"Essential in the modern workplace means necessary for success in today’s professional environment.","zh":"essential in the modern workplace 的意思是在今天的專業環境中成功所必需。"},{"en":"Teamwork is essential because modern tasks often cross departments and skills.","zh":"團隊合作不可或缺，因為現代任務常跨越部門和技能。"},{"en":"A company cannot solve complex problems if employees always work separately.","zh":"如果員工總是各自工作，公司不能解決複雜問題。"},{"en":"This phrase shows the practical necessity of collaboration.","zh":"這個短語顯示合作的實際必要性。"}],"source":"2025 Q4.pdf","sourcePage":3},{"front":"unequal participation","meaning":"參與不均","examples":[{"en":"Group work often becomes unpopular because of unequal participation.","zh":"小組工作常因參與不均而變得不受歡迎。"},{"en":"Unequal participation means some members join actively while others do very little.","zh":"unequal participation 的意思是有些成員積極參與，而其他人做得很少。"},{"en":"Unequal participation can make meetings feel unfair and inefficient.","zh":"參與不均可以令會議感覺不公平和低效。"},{"en":"When participation is unequal, strong workers may feel exploited.","zh":"當參與不均時，能力強的員工可能覺得被剝削。"},{"en":"This phrase describes a fairness problem in group work.","zh":"這個短語描述小組工作中的公平問題。"}],"source":"2025 Q4.pdf","sourcePage":3},{"front":"poor communication","meaning":"溝通不善","examples":[{"en":"Poor communication can quietly ruin even a talented team.","zh":"溝通不善可以悄悄破壞即使有才能的團隊。"},{"en":"Poor communication means unclear, incomplete, or confusing exchange of information.","zh":"poor communication 是不清晰、不完整或令人混亂的資訊交流。"},{"en":"Poor communication can make team members duplicate work or miss deadlines.","zh":"溝通不善可以令團隊成員重複工作或錯過限期。"},{"en":"A talented team may still fail if members misunderstand one another.","zh":"即使有才能的團隊，如果成員互相誤解，仍可能失敗。"},{"en":"This phrase describes a hidden weakness that damages teamwork.","zh":"這個短語描述會傷害團隊合作的隱藏弱點。"}],"source":"2025 Q4.pdf","sourcePage":3},{"front":"clashes of personality","meaning":"性格衝突","examples":[{"en":"Group work may become difficult because of clashes of personality.","zh":"小組工作可能因性格衝突而變得困難。"},{"en":"Clashes of personality are conflicts caused by different temperaments, habits, or working styles.","zh":"clashes of personality 是由不同性情、習慣或工作風格造成的衝突。"},{"en":"A direct worker may clash with a cautious colleague during a rushed project.","zh":"在趕急項目中，直接的員工可能與謹慎的同事產生衝突。"},{"en":"Personality clashes can grow worse under pressure if no one manages them.","zh":"如果沒有人管理，性格衝突在壓力下可能惡化。"},{"en":"This phrase explains why teamwork can be emotionally difficult.","zh":"這個短語解釋為何團隊合作在情緒上可能困難。"}],"source":"2025 Q4.pdf","sourcePage":3},{"front":"be overcome through","meaning":"透過……克服","examples":[{"en":"These problems can be overcome through clear structures.","zh":"這些問題可以透過清晰架構克服。"},{"en":"Be overcome through means be solved or reduced by using a particular method.","zh":"be overcome through 的意思是透過使用某種方法來解決或減少問題。"},{"en":"Unequal effort can be overcome through defined roles and progress checks.","zh":"付出不均可以透過明確角色和進度檢查來克服。"},{"en":"Communication problems can be overcome through written summaries and agreed channels.","zh":"溝通問題可以透過書面摘要和約定渠道來克服。"},{"en":"This phrase connects a problem with a practical solution.","zh":"這個短語把問題與實際解決方法連繫起來。"}],"source":"2025 Q4.pdf","sourcePage":3},{"front":"clear structures","meaning":"清晰架構","examples":[{"en":"Clear structures can make teamwork fairer.","zh":"清晰架構可以令團隊合作更公平。"},{"en":"Clear structures are organised rules, roles, timelines, and processes.","zh":"clear structures 是有組織的規則、角色、時間表和流程。"},{"en":"A clear structure tells each member what to do and when to report progress.","zh":"清晰架構告訴每位成員要做甚麼，以及何時匯報進度。"},{"en":"Teams work better when structure prevents confusion and hidden free-riding.","zh":"當架構防止混亂和隱藏搭便車時，團隊會運作得更好。"},{"en":"This phrase describes the organisation needed for fair teamwork.","zh":"這個短語描述公平團隊合作所需的組織。"}],"source":"2025 Q4.pdf","sourcePage":4},{"front":"effective leadership","meaning":"有效領導","examples":[{"en":"Effective leadership can reduce conflict in teams.","zh":"有效領導可以減少團隊中的衝突。"},{"en":"Effective leadership means guidance that helps people work clearly, respectfully, and productively.","zh":"effective leadership 是幫助人們清晰、尊重而有成效地工作的引導。"},{"en":"A good leader sets expectations and invites quieter members to contribute.","zh":"好領袖會訂立期望，並邀請較沉默的成員作出貢獻。"},{"en":"Effective leadership prevents disagreements from becoming personal attacks.","zh":"有效領導防止分歧變成人身攻擊。"},{"en":"This phrase describes management that improves cooperation.","zh":"這個短語描述能改善合作的管理。"}],"source":"2025 Q4.pdf","sourcePage":4},{"front":"mutual accountability","meaning":"互相問責","examples":[{"en":"Teamwork needs a culture of mutual accountability.","zh":"團隊合作需要互相問責的文化。"},{"en":"Mutual accountability means team members hold one another responsible for agreed work.","zh":"mutual accountability 的意思是團隊成員互相要求為約定工作負責。"},{"en":"A team has mutual accountability when everyone reports progress honestly.","zh":"當每個人都誠實匯報進度時，團隊就有互相問責。"},{"en":"Mutual accountability prevents one person from carrying the whole burden silently.","zh":"互相問責防止一個人默默承擔全部負擔。"},{"en":"This phrase describes shared responsibility within a team.","zh":"這個短語描述團隊內的共同責任。"}],"source":"2025 Q4.pdf","sourcePage":4},{"front":"one major challenge","meaning":"一個主要挑戰","examples":[{"en":"One major challenge of group work is unequal effort.","zh":"小組工作的一個主要挑戰是付出不均。"},{"en":"One major challenge means one important problem that must be dealt with.","zh":"one major challenge 的意思是一個必須處理的重要問題。"},{"en":"One major challenge in teamwork is making sure contribution is fair.","zh":"團隊合作的一個主要挑戰是確保貢獻公平。"},{"en":"Identifying one major challenge helps the essay organise its argument clearly.","zh":"指出一個主要挑戰幫助文章清楚組織論點。"},{"en":"This phrase introduces a key difficulty.","zh":"這個短語引入關鍵困難。"}],"source":"2025 Q4.pdf","sourcePage":4},{"front":"unequal distribution of effort","meaning":"付出分配不均","examples":[{"en":"Unequal distribution of effort creates resentment in teams.","zh":"付出分配不均會在團隊中造成不滿。"},{"en":"Unequal distribution of effort means work is not shared fairly among members.","zh":"unequal distribution of effort 的意思是工作沒有在成員之間公平分配。"},{"en":"A project has unequal distribution of effort when two people do almost everything.","zh":"當兩個人幾乎完成所有事情時，項目就有付出分配不均。"},{"en":"This problem makes hardworking members feel used rather than respected.","zh":"這個問題令勤奮成員覺得被利用，而不是被尊重。"},{"en":"This phrase describes unfair workload in formal language.","zh":"這個短語以正式語言描述工作量不公平。"}],"source":"2025 Q4.pdf","sourcePage":4},{"front":"shoulder most of the burden","meaning":"承擔大部分負擔","examples":[{"en":"Some employees shoulder most of the burden.","zh":"有些員工承擔大部分負擔。"},{"en":"To shoulder most of the burden means to carry the largest part of the work or responsibility.","zh":"shoulder most of the burden 的意思是承擔最大部分的工作或責任。"},{"en":"In an unfair project, one member may shoulder most of the burden while others wait.","zh":"在不公平項目中，一名成員可能承擔大部分負擔，而其他人等待。"},{"en":"People who shoulder too much may become tired and resentful.","zh":"承擔太多的人可能變得疲倦和不滿。"},{"en":"This phrase describes hidden pressure on hardworking members.","zh":"這個短語描述勤奮成員身上的隱藏壓力。"}],"source":"2025 Q4.pdf","sourcePage":4},{"front":"contribute very little","meaning":"貢獻很少","examples":[{"en":"Some team members contribute very little.","zh":"有些團隊成員貢獻很少。"},{"en":"To contribute very little means to give only a small amount of effort, work, or ideas.","zh":"contribute very little 的意思是只付出很少努力、工作或想法。"},{"en":"A member contributes very little if he attends meetings but completes no tasks.","zh":"如果一名成員出席會議但不完成任務，他就是貢獻很少。"},{"en":"When some people contribute little, others may lose trust in the team.","zh":"當有些人貢獻很少，其他人可能失去對團隊的信任。"},{"en":"This phrase describes free-riding behaviour.","zh":"這個短語描述搭便車行為。"}],"source":"2025 Q4.pdf","sourcePage":4},{"front":"create resentment","meaning":"造成不滿","examples":[{"en":"Unequal effort creates resentment almost immediately.","zh":"付出不均幾乎即時造成不滿。"},{"en":"To create resentment means to cause anger or bitterness because something feels unfair.","zh":"create resentment 的意思是因某事感覺不公平而造成憤怒或怨氣。"},{"en":"Extra unpaid work can create resentment among diligent employees.","zh":"額外而未被承認的工作可以在勤奮員工之間造成不滿。"},{"en":"Resentment grows when people feel their effort is being taken for granted.","zh":"當人們覺得自己的努力被視為理所當然，不滿就會增長。"},{"en":"This phrase shows the emotional result of unfairness.","zh":"這個短語顯示不公平帶來的情緒結果。"}],"source":"2025 Q4.pdf","sourcePage":4},{"front":"almost immediately","meaning":"幾乎即時","examples":[{"en":"Resentment can grow almost immediately.","zh":"不滿可以幾乎即時增長。"},{"en":"Almost immediately means very soon after something happens.","zh":"almost immediately 的意思是某事發生後很快。"},{"en":"Team members may feel unfairness almost immediately if roles are unclear.","zh":"如果角色不清晰，團隊成員可能幾乎即時感到不公平。"},{"en":"This phrase shows that some reactions appear quickly.","zh":"這個短語顯示某些反應很快出現。"},{"en":"It is useful when describing a fast emotional effect.","zh":"當描述快速情緒影響時，它很有用。"}],"source":"2025 Q4.pdf","sourcePage":4},{"front":"diligent workers","meaning":"勤奮的員工","examples":[{"en":"Diligent workers may become frustrated by unfair teamwork.","zh":"勤奮的員工可能因不公平的團隊合作而感到沮喪。"},{"en":"Diligent workers are employees who work hard, carefully, and responsibly.","zh":"diligent workers 是努力、細心並負責任工作的員工。"},{"en":"Diligent workers may stay late to finish tasks others have ignored.","zh":"勤奮的員工可能留到很晚，完成其他人忽略的任務。"},{"en":"If diligent workers feel exploited, their motivation may decline.","zh":"如果勤奮的員工覺得被剝削，他們的動力可能下降。"},{"en":"This phrase describes reliable employees who can be harmed by unfair systems.","zh":"這個短語描述可能被不公平制度傷害的可靠員工。"}],"source":"2025 Q4.pdf","sourcePage":4},{"front":"be tied to","meaning":"與……掛鈎","examples":[{"en":"Their performance is tied to colleagues who are less committed.","zh":"他們的表現與較不投入的同事掛鈎。"},{"en":"Be tied to means be connected with or affected by something.","zh":"be tied to 的意思是與某事物相連或受其影響。"},{"en":"In group projects, one worker’s result may be tied to another person’s effort.","zh":"在小組項目中，一名員工的成果可能與另一人的努力掛鈎。"},{"en":"Employees feel frustrated when their reputation is tied to unreliable teammates.","zh":"當員工的聲譽與不可靠隊友掛鈎時，他們會感到沮喪。"},{"en":"This phrase describes dependence that may feel unfair.","zh":"這個短語描述可能令人覺得不公平的依賴關係。"}],"source":"2025 Q4.pdf","sourcePage":5},{"front":"less committed","meaning":"較不投入的","examples":[{"en":"Diligent workers may be tied to colleagues who are less committed.","zh":"勤奮的員工可能與較不投入的同事掛鈎。"},{"en":"Less committed means showing less effort, responsibility, or loyalty to the task.","zh":"less committed 的意思是對任務表現較少努力、責任感或投入。"},{"en":"A less committed teammate may miss meetings or submit weak work late.","zh":"較不投入的隊友可能缺席會議或遲交薄弱工作。"},{"en":"Working with less committed colleagues can discourage hardworking employees.","zh":"與較不投入的同事合作，可以令勤奮員工氣餒。"},{"en":"This phrase describes unequal dedication within a team.","zh":"這個短語描述團隊內投入程度不均。"}],"source":"2025 Q4.pdf","sourcePage":5},{"front":"motivation begins to decline","meaning":"動力開始下降","examples":[{"en":"Motivation begins to decline when teamwork feels unfair.","zh":"當團隊合作感覺不公平時，動力開始下降。"},{"en":"Motivation begins to decline means people slowly become less willing to work hard.","zh":"motivation begins to decline 的意思是人們慢慢變得較不願努力工作。"},{"en":"Workers lose motivation when their effort is not recognised.","zh":"當員工的努力不被認可，他們會失去動力。"},{"en":"Unfair teamwork can reduce energy even among high performers.","zh":"不公平的團隊合作即使在表現優秀者中也會減少能量。"},{"en":"This phrase describes the beginning of emotional and professional decline.","zh":"這個短語描述情緒和工作表現下降的開始。"}],"source":"2025 Q4.pdf","sourcePage":5},{"front":"instead of focusing on","meaning":"而不是專注於","examples":[{"en":"Workers may focus on unfairness instead of focusing on the task.","zh":"員工可能專注於不公平，而不是專注於任務。"},{"en":"Instead of focusing on means paying attention to one thing rather than another more useful thing.","zh":"instead of focusing on 的意思是把注意力放在某事上，而不是另一件更有用的事上。"},{"en":"Employees may argue about workload instead of focusing on the project goal.","zh":"員工可能爭論工作量，而不是專注於項目目標。"},{"en":"This phrase shows how unfairness distracts people from productive work.","zh":"這個短語顯示不公平如何令人生產力分心。"},{"en":"It is useful when comparing harmful and helpful attention.","zh":"當比較有害和有用的注意力時，它很有用。"}],"source":"2025 Q4.pdf","sourcePage":5},{"front":"the quality of the task","meaning":"任務質素","examples":[{"en":"Team members should focus on the quality of the task.","zh":"團隊成員應專注於任務質素。"},{"en":"The quality of the task means how well the work is completed.","zh":"quality of the task 的意思是工作完成得有多好。"},{"en":"The quality of the task improves when members check accuracy, clarity, and usefulness.","zh":"當成員檢查準確性、清晰度和有用性時，任務質素會改善。"},{"en":"Teams lose focus on quality when they become busy arguing about unfairness.","zh":"當團隊忙於爭論不公平時，就會失去對質素的專注。"},{"en":"This phrase describes the standard of the final work.","zh":"這個短語描述最終工作的標準。"}],"source":"2025 Q4.pdf","sourcePage":5},{"front":"become preoccupied with","meaning":"滿腦子想着；過分關注","examples":[{"en":"Workers become preoccupied with the unfairness of the process.","zh":"員工滿腦子想着過程的不公平。"},{"en":"Become preoccupied with means think about something too much so that it distracts you.","zh":"become preoccupied with 的意思是過分想着某事，以致被它分心。"},{"en":"Employees may become preoccupied with who is doing less work.","zh":"員工可能滿腦子想着誰做得較少。"},{"en":"When people are preoccupied with unfairness, their creativity and focus suffer.","zh":"當人們過分關注不公平，他們的創意和專注會受損。"},{"en":"This phrase describes mental distraction caused by concern.","zh":"這個短語描述由關注造成的精神分心。"}],"source":"2025 Q4.pdf","sourcePage":5},{"front":"the unfairness of the process","meaning":"過程的不公平","examples":[{"en":"Unequal effort makes workers focus on the unfairness of the process.","zh":"付出不均令員工專注於過程的不公平。"},{"en":"The unfairness of the process means the way work is organised or judged feels unjust.","zh":"unfairness of the process 的意思是工作被組織或評價的方式感覺不公正。"},{"en":"Workers notice the unfairness of the process when effort and credit do not match.","zh":"當努力和功勞不相符時，員工會注意到過程的不公平。"},{"en":"A fair process helps people trust the final result more.","zh":"公平過程幫助人們更信任最終結果。"},{"en":"This phrase describes a problem with how teamwork is managed.","zh":"這個短語描述團隊合作管理方式中的問題。"}],"source":"2025 Q4.pdf","sourcePage":5},{"front":"over time","meaning":"隨着時間過去","examples":[{"en":"Over time, unfair group work damages morale.","zh":"隨着時間過去，不公平的小組工作會打擊士氣。"},{"en":"Over time means gradually as days, weeks, or months pass.","zh":"over time 的意思是隨着日子、星期或月份過去而逐漸發生。"},{"en":"Over time, repeated unfairness can make even loyal workers lose energy.","zh":"隨着時間過去，重複的不公平可以令即使忠誠的員工也失去能量。"},{"en":"Small problems become serious over time if leaders ignore them.","zh":"如果領袖忽視小問題，它們會隨着時間過去變得嚴重。"},{"en":"This phrase describes gradual change.","zh":"這個短語描述逐漸變化。"}],"source":"2025 Q4.pdf","sourcePage":5},{"front":"damage morale","meaning":"打擊士氣","examples":[{"en":"Unequal effort can damage morale.","zh":"付出不均可以打擊士氣。"},{"en":"To damage morale means to reduce people’s confidence, enthusiasm, and willingness to work.","zh":"damage morale 的意思是削弱人們的信心、熱情和工作意願。"},{"en":"Poor leadership can damage morale if employees feel ignored.","zh":"如果員工覺得被忽視，差劣領導可以打擊士氣。"},{"en":"Morale suffers when hardworking members think fairness is impossible.","zh":"當勤奮成員認為公平不可能時，士氣會受損。"},{"en":"This phrase describes harm to a team’s spirit.","zh":"這個短語描述對團隊精神的傷害。"}],"source":"2025 Q4.pdf","sourcePage":5},{"front":"discourage high performers from","meaning":"令表現優秀者不願……","examples":[{"en":"Unfairness discourages high performers from cooperating wholeheartedly.","zh":"不公平令表現優秀者不願全心全意合作。"},{"en":"Discourage high performers from means make strong workers less willing to do something.","zh":"discourage high performers from 的意思是令能力強的員工較不願做某事。"},{"en":"Unequal credit may discourage high performers from joining future group projects.","zh":"不均等的功勞可能令表現優秀者不願加入未來小組項目。"},{"en":"When top employees feel exploited, they may protect themselves by doing less.","zh":"當頂尖員工覺得被剝削，他們可能透過少做來保護自己。"},{"en":"This phrase shows how unfair systems can waste talent.","zh":"這個短語顯示不公平制度如何浪費人才。"}],"source":"2025 Q4.pdf","sourcePage":5},{"front":"high performers","meaning":"表現優秀者","examples":[{"en":"High performers may become unwilling to join future projects.","zh":"表現優秀者可能變得不願加入未來項目。"},{"en":"High performers are employees who consistently produce strong results.","zh":"high performers 是持續產生優秀成果的員工。"},{"en":"High performers often take responsibility when a project becomes difficult.","zh":"表現優秀者常在項目變得困難時承擔責任。"},{"en":"If high performers are treated unfairly, the whole organisation may suffer.","zh":"如果表現優秀者受到不公平對待，整個機構都可能受損。"},{"en":"This phrase describes valuable workers whose motivation should be protected.","zh":"這個短語描述應被保護動力的有價值員工。"}],"source":"2025 Q4.pdf","sourcePage":6},{"front":"cooperate wholeheartedly","meaning":"全心全意合作","examples":[{"en":"High performers may stop cooperating wholeheartedly.","zh":"表現優秀者可能停止全心全意合作。"},{"en":"To cooperate wholeheartedly means to work with others with full effort and sincere commitment.","zh":"cooperate wholeheartedly 的意思是以全部努力和真誠投入與他人合作。"},{"en":"Employees cooperate wholeheartedly when they trust that work and credit will be fair.","zh":"當員工相信工作和功勞會公平時，他們會全心全意合作。"},{"en":"People stop cooperating wholeheartedly if they feel used by the team.","zh":"如果人們覺得被團隊利用，就會停止全心全意合作。"},{"en":"This phrase describes deep and willing teamwork.","zh":"這個短語描述深入而自願的團隊合作。"}],"source":"2025 Q4.pdf","sourcePage":6},{"front":"future projects","meaning":"未來項目","examples":[{"en":"Unfair group work may affect future projects.","zh":"不公平的小組工作可能影響未來項目。"},{"en":"Future projects are tasks or assignments that will happen later.","zh":"future projects 是將來會發生的任務或工作。"},{"en":"Workers may avoid future projects if past teamwork felt unfair.","zh":"如果過去的團隊合作感覺不公平，員工可能避開未來項目。"},{"en":"A bad team experience can damage willingness to collaborate again.","zh":"一次差劣的團隊經驗可以傷害再次合作的意願。"},{"en":"This phrase shows that present management affects later cooperation.","zh":"這個短語顯示目前管理會影響日後合作。"}],"source":"2025 Q4.pdf","sourcePage":6},{"front":"a simple example can be seen in","meaning":"一個簡單例子可見於","examples":[{"en":"A simple example can be seen in office presentations.","zh":"一個簡單例子可見於辦公室匯報。"},{"en":"A simple example can be seen in means an easy case appears in a particular situation.","zh":"a simple example can be seen in 的意思是某種情況中出現一個容易理解的例子。"},{"en":"A simple example can be seen in group reports where one person writes everything.","zh":"一個簡單例子可見於小組報告中，一個人寫完所有內容。"},{"en":"This phrase helps move from general argument to concrete illustration.","zh":"這個短語幫助由一般論點轉向具體說明。"},{"en":"It is useful in essays when explaining abstract problems.","zh":"在文章中解釋抽象問題時，它很有用。"}],"source":"2025 Q4.pdf","sourcePage":6},{"front":"office presentations","meaning":"辦公室匯報","examples":[{"en":"Office presentations often reveal unequal effort.","zh":"辦公室匯報常揭示付出不均。"},{"en":"Office presentations are formal talks or reports given in a workplace.","zh":"office presentations 是在職場中進行的正式演講或報告。"},{"en":"A team may prepare slides and present findings during an office presentation.","zh":"團隊可以在辦公室匯報中準備簡報並展示研究結果。"},{"en":"Office presentations reveal teamwork quality because preparation is shared.","zh":"辦公室匯報會揭示團隊合作質素，因為準備工作是共同完成的。"},{"en":"This phrase describes a common workplace task.","zh":"這個短語描述常見職場任務。"}],"source":"2025 Q4.pdf","sourcePage":6},{"front":"spend hours doing","meaning":"花數小時做……","examples":[{"en":"Two members may spend hours researching data.","zh":"兩名成員可能花數小時搜集數據。"},{"en":"To spend hours doing something means to use many hours on a task.","zh":"spend hours doing something 的意思是花很多小時做某項任務。"},{"en":"Employees may spend hours preparing charts before a client meeting.","zh":"員工可能在客戶會議前花數小時準備圖表。"},{"en":"Spending hours on work can feel unfair if others contribute very little.","zh":"如果其他人貢獻很少，花數小時工作會感覺不公平。"},{"en":"This phrase shows the amount of effort involved.","zh":"這個短語顯示投入的努力量。"}],"source":"2025 Q4.pdf","sourcePage":6},{"front":"researching data","meaning":"搜集數據","examples":[{"en":"Some members spend hours researching data.","zh":"有些成員花數小時搜集數據。"},{"en":"Researching data means collecting and studying information to support a task or decision.","zh":"researching data 的意思是收集和研究資料，以支持任務或決策。"},{"en":"A team member may research sales data before preparing a presentation.","zh":"團隊成員可以在準備匯報前搜集銷售數據。"},{"en":"Researching data takes time because facts must be checked carefully.","zh":"搜集數據需要時間，因為事實必須仔細核實。"},{"en":"This phrase describes a detailed contribution that may be invisible.","zh":"這個短語描述可能不明顯的細緻貢獻。"}],"source":"2025 Q4.pdf","sourcePage":6},{"front":"preparing slides","meaning":"準備簡報","examples":[{"en":"Some members spend hours preparing slides.","zh":"有些成員花數小時準備簡報。"},{"en":"Preparing slides means creating visual pages for a presentation.","zh":"preparing slides 的意思是為匯報製作視覺頁面。"},{"en":"Employees prepare slides by organising text, charts, images, and key messages.","zh":"員工透過組織文字、圖表、圖片和重點訊息來準備簡報。"},{"en":"Slide preparation can take many hours if the information is complex.","zh":"如果資訊複雜，準備簡報可以花很多小時。"},{"en":"This phrase describes practical work behind a presentation.","zh":"這個短語描述匯報背後的實際工作。"}],"source":"2025 Q4.pdf","sourcePage":6},{"front":"merely read from the script","meaning":"只是照稿讀","examples":[{"en":"Another member may merely read from the script.","zh":"另一名成員可能只是照稿讀。"},{"en":"To merely read from the script means only read prepared words without deeper contribution.","zh":"merely read from the script 的意思是只讀準備好的文字，而沒有更深貢獻。"},{"en":"A weak presenter may merely read from the script without understanding the research.","zh":"薄弱的匯報者可能只是照稿讀，而不理解研究內容。"},{"en":"Reading from a script can be useful, but it should not replace real preparation.","zh":"照稿讀可以有用，但不應取代真正準備。"},{"en":"This phrase criticises shallow participation.","zh":"這個短語批評表面的參與。"}],"source":"2025 Q4.pdf","sourcePage":6},{"front":"on the day itself","meaning":"在當日","examples":[{"en":"Another member may merely read from the script on the day itself.","zh":"另一名成員可能在當日只是照稿讀。"},{"en":"On the day itself means on the actual day when the event happens.","zh":"on the day itself 的意思是在活動真正發生的那一天。"},{"en":"A member may appear only on the day itself and still receive credit.","zh":"一名成員可能只在當日出現，卻仍獲得功勞。"},{"en":"This phrase highlights the contrast between preparation time and final performance.","zh":"這個短語突顯準備時間與最終表現之間的對比。"},{"en":"It is useful when showing unfair contribution.","zh":"當展示貢獻不公平時，它很有用。"}],"source":"2025 Q4.pdf","sourcePage":6},{"front":"receive equal credit","meaning":"獲得同等功勞","examples":[{"en":"A weak contributor may still receive equal credit.","zh":"貢獻薄弱的人仍可能獲得同等功勞。"},{"en":"To receive equal credit means to get the same recognition as others.","zh":"receive equal credit 的意思是得到與其他人相同的認可。"},{"en":"Team members feel unfairness when little work receives equal credit.","zh":"當少量工作獲得同等功勞時，團隊成員會感到不公平。"},{"en":"Equal credit can damage morale if contribution is not actually equal.","zh":"如果貢獻其實不相等，同等功勞可以打擊士氣。"},{"en":"This phrase describes a common complaint about group work.","zh":"這個短語描述關於小組工作的常見投訴。"}],"source":"2025 Q4.pdf","sourcePage":7},{"front":"to solve this problem","meaning":"為了解決這個問題","examples":[{"en":"To solve this problem, responsibilities should be divided clearly.","zh":"為了解決這個問題，責任應被清楚分配。"},{"en":"To solve this problem means in order to deal with this difficulty effectively.","zh":"to solve this problem 的意思是為了有效處理這個困難。"},{"en":"To solve this problem of uneven effort, managers can introduce individual evaluations.","zh":"為了解決付出不均這個問題，管理者可以引入個人評估。"},{"en":"This phrase introduces a practical response after describing a problem.","zh":"這個短語在描述問題後引入實際回應。"},{"en":"It helps make an essay solution-focused.","zh":"它幫助文章聚焦於解決方案。"}],"source":"2025 Q4.pdf","sourcePage":7},{"front":"divide responsibilities clearly","meaning":"清楚分配責任","examples":[{"en":"Responsibilities should be divided clearly from the outset.","zh":"責任應從一開始清楚分配。"},{"en":"To divide responsibilities clearly means to state exactly who is responsible for each task.","zh":"divide responsibilities clearly 的意思是明確說明誰負責每項任務。"},{"en":"A team can divide responsibilities clearly by assigning research, slides, and presentation roles.","zh":"團隊可以透過分配研究、簡報和演說角色來清楚分配責任。"},{"en":"Clear division prevents members from assuming someone else will do the work.","zh":"清晰分工防止成員假設別人會完成工作。"},{"en":"This phrase describes a basic tool for fair teamwork.","zh":"這個短語描述公平團隊合作的基本工具。"}],"source":"2025 Q4.pdf","sourcePage":7},{"front":"from the outset","meaning":"從一開始","examples":[{"en":"Responsibilities should be divided clearly from the outset.","zh":"責任應從一開始清楚分配。"},{"en":"From the outset means from the very beginning.","zh":"from the outset 的意思是從最開始。"},{"en":"From the outset, each member should know their role and deadline.","zh":"從一開始，每位成員就應知道自己的角色和限期。"},{"en":"Problems are easier to prevent when expectations are clear from the start.","zh":"當期望從開始就清楚時，問題較容易預防。"},{"en":"This phrase stresses early planning.","zh":"這個短語強調早期計劃。"}],"source":"2025 Q4.pdf","sourcePage":7},{"front":"a defined role","meaning":"明確角色","examples":[{"en":"Each member should have a defined role.","zh":"每位成員都應有明確角色。"},{"en":"A defined role is a clear responsibility assigned to a particular person.","zh":"defined role 是分配給特定人士的清晰責任。"},{"en":"One member may have a defined role as researcher, while another prepares slides.","zh":"一名成員可以有研究員的明確角色，而另一人準備簡報。"},{"en":"Defined roles reduce confusion and make contribution easier to evaluate.","zh":"明確角色減少混亂，並令貢獻更容易評估。"},{"en":"This phrase describes clarity in team organisation.","zh":"這個短語描述團隊組織中的清晰度。"}],"source":"2025 Q4.pdf","sourcePage":7},{"front":"a measurable output","meaning":"可衡量的成果","examples":[{"en":"Each member should have a deadline and a measurable output.","zh":"每位成員都應有期限和可衡量的成果。"},{"en":"A measurable output is a result that can be checked, counted, or evaluated.","zh":"measurable output 是可以被檢查、計算或評估的結果。"},{"en":"A measurable output may be three research sources, five slides, or a written summary.","zh":"可衡量成果可以是三個研究來源、五張簡報或一份書面摘要。"},{"en":"Measurable outputs make contribution visible rather than vague.","zh":"可衡量成果令貢獻變得可見，而不是模糊。"},{"en":"This phrase helps teams turn responsibility into concrete work.","zh":"這個短語幫助團隊把責任變成具體工作。"}],"source":"2025 Q4.pdf","sourcePage":7},{"front":"introduce progress checks","meaning":"引入進度檢查","examples":[{"en":"Managers can introduce progress checks.","zh":"管理者可以引入進度檢查。"},{"en":"To introduce progress checks means to create regular moments for reviewing how work is developing.","zh":"introduce progress checks 的意思是建立定期檢視工作進展的時刻。"},{"en":"A manager may introduce weekly progress checks to see whether tasks are on schedule.","zh":"管理者可以引入每週進度檢查，了解任務是否按時進行。"},{"en":"Progress checks prevent problems from being discovered only at the last minute.","zh":"進度檢查防止問題到最後一刻才被發現。"},{"en":"This phrase describes a practical management measure.","zh":"這個短語描述實際管理措施。"}],"source":"2025 Q4.pdf","sourcePage":7},{"front":"individual evaluations","meaning":"個人評估","examples":[{"en":"Individual evaluations can make contribution visible.","zh":"個人評估可以令貢獻變得可見。"},{"en":"Individual evaluations are assessments of each person’s work rather than the group’s work alone.","zh":"individual evaluations 是評估每個人的工作，而不只是評估整個小組。"},{"en":"A manager may use individual evaluations to see who completed which task.","zh":"管理者可以使用個人評估來了解誰完成了哪些任務。"},{"en":"Individual evaluations can reduce free-riding because effort is recorded separately.","zh":"個人評估可以減少搭便車，因為努力被分開記錄。"},{"en":"This phrase describes a tool for fairness in group work.","zh":"這個短語描述小組工作中促進公平的工具。"}],"source":"2025 Q4.pdf","sourcePage":7},{"front":"contribution becomes visible","meaning":"貢獻變得可見","examples":[{"en":"Contribution should become visible rather than assumed.","zh":"貢獻應變得可見，而不是被假定。"},{"en":"Contribution becomes visible means each person’s work can be seen, checked, or recognised.","zh":"contribution becomes visible 的意思是每個人的工作可以被看見、檢查或認可。"},{"en":"Progress reports help contribution become visible during a project.","zh":"進度報告幫助貢獻在項目期間變得可見。"},{"en":"Visible contribution makes teamwork feel fairer to diligent workers.","zh":"可見的貢獻令勤奮員工覺得團隊合作更公平。"},{"en":"This phrase shows why accountability needs evidence.","zh":"這個短語顯示問責為何需要證據。"}],"source":"2025 Q4.pdf","sourcePage":7},{"front":"rather than assumed","meaning":"而不是被假定","examples":[{"en":"Contribution should be visible rather than assumed.","zh":"貢獻應是可見的，而不是被假定。"},{"en":"Rather than assumed means instead of being guessed or taken for granted.","zh":"rather than assumed 的意思是而不是被猜測或視為理所當然。"},{"en":"Managers should check completed work rather than assume everyone contributed equally.","zh":"管理者應檢查已完成工作，而不是假定人人貢獻相同。"},{"en":"This phrase contrasts evidence with guesswork.","zh":"這個短語把證據與猜測作對比。"},{"en":"It is useful when discussing fair assessment.","zh":"當討論公平評估時，它很有用。"}],"source":"2025 Q4.pdf","sourcePage":7},{"front":"be built into the system","meaning":"被納入制度之中","examples":[{"en":"Accountability should be built into the system.","zh":"問責應被納入制度之中。"},{"en":"Be built into the system means be included as a normal part of the process.","zh":"be built into the system 的意思是被包括成為流程的正常部分。"},{"en":"Progress checks and individual evaluations can be built into the system.","zh":"進度檢查和個人評估可以被納入制度之中。"},{"en":"When accountability is built in, fairness does not depend only on goodwill.","zh":"當問責被納入制度，公平就不只依賴善意。"},{"en":"This phrase describes structural support for teamwork.","zh":"這個短語描述對團隊合作的制度性支援。"}],"source":"2025 Q4.pdf","sourcePage":8},{"front":"stop feeling like exploitation","meaning":"不再感覺像被剝削","examples":[{"en":"Teamwork stops feeling like exploitation when accountability is clear.","zh":"當問責清晰時，團隊合作不再感覺像被剝削。"},{"en":"Stop feeling like exploitation means no longer seem as if some people are being unfairly used.","zh":"stop feeling like exploitation 的意思是不再看似有些人被不公平地利用。"},{"en":"Group work stops feeling like exploitation when everyone’s tasks are visible.","zh":"當每個人的任務都可見，小組工作不再感覺像被剝削。"},{"en":"Clear accountability reassures hardworking members that they will not carry everything alone.","zh":"清晰問責令勤奮成員放心，知道自己不會獨自承擔一切。"},{"en":"This phrase shows how fairness changes emotional experience.","zh":"這個短語顯示公平如何改變情緒經驗。"}],"source":"2025 Q4.pdf","sourcePage":8},{"front":"genuine collaboration","meaning":"真正合作","examples":[{"en":"Fair teamwork starts feeling like genuine collaboration.","zh":"公平團隊合作開始感覺像真正合作。"},{"en":"Genuine collaboration is real cooperation in which members contribute honestly and meaningfully.","zh":"genuine collaboration 是成員誠實而有意義地貢獻的真正合作。"},{"en":"A team shows genuine collaboration when ideas, tasks, and credit are shared fairly.","zh":"當想法、任務和功勞被公平分享時，團隊就展現真正合作。"},{"en":"Genuine collaboration feels different from forced group work.","zh":"真正合作感覺不同於被迫的小組工作。"},{"en":"This phrase describes teamwork at its best.","zh":"這個短語描述團隊合作的最佳狀態。"}],"source":"2025 Q4.pdf","sourcePage":8},{"front":"a second difficulty","meaning":"第二個困難","examples":[{"en":"A second difficulty is poor communication.","zh":"第二個困難是溝通不善。"},{"en":"A second difficulty means another important problem after the first one.","zh":"a second difficulty 的意思是在第一個問題之後的另一個重要問題。"},{"en":"A second difficulty in group work is that members may misunderstand instructions.","zh":"小組工作的第二個困難是成員可能誤解指示。"},{"en":"This phrase helps organise an essay into clear points.","zh":"這個短語幫助文章組織成清晰要點。"},{"en":"It signals that the discussion is moving to another challenge.","zh":"它表示討論正轉向另一個挑戰。"}],"source":"2025 Q4.pdf","sourcePage":8},{"front":"quietly ruin","meaning":"悄悄破壞","examples":[{"en":"Poor communication can quietly ruin even a talented team.","zh":"溝通不善可以悄悄破壞即使有才能的團隊。"},{"en":"To quietly ruin something means to damage it slowly or invisibly.","zh":"quietly ruin something 的意思是慢慢或不明顯地傷害某事。"},{"en":"Unclear instructions can quietly ruin a project before anyone notices.","zh":"不清晰指示可以在沒有人注意前悄悄破壞項目。"},{"en":"Communication problems are dangerous because they may not look dramatic at first.","zh":"溝通問題很危險，因為起初未必看起來戲劇化。"},{"en":"This phrase shows hidden damage.","zh":"這個短語顯示隱藏傷害。"}],"source":"2025 Q4.pdf","sourcePage":8},{"front":"talented team","meaning":"有才能的團隊","examples":[{"en":"Poor communication can ruin even a talented team.","zh":"溝通不善可以破壞即使有才能的團隊。"},{"en":"A talented team is a group with capable, skilled, or intelligent members.","zh":"talented team 是由有能力、有技能或聰明成員組成的團隊。"},{"en":"A talented team may still fail if members work in different directions.","zh":"如果成員朝不同方向工作，有才能的團隊仍可能失敗。"},{"en":"Talent needs coordination before it can become strong results.","zh":"才能需要協調，才能變成佳績。"},{"en":"This phrase shows that ability alone is not enough.","zh":"這個短語顯示單靠能力並不足夠。"}],"source":"2025 Q4.pdf","sourcePage":8},{"front":"not because…, but because…","meaning":"不是因為……而是因為……","examples":[{"en":"Group work often fails not because members lack ability, but because they misunderstand expectations.","zh":"小組工作常失敗，不是因為成員缺乏能力，而是因為他們誤解期望。"},{"en":"Not because A, but because B means B is the real reason, not A.","zh":"not because A, but because B 的意思是真正原因是 B，而不是 A。"},{"en":"A team may fail not because people are lazy, but because roles are unclear.","zh":"團隊可能失敗，不是因為人們懶惰，而是因為角色不清晰。"},{"en":"This structure corrects a simple explanation and gives a deeper cause.","zh":"這個結構修正簡單解釋，並給出更深層原因。"},{"en":"It is useful when analysing problems fairly.","zh":"當公平分析問題時，它很有用。"}],"source":"2025 Q4.pdf","sourcePage":8},{"front":"lack ability","meaning":"缺乏能力","examples":[{"en":"Group work may fail even when members do not lack ability.","zh":"即使成員並不缺乏能力，小組工作也可能失敗。"},{"en":"To lack ability means not to have enough skill or competence.","zh":"lack ability 的意思是沒有足夠技能或能力。"},{"en":"A worker may not lack ability but still fail if instructions are unclear.","zh":"員工可能不缺乏能力，但如果指示不清仍會失敗。"},{"en":"Teams should not assume failure always means people lack ability.","zh":"團隊不應假設失敗總是代表人們缺乏能力。"},{"en":"This phrase separates skill problems from communication problems.","zh":"這個短語把技能問題與溝通問題分開。"}],"source":"2025 Q4.pdf","sourcePage":8},{"front":"misunderstand one another’s expectations","meaning":"誤解彼此的期望","examples":[{"en":"Team members may misunderstand one another’s expectations.","zh":"團隊成員可能誤解彼此的期望。"},{"en":"To misunderstand one another’s expectations means to have different ideas about what others want or require.","zh":"misunderstand one another’s expectations 的意思是對別人想要或要求的東西有不同理解。"},{"en":"One member may expect a detailed report while another prepares only a short summary.","zh":"一名成員可能期望詳細報告，而另一人只準備簡短摘要。"},{"en":"Misunderstood expectations can waste time and create conflict.","zh":"誤解期望可以浪費時間並造成衝突。"},{"en":"This phrase describes a communication failure in teams.","zh":"這個短語描述團隊中的溝通失誤。"}],"source":"2025 Q4.pdf","sourcePage":8},{"front":"tasks are vaguely assigned","meaning":"任務被含糊分配","examples":[{"en":"Tasks are vaguely assigned when instructions are unclear.","zh":"當指示不清時，任務被含糊分配。"},{"en":"Tasks are vaguely assigned means duties are given in an unclear or imprecise way.","zh":"tasks are vaguely assigned 的意思是職責以不清楚或不精確的方式被分配。"},{"en":"A manager vaguely assigns tasks by saying “handle the research” without explaining what is needed.","zh":"管理者只說「處理研究」而不解釋需要甚麼，就是含糊分配任務。"},{"en":"Vague assignments can lead to duplicated work and missed details.","zh":"含糊分配可以導致重複工作和遺漏細節。"},{"en":"This phrase describes a problem at the start of teamwork.","zh":"這個短語描述團隊合作開始時的問題。"}],"source":"2025 Q4.pdf","sourcePage":8},{"front":"duplicate work","meaning":"重複工作","examples":[{"en":"Employees may duplicate work because of poor communication.","zh":"員工可能因溝通不善而重複工作。"},{"en":"To duplicate work means to repeat work that someone else has already done.","zh":"duplicate work 的意思是重複做其他人已完成的工作。"},{"en":"Two departments may duplicate work if they do not share updates.","zh":"如果兩個部門沒有分享更新，它們可能重複工作。"},{"en":"Duplicated work wastes time and can delay the whole project.","zh":"重複工作浪費時間，並可能延誤整個項目。"},{"en":"This phrase describes inefficiency caused by unclear coordination.","zh":"這個短語描述由協調不清造成的低效率。"}],"source":"2025 Q4.pdf","sourcePage":9},{"front":"overlook crucial details","meaning":"忽略關鍵細節","examples":[{"en":"Employees may overlook crucial details.","zh":"員工可能忽略關鍵細節。"},{"en":"To overlook crucial details means to fail to notice important information.","zh":"overlook crucial details 的意思是未能注意重要資訊。"},{"en":"A team may overlook crucial details if no one is responsible for checking the final report.","zh":"如果沒有人負責檢查最終報告，團隊可能忽略關鍵細節。"},{"en":"Overlooked details can turn small mistakes into costly problems.","zh":"被忽略的細節可以把小錯誤變成代價高昂的問題。"},{"en":"This phrase warns that unclear responsibility can damage quality.","zh":"這個短語提醒責任不清會損害質素。"}],"source":"2025 Q4.pdf","sourcePage":9},{"front":"proceed in different directions","meaning":"朝不同方向進行","examples":[{"en":"Team members may proceed in completely different directions.","zh":"團隊成員可能朝完全不同方向進行。"},{"en":"To proceed in different directions means to continue working toward different aims or plans.","zh":"proceed in different directions 的意思是繼續朝不同目標或計劃工作。"},{"en":"One member may focus on cost while another focuses on design without coordination.","zh":"一名成員可能專注成本，而另一人專注設計，卻沒有協調。"},{"en":"Teams waste effort when members proceed in different directions.","zh":"當成員朝不同方向進行時，團隊會浪費努力。"},{"en":"This phrase describes lack of shared understanding.","zh":"這個短語描述缺乏共同理解。"}],"source":"2025 Q4.pdf","sourcePage":9},{"front":"as a result","meaning":"結果","examples":[{"en":"As a result, time is wasted correcting mistakes.","zh":"結果，時間被浪費在改正錯誤上。"},{"en":"As a result means because of what happened before, this consequence follows.","zh":"as a result 的意思是因之前發生的事，所以產生這個後果。"},{"en":"The task was unclear; as a result, two members produced the same report.","zh":"任務不清晰；結果，兩名成員做出了同一份報告。"},{"en":"This phrase connects cause and effect.","zh":"這個短語連接原因和結果。"},{"en":"It is useful when explaining the consequence of poor teamwork.","zh":"當解釋差劣團隊合作的後果時，它很有用。"}],"source":"2025 Q4.pdf","sourcePage":9},{"front":"time is wasted","meaning":"時間被浪費","examples":[{"en":"Time is wasted correcting preventable mistakes.","zh":"時間被浪費在改正可避免的錯誤上。"},{"en":"Time is wasted means hours are used without real progress or value.","zh":"time is wasted 的意思是時間被用掉，卻沒有真正進展或價值。"},{"en":"Time is wasted when teams redo work that could have been done correctly first.","zh":"當團隊重做本可以一開始就做對的工作時，時間被浪費。"},{"en":"Poor communication wastes time because people must repair avoidable errors.","zh":"溝通不善浪費時間，因為人們必須修補可避免的錯誤。"},{"en":"This phrase describes lost efficiency.","zh":"這個短語描述效率流失。"}],"source":"2025 Q4.pdf","sourcePage":9},{"front":"correcting mistakes","meaning":"改正錯誤","examples":[{"en":"Teams may waste time correcting mistakes.","zh":"團隊可能浪費時間改正錯誤。"},{"en":"Correcting mistakes means finding errors and fixing them.","zh":"correcting mistakes 的意思是找出錯誤並修正它們。"},{"en":"A team may spend an afternoon correcting mistakes in duplicated slides.","zh":"團隊可能花一個下午改正重複簡報中的錯誤。"},{"en":"Correcting mistakes is necessary, but preventable mistakes should be avoided.","zh":"改正錯誤是必要的，但應避免可預防的錯誤。"},{"en":"This phrase describes repair work after something has gone wrong.","zh":"這個短語描述出錯後的修補工作。"}],"source":"2025 Q4.pdf","sourcePage":9},{"front":"could have been prevented","meaning":"原本可以被避免","examples":[{"en":"These mistakes could have been prevented through simple clarification.","zh":"這些錯誤原本可以透過簡單澄清被避免。"},{"en":"Could have been prevented means could have been avoided if better action had been taken earlier.","zh":"could have been prevented 的意思是如果較早採取更好行動，原本可以避免。"},{"en":"The duplicated research could have been prevented by a short planning meeting.","zh":"重複研究原本可以透過簡短計劃會議被避免。"},{"en":"This phrase shows regret about an avoidable problem.","zh":"這個短語顯示對可避免問題的遺憾。"},{"en":"It is useful when explaining why prevention matters.","zh":"當解釋預防為何重要時，它很有用。"}],"source":"2025 Q4.pdf","sourcePage":9},{"front":"simple clarification","meaning":"簡單澄清","examples":[{"en":"Simple clarification can prevent costly mistakes.","zh":"簡單澄清可以防止代價高昂的錯誤。"},{"en":"Simple clarification means a brief explanation that makes something clear.","zh":"simple clarification 是令某事清楚的簡短解釋。"},{"en":"Asking “Who is responsible for the data?” is a simple clarification.","zh":"問「誰負責數據？」就是簡單澄清。"},{"en":"Simple clarification early in a project can save hours later.","zh":"項目初期的簡單澄清可以在之後節省數小時。"},{"en":"This phrase describes an easy way to reduce confusion.","zh":"這個短語描述減少混亂的簡單方法。"}],"source":"2025 Q4.pdf","sourcePage":9},{"front":"especially serious","meaning":"尤其嚴重","examples":[{"en":"This problem is especially serious in large organisations.","zh":"這個問題在大型機構中尤其嚴重。"},{"en":"Especially serious means particularly important, worrying, or harmful.","zh":"especially serious 的意思是特別重要、令人擔心或有害。"},{"en":"Poor communication is especially serious when many departments depend on one another.","zh":"當許多部門互相依賴時，溝通不善尤其嚴重。"},{"en":"A small misunderstanding can become especially serious in a large project.","zh":"在大型項目中，小誤解可以變得尤其嚴重。"},{"en":"This phrase marks a problem as more severe in certain conditions.","zh":"這個短語指出某問題在特定條件下更嚴重。"}],"source":"2025 Q4.pdf","sourcePage":9},{"front":"large organisations","meaning":"大型機構","examples":[{"en":"Poor communication is common in large organisations.","zh":"溝通不善在大型機構中很常見。"},{"en":"Large organisations are big companies or institutions with many employees and departments.","zh":"large organisations 是有很多員工和部門的大公司或機構。"},{"en":"Large organisations may struggle because information has to pass through many levels.","zh":"大型機構可能遇到困難，因為資訊需要經過很多層級。"},{"en":"Clear systems are important in large organisations to prevent confusion.","zh":"在大型機構中，清晰制度對防止混亂很重要。"},{"en":"This phrase describes a workplace where communication is more complex.","zh":"這個短語描述溝通較複雜的職場。"}],"source":"2025 Q4.pdf","sourcePage":9},{"front":"departments such as","meaning":"例如……等部門","examples":[{"en":"Departments such as marketing, finance, and operations may use different language.","zh":"市場推廣、財務和營運等部門可能使用不同語言。"},{"en":"Departments such as means departments of the kind listed as examples.","zh":"departments such as 的意思是例如所列出的那些部門。"},{"en":"Departments such as human resources and sales may have different priorities.","zh":"人力資源和銷售等部門可能有不同優先事項。"},{"en":"This phrase introduces examples without listing every department.","zh":"這個短語引入例子，而不需要列出所有部門。"},{"en":"It is useful for explaining differences inside organisations.","zh":"它適合用來解釋機構內部差異。"}],"source":"2025 Q4.pdf","sourcePage":10},{"front":"marketing, finance and operations","meaning":"市場推廣、財務和營運","examples":[{"en":"Marketing, finance, and operations may have different priorities.","zh":"市場推廣、財務和營運可能有不同優先事項。"},{"en":"Marketing, finance and operations are departments that handle promotion, money, and daily business processes.","zh":"marketing, finance and operations 是處理宣傳、金錢和日常業務流程的部門。"},{"en":"Marketing may want speed, finance may control budgets, and operations may focus on delivery.","zh":"市場推廣可能追求速度，財務可能控制預算，營運可能專注交付。"},{"en":"These departments must communicate clearly because their goals may differ.","zh":"這些部門必須清晰溝通，因為它們的目標可能不同。"},{"en":"This phrase names common business functions involved in teamwork.","zh":"這個短語點出團隊合作中常見的商業職能。"}],"source":"2025 Q4.pdf","sourcePage":10},{"front":"professional language","meaning":"專業用語","examples":[{"en":"Different departments may use different professional language.","zh":"不同部門可能使用不同專業用語。"},{"en":"Professional language means specialised words used in a particular job or field.","zh":"professional language 是特定工作或領域使用的專門詞語。"},{"en":"Finance staff may use professional language that designers do not immediately understand.","zh":"財務人員可能使用設計師不能立即理解的專業用語。"},{"en":"Professional language can help experts be precise, but it can also confuse other departments.","zh":"專業用語可以幫助專家精準表達，但也可能令其他部門混亂。"},{"en":"This phrase explains one cause of workplace misunderstanding.","zh":"這個短語解釋職場誤解的一個原因。"}],"source":"2025 Q4.pdf","sourcePage":10},{"front":"priorities","meaning":"優先事項","examples":[{"en":"Departments may have different priorities.","zh":"部門可能有不同優先事項。"},{"en":"Priorities are the things considered most important and dealt with first.","zh":"priorities 是被視為最重要並首先處理的事情。"},{"en":"A marketing team’s priority may be speed, while a compliance team’s priority may be safety.","zh":"市場推廣團隊的優先事項可能是速度，而合規團隊的優先事項可能是安全。"},{"en":"Different priorities can create tension if teams do not explain their reasons.","zh":"如果團隊不解釋原因，不同優先事項可以造成緊張。"},{"en":"This word describes what guides decisions.","zh":"這個詞描述引導決策的東西。"}],"source":"2025 Q4.pdf","sourcePage":10},{"front":"push for speed","meaning":"追求速度","examples":[{"en":"A product team may push for speed.","zh":"產品團隊可能追求速度。"},{"en":"To push for speed means to strongly encourage faster action or quicker results.","zh":"push for speed 的意思是強烈推動更快行動或更快結果。"},{"en":"A product team may push for speed when a launch date is close.","zh":"當推出日期臨近時，產品團隊可能追求速度。"},{"en":"Pushing for speed can help progress, but it may create risk if caution is ignored.","zh":"追求速度可以幫助進展，但如果忽視謹慎，可能帶來風險。"},{"en":"This phrase describes pressure toward faster completion.","zh":"這個短語描述對更快完成的壓力。"}],"source":"2025 Q4.pdf","sourcePage":10},{"front":"compliance team","meaning":"合規團隊","examples":[{"en":"The compliance team may insist on caution.","zh":"合規團隊可能堅持謹慎。"},{"en":"A compliance team is a group responsible for making sure rules, laws, and standards are followed.","zh":"compliance team 是負責確保規則、法律和標準被遵守的團隊。"},{"en":"The compliance team may review a product before it is released to customers.","zh":"合規團隊可能在產品向顧客推出前進行審查。"},{"en":"Compliance staff may seem slow, but they protect the company from serious risk.","zh":"合規人員可能看似緩慢，但他們保護公司免受嚴重風險。"},{"en":"This phrase describes a department focused on rules and safety.","zh":"這個短語描述專注規則和安全的部門。"}],"source":"2025 Q4.pdf","sourcePage":10},{"front":"insist on caution","meaning":"堅持謹慎","examples":[{"en":"The compliance team may insist on caution.","zh":"合規團隊可能堅持謹慎。"},{"en":"To insist on caution means to strongly require careful action to avoid risk.","zh":"insist on caution 的意思是強烈要求小心行動，以避免風險。"},{"en":"A legal department may insist on caution before approving an advertisement.","zh":"法律部門可能在批准廣告前堅持謹慎。"},{"en":"Insisting on caution can frustrate fast-moving teams but prevent costly mistakes.","zh":"堅持謹慎可能令追求速度的團隊沮喪，但能防止代價高昂的錯誤。"},{"en":"This phrase describes firm concern for safety and responsibility.","zh":"這個短語描述對安全和責任的堅定關注。"}],"source":"2025 Q4.pdf","sourcePage":10},{"front":"differing aims","meaning":"不同目標","examples":[{"en":"Differing aims can delay the entire project.","zh":"不同目標可以延誤整個項目。"},{"en":"Differing aims are different goals held by different people or departments.","zh":"differing aims 是不同人或部門持有的不同目標。"},{"en":"One team may aim for speed while another aims for legal safety.","zh":"一個團隊可能追求速度，而另一個團隊追求法律安全。"},{"en":"Differing aims cause problems when nobody creates a shared objective.","zh":"當沒有人建立共同目標時，不同目標會造成問題。"},{"en":"This phrase describes conflicting directions inside a project.","zh":"這個短語描述項目內部互相衝突的方向。"}],"source":"2025 Q4.pdf","sourcePage":10},{"front":"delay the entire project","meaning":"延誤整個項目","examples":[{"en":"Poor communication can delay the entire project.","zh":"溝通不善可以延誤整個項目。"},{"en":"To delay the entire project means to make the whole piece of work finish later than planned.","zh":"delay the entire project 的意思是令整個工作比計劃更遲完成。"},{"en":"A missing approval can delay the entire project by several weeks.","zh":"一項缺失的批准可以令整個項目延誤數星期。"},{"en":"Delays become more likely when departments misunderstand one another’s priorities.","zh":"當部門誤解彼此優先事項時，延誤更可能發生。"},{"en":"This phrase describes a serious result of weak coordination.","zh":"這個短語描述協調薄弱的嚴重結果。"}],"source":"2025 Q4.pdf","sourcePage":10},{"front":"not merely “talking more”","meaning":"不只是「多說話」","examples":[{"en":"The solution is not merely “talking more”.","zh":"解決方法不只是「多說話」。"},{"en":"Not merely talking more means the answer is not just having more conversation.","zh":"not merely talking more 的意思是答案不只是進行更多對話。"},{"en":"A team can talk more but still remain confused if messages are vague.","zh":"如果訊息含糊，團隊即使多說話仍會混亂。"},{"en":"Better communication needs structure, precision, and records.","zh":"更好溝通需要架構、精準和紀錄。"},{"en":"This phrase rejects a shallow solution.","zh":"這個短語否定表面解決方法。"}],"source":"2025 Q4.pdf","sourcePage":10},{"front":"communicating more precisely","meaning":"更精準地溝通","examples":[{"en":"The solution is communicating more precisely.","zh":"解決方法是更精準地溝通。"},{"en":"Communicating more precisely means sharing information with clearer words, details, and expectations.","zh":"communicating more precisely 的意思是以更清晰文字、細節和期望分享資訊。"},{"en":"A manager communicates precisely by stating the deadline, owner, and required output.","zh":"管理者透過說明限期、負責人和所需成果來精準溝通。"},{"en":"Precise communication prevents people from guessing what others mean.","zh":"精準溝通防止人們猜測別人的意思。"},{"en":"This phrase describes a better standard of workplace communication.","zh":"這個短語描述更好的職場溝通標準。"}],"source":"2025 Q4.pdf","sourcePage":11},{"front":"shared objective","meaning":"共同目標","examples":[{"en":"Teams should begin with a shared objective.","zh":"團隊應以共同目標開始。"},{"en":"A shared objective is a common goal understood by all members.","zh":"shared objective 是所有成員都理解的共同目標。"},{"en":"A shared objective helps marketing, finance, and operations move in the same direction.","zh":"共同目標幫助市場推廣、財務和營運朝同一方向前進。"},{"en":"Without a shared objective, departments may protect their own priorities only.","zh":"沒有共同目標，部門可能只保護自己的優先事項。"},{"en":"This phrase describes the foundation of coordinated teamwork.","zh":"這個短語描述協調團隊合作的基礎。"}],"source":"2025 Q4.pdf","sourcePage":11},{"front":"realistic timeline","meaning":"實際可行的時間表","examples":[{"en":"A realistic timeline helps teams coordinate their work.","zh":"實際可行的時間表幫助團隊協調工作。"},{"en":"A realistic timeline is a schedule that can actually be followed.","zh":"realistic timeline 是真正能被遵守的時間安排。"},{"en":"A team creates a realistic timeline by considering workload, approvals, and possible delays.","zh":"團隊透過考慮工作量、批准流程和可能延誤來制定實際可行的時間表。"},{"en":"Unrealistic timelines can create stress and rushed mistakes.","zh":"不切實際的時間表可以造成壓力和匆忙錯誤。"},{"en":"This phrase describes practical planning of time.","zh":"這個短語描述實際的時間規劃。"}],"source":"2025 Q4.pdf","sourcePage":11},{"front":"agreed channels for updates","meaning":"約定好的更新渠道","examples":[{"en":"Teams need agreed channels for updates.","zh":"團隊需要約定好的更新渠道。"},{"en":"Agreed channels for updates are the tools or places everyone uses to share progress information.","zh":"agreed channels for updates 是所有人用來分享進度資訊的工具或地方。"},{"en":"A team may agree to use email for decisions and a project app for daily updates.","zh":"團隊可以約定用電郵處理決定，用項目應用程式作每日更新。"},{"en":"Agreed channels prevent important messages from being lost across different apps.","zh":"約定好的渠道防止重要訊息在不同應用程式之間遺失。"},{"en":"This phrase describes organised communication.","zh":"這個短語描述有組織的溝通。"}],"source":"2025 Q4.pdf","sourcePage":11},{"front":"brief but regular meetings","meaning":"簡短但定期的會議","examples":[{"en":"Brief but regular meetings can reduce confusion.","zh":"簡短但定期的會議可以減少混亂。"},{"en":"Brief but regular meetings are short meetings held consistently.","zh":"brief but regular meetings 是持續舉行的短會議。"},{"en":"A ten-minute weekly meeting can help members confirm tasks and deadlines.","zh":"每週十分鐘會議可以幫助成員確認任務和限期。"},{"en":"Regular meetings work best when they are focused and not too long.","zh":"定期會議在有焦點且不太長時最有效。"},{"en":"This phrase describes a balanced communication habit.","zh":"這個短語描述平衡的溝通習慣。"}],"source":"2025 Q4.pdf","sourcePage":11},{"front":"written summaries","meaning":"書面摘要","examples":[{"en":"Written summaries help teams remember decisions.","zh":"書面摘要幫助團隊記住決定。"},{"en":"Written summaries are short written records of key points, decisions, and next steps.","zh":"written summaries 是記錄重點、決定和下一步的簡短書面紀錄。"},{"en":"After a meeting, a written summary can show who is responsible for each task.","zh":"會議後，書面摘要可以顯示誰負責每項任務。"},{"en":"Written summaries reduce confusion because people can check the record later.","zh":"書面摘要減少混亂，因為人們之後可以查看紀錄。"},{"en":"This phrase describes a simple tool for workplace clarity.","zh":"這個短語描述促進職場清晰度的簡單工具。"}],"source":"2025 Q4.pdf","sourcePage":11},{"front":"digital project-management tools","meaning":"數碼項目管理工具","examples":[{"en":"Digital project-management tools can reduce confusion substantially.","zh":"數碼項目管理工具可以大幅減少混亂。"},{"en":"Digital project-management tools are online systems used to organise tasks, deadlines, files, and updates.","zh":"digital project-management tools 是用來組織任務、限期、文件和更新的網上系統。"},{"en":"Such tools can show who owns each task and when it is due.","zh":"這類工具可以顯示誰負責每項任務以及何時到期。"},{"en":"They help teams coordinate work without relying only on memory.","zh":"它們幫助團隊協調工作，而不只依賴記憶。"},{"en":"This phrase describes technology that supports teamwork.","zh":"這個短語描述支援團隊合作的科技。"}],"source":"2025 Q4.pdf","sourcePage":11},{"front":"reduce confusion substantially","meaning":"大幅減少混亂","examples":[{"en":"Clear tools can reduce confusion substantially.","zh":"清晰工具可以大幅減少混亂。"},{"en":"Reduce confusion substantially means make confusion much less serious or frequent.","zh":"reduce confusion substantially 的意思是大大降低混亂的嚴重程度或出現頻率。"},{"en":"Written summaries and task boards can reduce confusion substantially.","zh":"書面摘要和任務板可以大幅減少混亂。"},{"en":"Teams work faster when unclear expectations are greatly reduced.","zh":"當不清晰期望大幅減少，團隊工作會更快。"},{"en":"This phrase describes a strong improvement in clarity.","zh":"這個短語描述清晰度的強烈改善。"}],"source":"2025 Q4.pdf","sourcePage":11},{"front":"be encouraged to ask questions early","meaning":"被鼓勵及早提問","examples":[{"en":"Workers should be encouraged to ask questions early.","zh":"員工應被鼓勵及早提問。"},{"en":"Be encouraged to ask questions early means be supported in raising doubts before problems grow.","zh":"be encouraged to ask questions early 的意思是被支持在問題變大前提出疑問。"},{"en":"Employees should ask early if they do not understand a task.","zh":"如果員工不明白任務，應及早提問。"},{"en":"Early questions prevent mistakes and show responsibility.","zh":"早期提問可以防止錯誤，並顯示責任感。"},{"en":"This phrase describes a healthy communication culture.","zh":"這個短語描述健康的溝通文化。"}],"source":"2025 Q4.pdf","sourcePage":11},{"front":"conceal uncertainty","meaning":"隱藏不確定","examples":[{"en":"Workers should not conceal uncertainty out of embarrassment.","zh":"員工不應出於尷尬而隱藏不確定。"},{"en":"To conceal uncertainty means to hide the fact that one is unsure.","zh":"conceal uncertainty 的意思是隱瞞自己不確定的事實。"},{"en":"An employee may conceal uncertainty because he fears looking incompetent.","zh":"員工可能因害怕看起來無能而隱藏不確定。"},{"en":"Hidden uncertainty can lead to wrong work and preventable mistakes.","zh":"隱藏的不確定可以導致錯誤工作和可避免的錯誤。"},{"en":"This phrase shows why psychological safety matters.","zh":"這個短語顯示心理安全為何重要。"}],"source":"2025 Q4.pdf","sourcePage":11},{"front":"out of embarrassment","meaning":"出於尷尬","examples":[{"en":"Some workers conceal uncertainty out of embarrassment.","zh":"有些員工出於尷尬而隱藏不確定。"},{"en":"Out of embarrassment means because someone feels ashamed, awkward, or afraid of judgement.","zh":"out of embarrassment 的意思是因感到羞愧、不自在或害怕被評判。"},{"en":"An employee may stay silent out of embarrassment even when instructions are unclear.","zh":"即使指示不清，員工也可能出於尷尬而保持沉默。"},{"en":"Teams should make questions normal so people do not hide doubts.","zh":"團隊應令提問變得正常，這樣人們就不會隱藏疑問。"},{"en":"This phrase explains the emotional reason behind silence.","zh":"這個短語解釋沉默背後的情感原因。"}],"source":"2025 Q4.pdf","sourcePage":12},{"front":"communication becomes structured","meaning":"溝通變得有系統","examples":[{"en":"Group work improves once communication becomes structured.","zh":"一旦溝通變得有系統，小組工作就會改善。"},{"en":"Communication becomes structured means information is shared through clear routines and channels.","zh":"communication becomes structured 的意思是資訊透過清晰常規和渠道分享。"},{"en":"Communication becomes structured when teams use agendas, summaries, and update tools.","zh":"當團隊使用議程、摘要和更新工具時，溝通就變得有系統。"},{"en":"Structured communication reduces guessing and repeated explanation.","zh":"有系統的溝通減少猜測和重複解釋。"},{"en":"This phrase describes communication that is organised rather than random.","zh":"這個短語描述有組織而非隨機的溝通。"}],"source":"2025 Q4.pdf","sourcePage":12},{"front":"far more efficient","meaning":"效率高得多","examples":[{"en":"Group work becomes far more efficient with clear communication.","zh":"有清晰溝通時，小組工作效率高得多。"},{"en":"Far more efficient means much better at saving time, effort, and resources.","zh":"far more efficient 的意思是在節省時間、努力和資源方面好得多。"},{"en":"A team becomes far more efficient when everyone knows the same deadline.","zh":"當每個人都知道同一限期時，團隊效率會高得多。"},{"en":"Efficiency improves when tasks are clear and updates are easy to find.","zh":"當任務清晰且更新容易找到時，效率會改善。"},{"en":"This phrase describes a major practical improvement.","zh":"這個短語描述重大的實際改善。"}],"source":"2025 Q4.pdf","sourcePage":12},{"front":"no longer guessing","meaning":"不再猜測","examples":[{"en":"People are no longer guessing what others mean or need.","zh":"人們不再猜測別人的意思或需要。"},{"en":"No longer guessing means people do not have to make uncertain assumptions anymore.","zh":"no longer guessing 的意思是人們不再需要作不確定的假設。"},{"en":"Clear instructions mean workers are no longer guessing who should prepare the report.","zh":"清晰指示代表員工不再猜測誰應準備報告。"},{"en":"Teams waste less time when members stop guessing and start confirming.","zh":"當成員停止猜測並開始確認時，團隊會少浪費時間。"},{"en":"This phrase describes clarity replacing uncertainty.","zh":"這個短語描述清晰取代不確定。"}],"source":"2025 Q4.pdf","sourcePage":12},{"front":"a third and often underestimated challenge","meaning":"第三個經常被低估的挑戰","examples":[{"en":"A third and often underestimated challenge is interpersonal conflict.","zh":"第三個經常被低估的挑戰是人際衝突。"},{"en":"A third and often underestimated challenge means another problem that people often fail to take seriously enough.","zh":"a third and often underestimated challenge 的意思是另一個人們常未夠認真看待的問題。"},{"en":"Interpersonal conflict is often underestimated because it seems less concrete than deadlines.","zh":"人際衝突常被低估，因為它看起來不如限期具體。"},{"en":"This phrase signals a new point and warns that it deserves attention.","zh":"這個短語標示新觀點，並提醒它值得注意。"},{"en":"It helps structure an essay while adding emphasis.","zh":"它幫助文章組織結構，同時增加強調。"}],"source":"2025 Q4.pdf","sourcePage":12},{"front":"interpersonal conflict","meaning":"人際衝突","examples":[{"en":"Interpersonal conflict can damage teamwork.","zh":"人際衝突可以傷害團隊合作。"},{"en":"Interpersonal conflict is tension or disagreement between people in a relationship or team.","zh":"interpersonal conflict 是人際關係或團隊中人與人之間的緊張或分歧。"},{"en":"Interpersonal conflict may arise when one member dominates and another feels ignored.","zh":"當一名成員主導討論而另一人感到被忽略時，可能出現人際衝突。"},{"en":"Conflict between people can weaken trust even if the task itself is clear.","zh":"即使任務本身清晰，人與人之間的衝突仍可削弱信任。"},{"en":"This phrase describes the human side of teamwork problems.","zh":"這個短語描述團隊問題中人的一面。"}],"source":"2025 Q4.pdf","sourcePage":12},{"front":"bring together","meaning":"把……聚在一起","examples":[{"en":"Group work brings together people with different temperaments.","zh":"小組工作把不同性情的人聚在一起。"},{"en":"To bring together means to gather people or things into one place or group.","zh":"bring together 的意思是把人或事物集合到同一地方或群體。"},{"en":"A project may bring together designers, accountants, and customer-service staff.","zh":"一個項目可以把設計師、會計師和客戶服務人員聚在一起。"},{"en":"Bringing people together creates opportunity but also possible conflict.","zh":"把人聚在一起會創造機會，也可能產生衝突。"},{"en":"This phrase describes the basic action behind teamwork.","zh":"這個短語描述團隊合作背後的基本行動。"}],"source":"2025 Q4.pdf","sourcePage":12},{"front":"different temperaments","meaning":"不同性情","examples":[{"en":"Team members may have different temperaments, habits, and values.","zh":"團隊成員可能有不同性情、習慣和價值觀。"},{"en":"Different temperaments are different natural ways of reacting, working, or communicating.","zh":"different temperaments 是不同的自然反應、工作或溝通方式。"},{"en":"Some workers are calm and slow, while others are direct and fast-paced.","zh":"有些員工冷靜而慢熱，另一些直接而節奏快。"},{"en":"Different temperaments can strengthen a team if they are managed well.","zh":"如果管理得好，不同性情可以加強團隊。"},{"en":"This phrase describes personality differences in the workplace.","zh":"這個短語描述職場中的性格差異。"}],"source":"2025 Q4.pdf","sourcePage":12},{"front":"habits and values","meaning":"習慣和價值觀","examples":[{"en":"Group work brings together people with different habits and values.","zh":"小組工作把有不同習慣和價值觀的人聚在一起。"},{"en":"Habits and values are regular behaviours and beliefs about what matters.","zh":"habits and values 是日常行為和對何事重要的信念。"},{"en":"One worker may value speed, while another values careful checking.","zh":"一名員工可能重視速度，而另一人重視仔細檢查。"},{"en":"Different habits and values can cause tension if they are not discussed.","zh":"如果不同習慣和價值觀沒有被討論，就可能造成緊張。"},{"en":"This phrase explains why cooperation needs understanding.","zh":"這個短語解釋為何合作需要理解。"}],"source":"2025 Q4.pdf","sourcePage":12},{"front":"direct and fast-paced","meaning":"直接而節奏快","examples":[{"en":"Some employees are direct and fast-paced.","zh":"有些員工直接而節奏快。"},{"en":"Direct and fast-paced means straightforward in communication and quick in action.","zh":"direct and fast-paced 的意思是溝通直接，行動快速。"},{"en":"A direct and fast-paced manager may make decisions quickly during meetings.","zh":"直接而節奏快的管理者可能在會議中迅速作決定。"},{"en":"This style can be efficient, but it may overwhelm cautious colleagues.","zh":"這種風格可以有效率，但可能令謹慎同事感到壓力。"},{"en":"This phrase describes one workplace personality style.","zh":"這個短語描述一種職場性格風格。"}],"source":"2025 Q4.pdf","sourcePage":12},{"front":"cautious and reflective","meaning":"謹慎而善於反思","examples":[{"en":"Others are cautious and reflective.","zh":"另一些人謹慎而善於反思。"},{"en":"Cautious and reflective means careful and thoughtful before acting or speaking.","zh":"cautious and reflective 的意思是在行動或說話前小心並深思熟慮。"},{"en":"A cautious and reflective employee may ask for more evidence before approving a plan.","zh":"謹慎而善於反思的員工可能在批准計劃前要求更多證據。"},{"en":"This style can prevent mistakes, but it may seem slow to fast-paced teammates.","zh":"這種風格可以防止錯誤，但對節奏快的隊友來說可能顯得緩慢。"},{"en":"This phrase describes a careful workplace personality style.","zh":"這個短語描述一種細心的職場性格風格。"}],"source":"2025 Q4.pdf","sourcePage":13},{"front":"dominate discussion","meaning":"主導討論","examples":[{"en":"Some employees prefer to dominate discussion.","zh":"有些員工偏好主導討論。"},{"en":"To dominate discussion means to control most of the conversation.","zh":"dominate discussion 的意思是控制大部分對話。"},{"en":"A confident worker may dominate discussion by speaking before others can respond.","zh":"有信心的員工可能在別人能回應前發言，從而主導討論。"},{"en":"When one person dominates discussion, quieter members may hesitate to speak.","zh":"當一個人主導討論，較沉默的成員可能猶豫是否發言。"},{"en":"This phrase describes an imbalance in communication.","zh":"這個短語描述溝通中的不平衡。"}],"source":"2025 Q4.pdf","sourcePage":13},{"front":"quieter members","meaning":"較沉默的成員","examples":[{"en":"Quieter members may hesitate to speak.","zh":"較沉默的成員可能猶豫是否發言。"},{"en":"Quieter members are people who speak less often or less loudly in a group.","zh":"quieter members 是在小組中較少或較小聲發言的人。"},{"en":"Quieter members may have valuable ideas but need time or invitation to share them.","zh":"較沉默的成員可能有有價值的想法，但需要時間或邀請來分享。"},{"en":"Good leaders make space for quieter members during meetings.","zh":"好領袖會在會議中為較沉默的成員留出空間。"},{"en":"This phrase reminds teams not to confuse silence with lack of ideas.","zh":"這個短語提醒團隊不要把沉默誤解為沒有想法。"}],"source":"2025 Q4.pdf","sourcePage":13},{"front":"hesitate to speak","meaning":"猶豫是否發言","examples":[{"en":"Quieter members may hesitate to speak even when they have ideas.","zh":"較沉默的成員即使有想法，也可能猶豫是否發言。"},{"en":"To hesitate to speak means to pause or hold back before expressing an opinion.","zh":"hesitate to speak 的意思是在表達意見前停頓或退縮。"},{"en":"An employee may hesitate to speak if the discussion feels aggressive.","zh":"如果討論感覺具攻擊性，員工可能猶豫是否發言。"},{"en":"Teams lose useful ideas when people hesitate for fear of judgement.","zh":"當人們因害怕被評判而猶豫，團隊會失去有用想法。"},{"en":"This phrase describes uncertainty before communication.","zh":"這個短語描述溝通前的不確定。"}],"source":"2025 Q4.pdf","sourcePage":13},{"front":"valuable ideas","meaning":"有價值的想法","examples":[{"en":"Quieter members may have valuable ideas.","zh":"較沉默的成員可能有有價值的想法。"},{"en":"Valuable ideas are useful, thoughtful, or important suggestions.","zh":"valuable ideas 是有用、有思想或重要的建議。"},{"en":"A quiet analyst may have valuable ideas about risks in a project.","zh":"安靜的分析員可能對項目風險有有價值的想法。"},{"en":"Teams should create space for valuable ideas from every member.","zh":"團隊應為每位成員的有價值想法創造空間。"},{"en":"This phrase shows that contribution is not always loud.","zh":"這個短語顯示貢獻不一定大聲。"}],"source":"2025 Q4.pdf","sourcePage":13},{"front":"under pressure","meaning":"在壓力下","examples":[{"en":"Under pressure, personality differences can escalate into tension.","zh":"在壓力下，性格差異可能升級成緊張關係。"},{"en":"Under pressure means during stressful or demanding conditions.","zh":"under pressure 的意思是在有壓力或要求高的情況下。"},{"en":"Under pressure, direct workers may become impatient with cautious colleagues.","zh":"在壓力下，直接的員工可能對謹慎同事失去耐性。"},{"en":"Pressure can make small differences feel like serious conflicts.","zh":"壓力可以令小差異感覺像嚴重衝突。"},{"en":"This phrase explains why teamwork becomes harder during deadlines.","zh":"這個短語解釋為何團隊合作在限期下變得更困難。"}],"source":"2025 Q4.pdf","sourcePage":13},{"front":"escalate into tension","meaning":"升級成緊張關係","examples":[{"en":"These differences can easily escalate into tension.","zh":"這些差異很容易升級成緊張關係。"},{"en":"To escalate into tension means to grow into a more serious and stressful conflict.","zh":"escalate into tension 的意思是發展成更嚴重和有壓力的衝突。"},{"en":"A disagreement about timing may escalate into tension if people feel disrespected.","zh":"如果人們感到不被尊重，關於時間安排的分歧可能升級成緊張關係。"},{"en":"Leaders should act early before small problems escalate.","zh":"領袖應及早行動，防止小問題升級。"},{"en":"This phrase describes conflict becoming more serious.","zh":"這個短語描述衝突變得更嚴重。"}],"source":"2025 Q4.pdf","sourcePage":13},{"front":"generate solutions","meaning":"產生解決方案","examples":[{"en":"A team meeting should generate solutions.","zh":"團隊會議應產生解決方案。"},{"en":"To generate solutions means to produce useful answers to problems.","zh":"generate solutions 的意思是產生有用的問題答案。"},{"en":"A good meeting generates solutions by focusing on evidence and next steps.","zh":"好會議透過聚焦證據和下一步來產生解決方案。"},{"en":"Meetings fail when they generate arguments instead of solutions.","zh":"當會議產生爭論而不是解決方案時，就失敗了。"},{"en":"This phrase describes the productive goal of discussion.","zh":"這個短語描述討論的生產性目標。"}],"source":"2025 Q4.pdf","sourcePage":13},{"front":"turn into a contest of egos","meaning":"變成自我較量","examples":[{"en":"A meeting may turn into a contest of egos.","zh":"會議可能變成自我較量。"},{"en":"To turn into a contest of egos means to become a fight about pride rather than results.","zh":"turn into a contest of egos 的意思是變成關於自尊而非成果的爭鬥。"},{"en":"A team meeting turns into a contest of egos when members care more about winning than solving the problem.","zh":"當成員更關心勝過別人，而不是解決問題時，團隊會議就變成自我較量。"},{"en":"Ego contests damage trust and waste time.","zh":"自我較量會破壞信任並浪費時間。"},{"en":"This phrase criticises unproductive workplace conflict.","zh":"這個短語批評沒有生產力的職場衝突。"}],"source":"2025 Q4.pdf","sourcePage":13},{"front":"defend pride","meaning":"維護自尊","examples":[{"en":"People may defend pride rather than pursue results.","zh":"人們可能維護自尊，而不是追求成果。"},{"en":"To defend pride means to protect one’s ego or image instead of focusing on the task.","zh":"defend pride 的意思是保護自己的自我或形象，而不是專注任務。"},{"en":"A manager defends pride when he refuses to admit a mistake.","zh":"當管理者拒絕承認錯誤時，就是維護自尊。"},{"en":"Defending pride can stop a team from learning and improving.","zh":"維護自尊可以阻止團隊學習和改善。"},{"en":"This phrase describes ego-driven behaviour.","zh":"這個短語描述由自我驅動的行為。"}],"source":"2025 Q4.pdf","sourcePage":13},{"front":"pursue results","meaning":"追求成果","examples":[{"en":"Teams should pursue results instead of defending pride.","zh":"團隊應追求成果，而不是維護自尊。"},{"en":"To pursue results means to work toward practical outcomes and success.","zh":"pursue results 的意思是朝實際成果和成功努力。"},{"en":"A team pursues results when it focuses on solutions rather than blame.","zh":"當團隊專注解決方案而不是責怪時，就是追求成果。"},{"en":"Pursuing results requires members to accept feedback and adjust their views.","zh":"追求成果要求成員接受回饋並調整看法。"},{"en":"This phrase describes goal-focused teamwork.","zh":"這個短語描述以目標為本的團隊合作。"}],"source":"2025 Q4.pdf","sourcePage":14},{"front":"emotionally draining","meaning":"令人情緒疲憊","examples":[{"en":"Interpersonal conflict can be emotionally draining.","zh":"人際衝突可以令人情緒疲憊。"},{"en":"Emotionally draining means tiring in a mental and emotional way.","zh":"emotionally draining 的意思是在精神和情感上令人疲累。"},{"en":"Constant arguments with teammates can be emotionally draining for employees.","zh":"與隊友持續爭吵可以令員工情緒疲憊。"},{"en":"Work feels heavier when conflict uses up emotional energy.","zh":"當衝突耗盡情感能量，工作會感覺更沉重。"},{"en":"This phrase describes the personal cost of tension.","zh":"這個短語描述緊張關係的個人代價。"}],"source":"2025 Q4.pdf","sourcePage":14},{"front":"professionally damaging","meaning":"對工作有害","examples":[{"en":"Conflict can be professionally damaging.","zh":"衝突可以對工作有害。"},{"en":"Professionally damaging means harmful to someone’s work, reputation, career, or performance.","zh":"professionally damaging 的意思是對某人的工作、聲譽、事業或表現有害。"},{"en":"A public argument in a meeting can be professionally damaging for everyone involved.","zh":"會議中的公開爭吵可以對所有相關人士的工作有害。"},{"en":"Conflict damages work when it reduces trust and cooperation.","zh":"當衝突削弱信任和合作時，就會傷害工作。"},{"en":"This phrase describes career-related harm.","zh":"這個短語描述與職業相關的傷害。"}],"source":"2025 Q4.pdf","sourcePage":14},{"front":"weaken trust","meaning":"削弱信任","examples":[{"en":"Conflict weakens trust.","zh":"衝突削弱信任。"},{"en":"To weaken trust means to reduce people’s confidence in one another.","zh":"weaken trust 的意思是降低人們對彼此的信心。"},{"en":"Broken promises and personal attacks can weaken trust in a team.","zh":"破壞承諾和人身攻擊可以削弱團隊中的信任。"},{"en":"Once trust weakens, members may share less information and take fewer risks.","zh":"一旦信任被削弱，成員可能分享更少資訊，也較少冒險。"},{"en":"This phrase describes damage to the foundation of teamwork.","zh":"這個短語描述對團隊合作基礎的傷害。"}],"source":"2025 Q4.pdf","sourcePage":14},{"front":"the foundation of","meaning":"……的基礎","examples":[{"en":"Trust is the foundation of all effective teamwork.","zh":"信任是所有有效團隊合作的基礎。"},{"en":"The foundation of something is the basic support on which it depends.","zh":"foundation of something 是某事所依賴的基本支撐。"},{"en":"Clear communication is the foundation of successful collaboration.","zh":"清晰溝通是成功合作的基礎。"},{"en":"If the foundation is weak, even talented teams may struggle.","zh":"如果基礎薄弱，即使有才能的團隊也可能掙扎。"},{"en":"This phrase identifies the basic condition needed for success.","zh":"這個短語指出成功所需的基本條件。"}],"source":"2025 Q4.pdf","sourcePage":14},{"front":"effective teamwork","meaning":"有效團隊合作","examples":[{"en":"Trust is the foundation of effective teamwork.","zh":"信任是有效團隊合作的基礎。"},{"en":"Effective teamwork is cooperation that produces strong results fairly and efficiently.","zh":"effective teamwork 是公平而有效率地產生佳績的合作。"},{"en":"Effective teamwork requires clear roles, respectful communication, and shared responsibility.","zh":"有效團隊合作需要清晰角色、尊重溝通和共同責任。"},{"en":"A team shows effective teamwork when different personalities work toward one goal.","zh":"當不同性格的人朝同一目標合作時，團隊就展現有效團隊合作。"},{"en":"This phrase describes teamwork that actually works.","zh":"這個短語描述真正發揮作用的團隊合作。"}],"source":"2025 Q4.pdf","sourcePage":14},{"front":"nevertheless","meaning":"儘管如此","examples":[{"en":"Nevertheless, personality clashes need not destroy cooperation.","zh":"儘管如此，性格衝突不一定會破壞合作。"},{"en":"Nevertheless means despite what has just been said.","zh":"nevertheless 的意思是儘管剛才所說的情況存在。"},{"en":"Conflict can be tiring; nevertheless, it can be managed with strong leadership.","zh":"衝突可以令人疲憊；儘管如此，它可以透過強而有力的領導來管理。"},{"en":"This word introduces a hopeful contrast after describing a problem.","zh":"這個詞在描述問題後引入有希望的對比。"},{"en":"It is useful when showing that difficulties are not final.","zh":"當顯示困難不是最終結局時，它很有用。"}],"source":"2025 Q4.pdf","sourcePage":14},{"front":"personality clashes","meaning":"性格衝突","examples":[{"en":"Personality clashes need not destroy cooperation.","zh":"性格衝突不一定會破壞合作。"},{"en":"Personality clashes are conflicts caused by differences in character or working style.","zh":"personality clashes 是由性格或工作風格差異造成的衝突。"},{"en":"A cautious employee and a fast-paced employee may experience personality clashes.","zh":"謹慎員工和節奏快的員工可能經歷性格衝突。"},{"en":"Personality clashes can become useful if differences are discussed respectfully.","zh":"如果差異被尊重地討論，性格衝突可以變得有用。"},{"en":"This phrase describes a common but manageable teamwork challenge.","zh":"這個短語描述常見但可管理的團隊挑戰。"}],"source":"2025 Q4.pdf","sourcePage":14},{"front":"need not destroy cooperation","meaning":"不一定會破壞合作","examples":[{"en":"Personality clashes need not destroy cooperation.","zh":"性格衝突不一定會破壞合作。"},{"en":"Need not destroy cooperation means do not have to ruin people’s ability to work together.","zh":"need not destroy cooperation 的意思是不必然破壞人們一起工作的能力。"},{"en":"Differences need not destroy cooperation if a leader keeps discussion respectful.","zh":"如果領袖保持討論尊重，差異不一定會破壞合作。"},{"en":"Teams can disagree strongly and still cooperate well.","zh":"團隊可以有強烈分歧，仍然良好合作。"},{"en":"This phrase gives a hopeful view of conflict.","zh":"這個短語給衝突一個有希望的看法。"}],"source":"2025 Q4.pdf","sourcePage":14},{"front":"strong leadership","meaning":"強而有力的領導","examples":[{"en":"Strong leadership is crucial in managing conflict.","zh":"強而有力的領導在管理衝突方面很關鍵。"},{"en":"Strong leadership means confident, fair, and responsible guidance.","zh":"strong leadership 是有信心、公平和負責任的引導。"},{"en":"Strong leadership helps teams stay focused when personalities clash.","zh":"當性格衝突時，強而有力的領導幫助團隊保持專注。"},{"en":"A strong leader invites quiet members and limits personal attacks.","zh":"強而有力的領袖會邀請沉默成員發言，並限制人身攻擊。"},{"en":"This phrase describes leadership that protects cooperation.","zh":"這個短語描述保護合作的領導。"}],"source":"2025 Q4.pdf","sourcePage":14},{"front":"crucial","meaning":"關鍵的","examples":[{"en":"Strong leadership is crucial here.","zh":"強而有力的領導在這裏是關鍵的。"},{"en":"Crucial means extremely important and necessary for success.","zh":"crucial 的意思是極其重要並對成功必要。"},{"en":"Clear communication is crucial when several departments share one project.","zh":"當幾個部門共同處理一個項目時，清晰溝通是關鍵的。"},{"en":"A crucial decision can affect the whole team’s progress.","zh":"關鍵決定可以影響整個團隊的進度。"},{"en":"This word marks something as central, not optional.","zh":"這個詞把某事標示為核心，而不是可有可無。"}],"source":"2025 Q4.pdf","sourcePage":15},{"front":"competent team leader","meaning":"稱職的團隊領袖","examples":[{"en":"A competent team leader should keep discussion respectful.","zh":"稱職的團隊領袖應讓討論保持尊重。"},{"en":"A competent team leader is a capable person who guides a group effectively.","zh":"competent team leader 是能有效引導小組的有能力人士。"},{"en":"A competent leader sets roles, manages tension, and keeps meetings focused.","zh":"稱職的領袖會設定角色、管理緊張，並讓會議保持焦點。"},{"en":"Teams need competent leaders when members have different personalities.","zh":"當成員有不同性格時，團隊需要稱職的領袖。"},{"en":"This phrase describes the person responsible for guiding teamwork.","zh":"這個短語描述負責引導團隊合作的人。"}],"source":"2025 Q4.pdf","sourcePage":15},{"front":"ensure that","meaning":"確保","examples":[{"en":"A team leader should ensure that discussion remains respectful.","zh":"團隊領袖應確保討論保持尊重。"},{"en":"Ensure that means make certain that something happens or continues.","zh":"ensure that 的意思是確保某事發生或持續。"},{"en":"Managers should ensure that everyone understands the deadline.","zh":"管理者應確保每個人都明白限期。"},{"en":"This phrase is useful when describing responsibility and control.","zh":"這個短語在描述責任和控制時很有用。"},{"en":"It shows that leaders must actively protect good teamwork.","zh":"它顯示領袖必須主動保護良好團隊合作。"}],"source":"2025 Q4.pdf","sourcePage":15},{"front":"discussion remains respectful","meaning":"討論保持尊重","examples":[{"en":"The leader should ensure that discussion remains respectful.","zh":"領袖應確保討論保持尊重。"},{"en":"Discussion remains respectful means people can disagree without insulting one another.","zh":"discussion remains respectful 的意思是人們可以不同意，而不侮辱彼此。"},{"en":"A meeting remains respectful when members challenge ideas rather than personalities.","zh":"當成員挑戰想法而不是性格時，會議就保持尊重。"},{"en":"Respectful discussion helps teams use disagreement productively.","zh":"尊重的討論幫助團隊把分歧用得有成效。"},{"en":"This phrase describes a healthy communication standard.","zh":"這個短語描述健康的溝通標準。"}],"source":"2025 Q4.pdf","sourcePage":15},{"front":"invited to contribute","meaning":"被邀請作出貢獻","examples":[{"en":"Quieter members should be invited to contribute.","zh":"較沉默的成員應被邀請作出貢獻。"},{"en":"Invited to contribute means asked or encouraged to share ideas, work, or opinions.","zh":"invited to contribute 的意思是被詢問或鼓勵分享想法、工作或意見。"},{"en":"A leader may invite quieter members to contribute by asking for their view directly.","zh":"領袖可以直接詢問較沉默成員的看法，邀請他們作出貢獻。"},{"en":"This invitation can reveal ideas that would otherwise remain hidden.","zh":"這種邀請可以揭示原本會被隱藏的想法。"},{"en":"This phrase shows active inclusion in teamwork.","zh":"這個短語展示團隊合作中的主動共融。"}],"source":"2025 Q4.pdf","sourcePage":15},{"front":"disagreement is directed towards ideas","meaning":"分歧應針對想法","examples":[{"en":"Disagreement should be directed towards ideas rather than individuals.","zh":"分歧應針對想法，而不是個人。"},{"en":"Disagreement is directed towards ideas means criticism focuses on arguments, plans, or evidence.","zh":"disagreement is directed towards ideas 的意思是批評集中於論點、計劃或證據。"},{"en":"A team can question a proposal without attacking the person who made it.","zh":"團隊可以質疑建議，而不攻擊提出建議的人。"},{"en":"Directing disagreement toward ideas keeps conflict professional.","zh":"把分歧指向想法，可以令衝突保持專業。"},{"en":"This phrase describes fair and mature debate.","zh":"這個短語描述公平而成熟的討論。"}],"source":"2025 Q4.pdf","sourcePage":15},{"front":"rather than individuals","meaning":"而不是個人","examples":[{"en":"Disagreement should target ideas rather than individuals.","zh":"分歧應針對想法，而不是個人。"},{"en":"Rather than individuals means instead of attacking particular people personally.","zh":"rather than individuals 的意思是不要人身攻擊特定人士。"},{"en":"A manager should criticise the plan rather than the employee’s character.","zh":"管理者應批評計劃，而不是批評員工性格。"},{"en":"This phrase helps keep workplace conflict respectful.","zh":"這個短語幫助職場衝突保持尊重。"},{"en":"It is useful when explaining how to disagree professionally.","zh":"當解釋如何專業地表達不同意見時，它很有用。"}],"source":"2025 Q4.pdf","sourcePage":15},{"front":"conflict resolution","meaning":"衝突處理","examples":[{"en":"Workplaces should provide training in conflict resolution.","zh":"職場應提供衝突處理培訓。"},{"en":"Conflict resolution means methods for settling disagreements fairly and calmly.","zh":"conflict resolution 是公平而冷靜地解決分歧的方法。"},{"en":"Conflict-resolution training may teach listening, mediation, and problem-solving.","zh":"衝突處理培訓可以教授聆聽、調解和解難。"},{"en":"Teams with conflict-resolution skills can recover from tension more quickly.","zh":"具備衝突處理技巧的團隊可以更快從緊張中恢復。"},{"en":"This phrase describes a practical way to manage workplace disagreement.","zh":"這個短語描述管理職場分歧的實際方法。"}],"source":"2025 Q4.pdf","sourcePage":15},{"front":"emotional intelligence","meaning":"情緒智商","examples":[{"en":"Emotional intelligence is important for productive collaboration.","zh":"情緒智商對有成效的合作很重要。"},{"en":"Emotional intelligence is the ability to understand and manage one’s own feelings and respond well to others’ feelings.","zh":"emotional intelligence 是理解和管理自己情緒，以及良好回應他人情緒的能力。"},{"en":"A team leader uses emotional intelligence when calming a tense meeting.","zh":"團隊領袖在安撫緊張會議時，就是運用情緒智商。"},{"en":"Emotional intelligence helps employees disagree without damaging relationships.","zh":"情緒智商幫助員工表達不同意見而不傷害關係。"},{"en":"This phrase describes a people skill needed for teamwork.","zh":"這個短語描述團隊合作所需的人際技巧。"}],"source":"2025 Q4.pdf","sourcePage":15},{"front":"technical skills alone","meaning":"單靠技術能力","examples":[{"en":"Technical skills alone do not guarantee productive collaboration.","zh":"單靠技術能力不能保證有成效的合作。"},{"en":"Technical skills alone means job-specific abilities without communication, empathy, or teamwork skills.","zh":"technical skills alone 的意思是只有工作專門能力，而沒有溝通、同理心或團隊技巧。"},{"en":"A team of experts may fail if technical skills alone are valued.","zh":"如果只重視技術能力，專家團隊也可能失敗。"},{"en":"Collaboration also needs listening, respect, and conflict management.","zh":"合作也需要聆聽、尊重和衝突管理。"},{"en":"This phrase warns against relying only on professional ability.","zh":"這個短語提醒人們不要只依賴專業能力。"}],"source":"2025 Q4.pdf","sourcePage":15},{"front":"guarantee productive collaboration","meaning":"保證有成效的合作","examples":[{"en":"Technical skills alone do not guarantee productive collaboration.","zh":"單靠技術能力不能保證有成效的合作。"},{"en":"To guarantee productive collaboration means to make successful teamwork certain.","zh":"guarantee productive collaboration 的意思是確保成功團隊合作必然發生。"},{"en":"Expertise cannot guarantee productive collaboration if members refuse to communicate.","zh":"如果成員拒絕溝通，專業知識不能保證有成效的合作。"},{"en":"Productive collaboration requires both skill and trust.","zh":"有成效的合作需要技能，也需要信任。"},{"en":"This phrase describes the limit of technical ability.","zh":"這個短語描述技術能力的限制。"}],"source":"2025 Q4.pdf","sourcePage":16},{"front":"productive collaboration","meaning":"有成效的合作","examples":[{"en":"Teams need more than technical skills for productive collaboration.","zh":"團隊需要多於技術能力，才能有成效地合作。"},{"en":"Productive collaboration is teamwork that creates useful results efficiently and fairly.","zh":"productive collaboration 是有效率而公平地創造有用成果的團隊合作。"},{"en":"Productive collaboration happens when members combine expertise and communicate clearly.","zh":"當成員結合專業知識並清晰溝通時，就會出現有成效的合作。"},{"en":"A team can be busy without being productive if work is duplicated or confused.","zh":"如果工作重複或混亂，團隊可以很忙卻沒有成效。"},{"en":"This phrase describes cooperation that produces real value.","zh":"這個短語描述產生真正價值的合作。"}],"source":"2025 Q4.pdf","sourcePage":16},{"front":"managed maturely","meaning":"成熟地管理","examples":[{"en":"Differences can become useful when they are managed maturely.","zh":"當差異被成熟地管理時，它們可以變得有用。"},{"en":"Managed maturely means handled calmly, respectfully, and responsibly.","zh":"managed maturely 的意思是冷靜、尊重而負責任地處理。"},{"en":"Personality differences are managed maturely when a leader keeps discussion focused on ideas.","zh":"當領袖讓討論集中於想法時，性格差異就是被成熟地管理。"},{"en":"Mature management turns tension into learning rather than division.","zh":"成熟管理把緊張轉化為學習，而不是分裂。"},{"en":"This phrase describes wise handling of conflict.","zh":"這個短語描述明智地處理衝突。"}],"source":"2025 Q4.pdf","sourcePage":16},{"front":"diversity becomes an advantage","meaning":"多元性成為優勢","examples":[{"en":"When differences are managed well, diversity becomes an advantage.","zh":"當差異被良好管理，多元性就會成為優勢。"},{"en":"Diversity becomes an advantage means different backgrounds, skills, or personalities help the team succeed.","zh":"diversity becomes an advantage 的意思是不同背景、技能或性格幫助團隊成功。"},{"en":"A diverse team gains advantage when different views improve decision-making.","zh":"當不同觀點改善決策時，多元團隊就獲得優勢。"},{"en":"Diversity can hurt teamwork if unmanaged, but help it when guided well.","zh":"如果缺乏管理，多元性可以傷害團隊合作；但引導得好則能幫助它。"},{"en":"This phrase shows the positive potential of difference.","zh":"這個短語展示差異的正面潛力。"}],"source":"2025 Q4.pdf","sourcePage":16},{"front":"a source of division","meaning":"分裂的來源","examples":[{"en":"Diversity should be an advantage rather than a source of division.","zh":"多元性應是優勢，而不是分裂的來源。"},{"en":"A source of division is something that causes people to separate, argue, or distrust one another.","zh":"source of division 是造成分離、爭吵或彼此不信任的東西。"},{"en":"Different working styles become a source of division when people judge one another unfairly.","zh":"當人們不公平地評判彼此時，不同工作風格會成為分裂的來源。"},{"en":"Leadership can stop diversity from becoming division.","zh":"領導可以阻止多元性變成分裂。"},{"en":"This phrase describes a harmful result that good management should prevent.","zh":"這個短語描述良好管理應防止的有害結果。"}],"source":"2025 Q4.pdf","sourcePage":16},{"front":"in conclusion","meaning":"總結而言","examples":[{"en":"In conclusion, group work may be unpopular for several reasons.","zh":"總結而言，小組工作可能因幾個原因而不受歡迎。"},{"en":"In conclusion means finally, before giving the final judgement or summary.","zh":"in conclusion 的意思是最後，在提出最終判斷或總結前。"},{"en":"In conclusion, teamwork needs structure, communication, and leadership.","zh":"總結而言，團隊合作需要架構、溝通和領導。"},{"en":"Writers use this phrase to signal the ending of an essay.","zh":"作者使用這個短語來標示文章結尾。"},{"en":"It helps gather the main points into a final answer.","zh":"它幫助把主要觀點整理成最終答案。"}],"source":"2025 Q4.pdf","sourcePage":16},{"front":"unpopular among workers","meaning":"不受員工歡迎","examples":[{"en":"Group work may be unpopular among workers.","zh":"小組工作可能不受員工歡迎。"},{"en":"Unpopular among workers means disliked or not welcomed by employees.","zh":"unpopular among workers 的意思是被員工不喜歡或不歡迎。"},{"en":"Group work becomes unpopular when workers expect unfair effort and conflict.","zh":"當員工預期付出不公平和衝突時，小組工作會不受歡迎。"},{"en":"A task can be necessary yet still unpopular if past experiences were poor.","zh":"如果過去經驗差，一項任務即使必要也可能不受歡迎。"},{"en":"This phrase describes employees’ negative attitude toward teamwork.","zh":"這個短語描述員工對團隊合作的負面態度。"}],"source":"2025 Q4.pdf","sourcePage":16},{"front":"suffer from","meaning":"受到……困擾","examples":[{"en":"Group work often suffers from free-riding and miscommunication.","zh":"小組工作常受到搭便車和溝通失誤困擾。"},{"en":"To suffer from something means to be harmed or affected by a problem.","zh":"suffer from something 的意思是被某問題傷害或影響。"},{"en":"A team may suffer from poor communication if updates are scattered across many channels.","zh":"如果更新分散在許多渠道，團隊可能受到溝通不善困擾。"},{"en":"Group work suffers when problems continue without being managed.","zh":"當問題持續而無人管理時，小組工作就會受困擾。"},{"en":"This phrase introduces difficulties affecting something.","zh":"這個短語引入影響某事的困難。"}],"source":"2025 Q4.pdf","sourcePage":16},{"front":"free-riding","meaning":"搭便車；坐享其成","examples":[{"en":"Free-riding makes group work feel unfair.","zh":"搭便車令小組工作感覺不公平。"},{"en":"Free-riding means benefiting from a group’s work while contributing little or nothing.","zh":"free-riding 的意思是從小組工作中得益，卻貢獻很少或完全沒有貢獻。"},{"en":"A free-rider may receive credit although others completed the main tasks.","zh":"搭便車者可能在其他人完成主要任務後仍獲得功勞。"},{"en":"Free-riding damages trust because hardworking members feel exploited.","zh":"搭便車會破壞信任，因為勤奮成員覺得被剝削。"},{"en":"This word describes one of the clearest fairness problems in teamwork.","zh":"這個詞描述團隊合作中最明顯的公平問題之一。"}],"source":"2025 Q4.pdf","sourcePage":16},{"front":"miscommunication","meaning":"溝通失誤","examples":[{"en":"Miscommunication can damage teamwork.","zh":"溝通失誤可以傷害團隊合作。"},{"en":"Miscommunication means information is misunderstood, unclear, or sent wrongly.","zh":"miscommunication 的意思是資訊被誤解、不清晰或傳送錯誤。"},{"en":"Miscommunication may cause two employees to prepare the same slides.","zh":"溝通失誤可能導致兩名員工準備同樣簡報。"},{"en":"A small miscommunication can delay a large project.","zh":"小小溝通失誤可以延誤大型項目。"},{"en":"This word describes communication failure that creates mistakes.","zh":"這個詞描述會造成錯誤的溝通失敗。"}],"source":"2025 Q4.pdf","sourcePage":16},{"front":"interpersonal tension","meaning":"人際緊張","examples":[{"en":"Interpersonal tension can make group work unpleasant.","zh":"人際緊張可以令小組工作令人不愉快。"},{"en":"Interpersonal tension is stress or unease between people.","zh":"interpersonal tension 是人與人之間的壓力或不安。"},{"en":"Tension may grow when one member dominates discussion and others feel ignored.","zh":"當一名成員主導討論，而其他人感到被忽略時，緊張可能增長。"},{"en":"Interpersonal tension can reduce honesty because people avoid speaking openly.","zh":"人際緊張可以減少坦誠，因為人們避免公開發言。"},{"en":"This phrase describes emotional strain inside a team.","zh":"這個短語描述團隊內部的情感壓力。"}],"source":"2025 Q4.pdf","sourcePage":17},{"front":"flawed by nature","meaning":"本質上有缺陷","examples":[{"en":"These problems do not prove that teamwork is flawed by nature.","zh":"這些問題並不證明團隊合作本質上有缺陷。"},{"en":"Flawed by nature means having defects as an unavoidable part of what something is.","zh":"flawed by nature 的意思是某事本身不可避免地帶有缺點。"},{"en":"Teamwork is not flawed by nature simply because some teams are badly managed.","zh":"團隊合作不會只因有些團隊管理不善，就本質上有缺陷。"},{"en":"Problems in teamwork often come from weak systems, not cooperation itself.","zh":"團隊合作中的問題常來自薄弱制度，而不是合作本身。"},{"en":"This phrase rejects an extreme judgement.","zh":"這個短語否定極端判斷。"}],"source":"2025 Q4.pdf","sourcePage":17},{"front":"fulfil its promise","meaning":"發揮其應有潛力","examples":[{"en":"Teamwork must be managed carefully if it is to fulfil its promise.","zh":"如果團隊合作要發揮其應有潛力，就必須被小心管理。"},{"en":"To fulfil its promise means to achieve the good results it is capable of producing.","zh":"fulfil its promise 的意思是達成它有能力產生的良好成果。"},{"en":"Teamwork fulfils its promise when it combines expertise and creates better decisions.","zh":"當團隊合作結合專業知識並創造更佳決策時，就是發揮其應有潛力。"},{"en":"Without structure, teamwork may fail to fulfil its promise.","zh":"沒有架構，團隊合作可能未能發揮其應有潛力。"},{"en":"This phrase describes reaching potential.","zh":"這個短語描述達到潛能。"}],"source":"2025 Q4.pdf","sourcePage":17},{"front":"contribution is transparent","meaning":"貢獻透明","examples":[{"en":"Group work is effective when contribution is transparent.","zh":"當貢獻透明時，小組工作就是有效的。"},{"en":"Contribution is transparent means everyone can see who has done what work.","zh":"contribution is transparent 的意思是每個人都能看見誰完成了甚麼工作。"},{"en":"Transparent contribution reduces suspicion and hidden free-riding.","zh":"透明貢獻可以減少猜疑和隱藏搭便車。"},{"en":"A shared task board can make contribution transparent during a project.","zh":"共享任務板可以令項目期間的貢獻透明。"},{"en":"This phrase describes fairness through visibility.","zh":"這個短語描述透過可見度建立公平。"}],"source":"2025 Q4.pdf","sourcePage":17},{"front":"communication is disciplined","meaning":"溝通有紀律","examples":[{"en":"Group work works best when communication is disciplined.","zh":"當溝通有紀律時，小組工作最有效。"},{"en":"Communication is disciplined means information is shared clearly, regularly, and through agreed methods.","zh":"communication is disciplined 的意思是資訊透過約定方法清晰、定期地分享。"},{"en":"Disciplined communication avoids random messages and unclear instructions.","zh":"有紀律的溝通避免隨機訊息和不清晰指示。"},{"en":"A team communicates with discipline when updates are brief, written, and timely.","zh":"當團隊更新簡短、書面化並準時，就是有紀律地溝通。"},{"en":"This phrase describes organised and responsible communication.","zh":"這個短語描述有組織而負責任的溝通。"}],"source":"2025 Q4.pdf","sourcePage":17},{"front":"unite different personalities around","meaning":"團結不同性格的人圍繞……","examples":[{"en":"Strong leadership can unite different personalities around a common purpose.","zh":"強而有力的領導可以團結不同性格的人圍繞共同目標。"},{"en":"To unite different personalities around something means to bring different people together under one shared goal.","zh":"unite different personalities around something 的意思是把不同的人帶到同一共同目標之下。"},{"en":"A leader unites different personalities around a project by reminding them of the same outcome.","zh":"領袖可以透過提醒大家同一成果，團結不同性格的人圍繞項目。"},{"en":"Unity does not require everyone to think the same way.","zh":"團結不需要每個人以相同方式思考。"},{"en":"This phrase describes leadership that turns difference into cooperation.","zh":"這個短語描述把差異轉化為合作的領導。"}],"source":"2025 Q4.pdf","sourcePage":17},{"front":"common purpose","meaning":"共同目標","examples":[{"en":"Team members should work towards a common purpose.","zh":"團隊成員應朝共同目標努力。"},{"en":"A common purpose is a shared aim that gives people a reason to cooperate.","zh":"common purpose 是給人合作理由的共同目標。"},{"en":"A project team’s common purpose may be to launch a safe and useful product.","zh":"項目團隊的共同目標可能是推出安全而有用的產品。"},{"en":"A common purpose helps members move beyond personal pride.","zh":"共同目標幫助成員超越個人自尊。"},{"en":"This phrase describes the goal that holds a team together.","zh":"這個短語描述把團隊凝聚在一起的目標。"}],"source":"2025 Q4.pdf","sourcePage":17},{"front":"employers","meaning":"僱主","examples":[{"en":"Employers should create the conditions for fair collaboration.","zh":"僱主應創造公平合作的條件。"},{"en":"Employers are people or organisations that hire and manage workers.","zh":"employers 是聘請和管理員工的人或機構。"},{"en":"Employers influence teamwork by setting systems, expectations, and rewards.","zh":"僱主透過設定制度、期望和獎勵來影響團隊合作。"},{"en":"Good employers do not simply demand collaboration; they support it properly.","zh":"好僱主不只是要求合作，而是適當地支援合作。"},{"en":"This word identifies who has responsibility for workplace conditions.","zh":"這個詞指出誰對職場條件負有責任。"}],"source":"2025 Q4.pdf","sourcePage":17},{"front":"require workers to collaborate","meaning":"要求員工合作","examples":[{"en":"Employers should not simply require workers to collaborate.","zh":"僱主不應只是要求員工合作。"},{"en":"To require workers to collaborate means to demand that employees work together.","zh":"require workers to collaborate 的意思是要求員工一起工作。"},{"en":"Requiring collaboration without clear systems can make teamwork frustrating.","zh":"在沒有清晰制度下要求合作，可以令團隊合作令人沮喪。"},{"en":"Workers need time, tools, and fair evaluation before collaboration can succeed.","zh":"合作要成功，員工需要時間、工具和公平評估。"},{"en":"This phrase describes a demand that must be supported by conditions.","zh":"這個短語描述必須有條件支援的要求。"}],"source":"2025 Q4.pdf","sourcePage":17},{"front":"create the conditions","meaning":"創造條件","examples":[{"en":"Employers should create the conditions that make collaboration fair.","zh":"僱主應創造令合作公平的條件。"},{"en":"To create the conditions means to provide the environment, rules, and support needed for something to work.","zh":"create the conditions 的意思是提供某事發揮作用所需的環境、規則和支援。"},{"en":"Managers create the conditions for teamwork by defining roles and communication channels.","zh":"管理者透過界定角色和溝通渠道來創造團隊合作的條件。"},{"en":"Fair collaboration cannot happen if the workplace rewards free-riding.","zh":"如果職場獎勵搭便車，公平合作就不能發生。"},{"en":"This phrase describes responsibility for building a supportive system.","zh":"這個短語描述建立支援制度的責任。"}],"source":"2025 Q4.pdf","sourcePage":17},{"front":"fair, focused and fruitful","meaning":"公平、專注而有成果","examples":[{"en":"Collaboration should be fair, focused, and fruitful.","zh":"合作應該公平、專注而有成果。"},{"en":"Fair, focused and fruitful means just, clearly directed, and able to produce good results.","zh":"fair, focused and fruitful 的意思是公正、有清晰方向，並能產生好成果。"},{"en":"A fair team shares credit, a focused team follows a common goal, and a fruitful team achieves results.","zh":"公平的團隊分享功勞，專注的團隊跟隨共同目標，有成果的團隊取得成效。"},{"en":"These three qualities make collaboration worth employees’ time.","zh":"這三種質素令合作值得員工投入時間。"},{"en":"This phrase summarises the ideal form of teamwork.","zh":"這個短語總結理想的團隊合作形式。"}],"source":"2025 Q4.pdf","sourcePage":18},{"front":"only then","meaning":"只有到那時","examples":[{"en":"Only then will group work be valued in everyday professional life.","zh":"只有到那時，小組工作才會在日常職業生活中被重視。"},{"en":"Only then means only after those conditions have been met.","zh":"only then 的意思是只有在那些條件達成之後。"},{"en":"Only then will employees trust group work instead of fearing unfairness.","zh":"只有到那時，員工才會信任小組工作，而不是害怕不公平。"},{"en":"This phrase shows that a result depends on previous actions.","zh":"這個短語顯示某結果取決於之前的行動。"},{"en":"It is useful in conclusions when stressing necessary conditions.","zh":"它在結論中強調必要條件時很有用。"}],"source":"2025 Q4.pdf","sourcePage":18},{"front":"valued not merely in theory","meaning":"不只是理論上被重視","examples":[{"en":"Group work should be valued not merely in theory.","zh":"小組工作不應只是理論上被重視。"},{"en":"Valued not merely in theory means respected not only as an idea but also in real practice.","zh":"valued not merely in theory 的意思是不只作為概念被尊重，也在實際中被重視。"},{"en":"Teamwork is valued not merely in theory when companies reward fair contribution.","zh":"當公司獎勵公平貢獻時，團隊合作就是不只是理論上被重視。"},{"en":"A concept has little use if it is praised in theory but ignored in daily work.","zh":"如果一個概念只在理論上被稱讚，卻在日常工作中被忽視，就沒有太大用處。"},{"en":"This phrase contrasts words with practical reality.","zh":"這個短語把說話與實際現實作對比。"}],"source":"2025 Q4.pdf","sourcePage":18},{"front":"everyday professional life","meaning":"日常職業生活","examples":[{"en":"Group work should be valued in everyday professional life.","zh":"小組工作應在日常職業生活中被重視。"},{"en":"Everyday professional life means the normal daily experience of work.","zh":"everyday professional life 是正常每日工作經驗。"},{"en":"Teamwork matters in everyday professional life through meetings, reports, and shared projects.","zh":"團隊合作透過會議、報告和共同項目在日常職業生活中發揮作用。"},{"en":"Good systems make collaboration useful not only in policy documents but in daily routines.","zh":"良好制度令合作不只在政策文件中有用，也在日常規律中有用。"},{"en":"This phrase brings the essay’s argument back to real workplaces.","zh":"這個短語把文章論點帶回真實職場。"}],"source":"2025 Q4.pdf","sourcePage":18}],"dse/writing/part-b/2025/Q5":[{"front":"seven days without meat","meaning":"七日不吃肉","examples":[{"en":"The writer spent seven days without meat.","zh":"作者七日不吃肉。"},{"en":"Seven days without meat means not eating meat for one full week.","zh":"七日不吃肉意思是整整一星期不吃肉類。"},{"en":"A student may try seven days without meat to test a healthier diet.","zh":"學生可能嘗試七日不吃肉，以測試較健康的飲食。"},{"en":"Seven days without meat can reveal how much someone relies on old food habits.","zh":"七日不吃肉可以顯示一個人有多依賴舊有飲食習慣。"},{"en":"The week becomes meaningful because it changes both meals and thinking.","zh":"這一星期之所以有意義，是因為它改變了膳食和想法。"}],"source":"2025 Q5.pdf","sourcePage":1},{"front":"one-week experiment","meaning":"一星期實驗","examples":[{"en":"The one-week experiment changed how the writer thought about food.","zh":"這個一星期實驗改變了作者對食物的看法。"},{"en":"A one-week experiment is a short test that lasts for seven days.","zh":"一星期實驗是持續七日的短期測試。"},{"en":"A person may start a one-week experiment to see whether a new habit is possible.","zh":"一個人可能開始一星期實驗，看看新習慣是否可行。"},{"en":"Short experiments can feel safe because they do not require lifelong commitment at first.","zh":"短期實驗一開始不要求終身承諾，所以感覺較安全。"},{"en":"This one-week experiment becomes the beginning of a lasting choice.","zh":"這個一星期實驗成為持久選擇的開始。"}],"source":"2025 Q5.pdf","sourcePage":1},{"front":"will not end here","meaning":"不會就此結束","examples":[{"en":"The writer’s vegetarian experiment will not end here.","zh":"作者的素食實驗不會就此結束。"},{"en":"Will not end here means something will continue beyond the present point.","zh":"不會就此結束意思是某事會在現在這一點之後繼續。"},{"en":"A useful challenge may not end here if it changes someone’s values.","zh":"如果一個有用的挑戰改變了人的價值觀，它可能不會就此結束。"},{"en":"The experiment will not end here because the writer wants to continue being vegetarian.","zh":"這個實驗不會就此結束，因為作者想繼續做素食者。"},{"en":"This phrase suggests that a temporary test has become something deeper.","zh":"這個短語暗示暫時性測試已變成更深層的東西。"}],"source":"2025 Q5.pdf","sourcePage":1},{"front":"last Monday","meaning":"上星期一","examples":[{"en":"Last Monday, the writer made a promise to himself.","zh":"上星期一，作者向自己許下承諾。"},{"en":"Last Monday means the Monday before the present week or before the time of writing.","zh":"上星期一意思是現在這星期或寫作時間之前的那個星期一。"},{"en":"Last Monday, a student decided to stop buying takeaway lunches.","zh":"上星期一，一位學生決定停止購買外賣午餐。"},{"en":"Mentioning last Monday makes the challenge feel specific and recent.","zh":"提到上星期一令挑戰感覺具體而近期。"},{"en":"The promise began on last Monday, but its effect lasted beyond the week.","zh":"承諾在上星期一開始，但它的影響延續到那一星期之後。"}],"source":"2025 Q5.pdf","sourcePage":1},{"front":"made a promise to myself","meaning":"向自己許下承諾","examples":[{"en":"I made what I thought was a small promise to myself.","zh":"我向自己許下了一個我以為很小的承諾。"},{"en":"To make a promise to myself means to privately decide to do something and try to keep it.","zh":"向自己許下承諾意思是私下決定做某事，並嘗試遵守。"},{"en":"A student may make a promise to herself to sleep earlier for one week.","zh":"學生可能向自己許下承諾，為期一星期早點睡覺。"},{"en":"Promises to ourselves can be powerful because they test our honesty.","zh":"對自己的承諾很有力量，因為它考驗我們的誠實。"},{"en":"The writer’s small promise becomes larger as the week changes his thinking.","zh":"作者的小承諾隨著一星期改變他的想法而變得更大。"}],"source":"2025 Q5.pdf","sourcePage":1},{"front":"for one week","meaning":"為期一星期","examples":[{"en":"For one week, I would become a vegetarian.","zh":"為期一星期，我會成為素食者。"},{"en":"For one week means during a period of seven days.","zh":"為期一星期意思是在七日的時間內。"},{"en":"For one week, a family may cook only home-made meals to test healthier habits.","zh":"為期一星期，一個家庭可能只煮家常飯來測試較健康的習慣。"},{"en":"A limited period makes a difficult change feel more manageable.","zh":"有限時間能令困難改變感覺較容易管理。"},{"en":"For one week, the writer tested a lifestyle that later felt sustainable.","zh":"為期一星期，作者測試了一種後來覺得可持續的生活方式。"}],"source":"2025 Q5.pdf","sourcePage":1},{"front":"become a vegetarian","meaning":"成為素食者","examples":[{"en":"For one week, I would become a vegetarian.","zh":"為期一星期，我會成為素食者。"},{"en":"To become a vegetarian means to stop eating meat and choose plant-based meals.","zh":"成為素食者意思是停止吃肉，並選擇以植物為主的膳食。"},{"en":"A person may become a vegetarian for health, ethical, or environmental reasons.","zh":"一個人可能因健康、道德或環境原因成為素食者。"},{"en":"Becoming vegetarian can feel difficult at first if meat has always been the centre of meals.","zh":"如果肉一直是一餐的中心，成為素食者一開始可能感覺困難。"},{"en":"The writer becomes vegetarian as an experiment, but the change grows more meaningful.","zh":"作者以實驗方式成為素食者，但這個改變逐漸變得更有意義。"}],"source":"2025 Q5.pdf","sourcePage":1},{"front":"at first","meaning":"起初","examples":[{"en":"At first, it was simply an experiment.","zh":"起初，這只是一個實驗。"},{"en":"At first means in the beginning, before later changes happened.","zh":"起初意思是在開始時，在後來改變發生之前。"},{"en":"At first, the writer did not expect the challenge to change his thinking.","zh":"起初，作者沒有預料這個挑戰會改變自己的想法。"},{"en":"Many lasting habits begin as small tests at first.","zh":"許多持久習慣起初都只是小測試。"},{"en":"This phrase helps show the difference between the beginning and the final result.","zh":"這個短語幫助顯示開始和最終結果之間的差別。"}],"source":"2025 Q5.pdf","sourcePage":1},{"front":"simply an experiment","meaning":"只是一個實驗","examples":[{"en":"At first, becoming vegetarian was simply an experiment.","zh":"起初，成為素食者只是一個實驗。"},{"en":"Simply an experiment means only a test, not yet a serious long-term decision.","zh":"只是一個實驗意思是只是一次測試，尚未是嚴肅長期決定。"},{"en":"Trying a new breakfast for seven days may be simply an experiment.","zh":"嘗試七日新早餐可能只是一個實驗。"},{"en":"An experiment can become important when it reveals hidden habits.","zh":"當實驗揭示隱藏習慣時，它可以變得重要。"},{"en":"The vegetarian week begins simply as an experiment but becomes a choice.","zh":"素食一星期起初只是一個實驗，但後來變成選擇。"}],"source":"2025 Q5.pdf","sourcePage":1},{"front":"heard claims that","meaning":"聽過一些說法指","examples":[{"en":"I had heard claims that eating less meat could improve health.","zh":"我聽過一些說法指少吃肉可以改善健康。"},{"en":"Heard claims that means had heard people say or argue that something is true.","zh":"聽過一些說法指某事，意思是聽過有人說或主張某事是真的。"},{"en":"A student may hear claims that sleeping earlier improves memory.","zh":"學生可能聽過一些說法指早睡可以改善記憶。"},{"en":"Hearing claims is different from experiencing the result personally.","zh":"聽過說法和親身經歷結果是不同的。"},{"en":"The writer begins with claims, then tests them through daily meals.","zh":"作者由一些說法開始，然後透過每日膳食測試它們。"}],"source":"2025 Q5.pdf","sourcePage":1},{"front":"eating less meat","meaning":"少吃肉","examples":[{"en":"Eating less meat could improve health and reduce environmental harm.","zh":"少吃肉可以改善健康並減少對環境的傷害。"},{"en":"Eating less meat means reducing the amount of meat in one’s diet.","zh":"少吃肉意思是減少飲食中的肉類份量。"},{"en":"A family may start eating less meat by having vegetarian dinners twice a week.","zh":"一個家庭可以透過每星期吃兩次素食晚餐來開始少吃肉。"},{"en":"Eating less meat can encourage people to try beans, tofu, vegetables, and grains.","zh":"少吃肉可以鼓勵人嘗試豆類、豆腐、蔬菜和穀物。"},{"en":"For the writer, eating less meat becomes a way to think more carefully about choices.","zh":"對作者來說，少吃肉成為更仔細思考選擇的方法。"}],"source":"2025 Q5.pdf","sourcePage":2},{"front":"improve health","meaning":"改善健康","examples":[{"en":"Eating less meat may improve health.","zh":"少吃肉可能改善健康。"},{"en":"To improve health means to make the body or mind healthier.","zh":"改善健康意思是令身體或心理更健康。"},{"en":"More vegetables and fruit may improve health by adding fibre and nutrients.","zh":"更多蔬菜和水果可以透過增加纖維和營養來改善健康。"},{"en":"A healthier diet can improve energy, digestion, and mood.","zh":"更健康飲食可以改善精力、消化和心情。"},{"en":"The writer notices small health changes during the vegetarian week.","zh":"作者在素食一星期期間注意到一些健康上的小改變。"}],"source":"2025 Q5.pdf","sourcePage":2},{"front":"reduce environmental harm","meaning":"減少對環境的傷害","examples":[{"en":"Eating less meat could reduce environmental harm.","zh":"少吃肉可以減少對環境的傷害。"},{"en":"To reduce environmental harm means to cause less damage to nature and the planet.","zh":"減少對環境的傷害意思是對自然和地球造成較少破壞。"},{"en":"Choosing plant-based meals can reduce environmental harm if it lowers resource use.","zh":"如果植物性膳食降低資源使用，就可以減少對環境的傷害。"},{"en":"The writer begins to connect daily meals with wider environmental consequences.","zh":"作者開始把每日膳食與更廣泛的環境後果連繫起來。"},{"en":"Small food choices can feel meaningful when they reduce harm over time.","zh":"當小小飲食選擇長期減少傷害時，它們會變得有意義。"}],"source":"2025 Q5.pdf","sourcePage":2},{"front":"make people more mindful about","meaning":"令人在……方面更有意識","examples":[{"en":"Eating less meat can make people more mindful about what they consume.","zh":"少吃肉可以令人對自己所食用的東西更有意識。"},{"en":"To make people more mindful about something means to make them think about it more carefully.","zh":"令人在某方面更有意識，意思是令人更仔細思考那件事。"},{"en":"Reading food labels can make students more mindful about sugar and salt.","zh":"閱讀食物標籤可以令人對糖和鹽更有意識。"},{"en":"Vegetarian meals made the writer more mindful about ingredients and habits.","zh":"素食膳食令作者對食材和習慣更有意識。"},{"en":"Being mindful turns eating from automatic behaviour into thoughtful choice.","zh":"有意識地進食會把自動行為變成深思熟慮的選擇。"}],"source":"2025 Q5.pdf","sourcePage":2},{"front":"what they consumed","meaning":"他們所食用的東西","examples":[{"en":"The experiment made people think about what they consumed.","zh":"這個實驗令人思考他們所食用的東西。"},{"en":"What they consumed means the food, drinks, or products people used or ate.","zh":"他們所食用的東西是指人們使用或吃下的食物、飲品或產品。"},{"en":"A food diary can help students notice what they consumed during a week.","zh":"飲食日記可以幫助學生注意自己一星期所食用的東西。"},{"en":"Thinking about what we consume can reveal hidden habits.","zh":"思考我們所消耗的東西，可以揭示隱藏習慣。"},{"en":"The writer realises that meals are choices, not just routine.","zh":"作者意識到膳食是選擇，而不只是慣例。"}],"source":"2025 Q5.pdf","sourcePage":2},{"front":"sceptical","meaning":"懷疑的","examples":[{"en":"At first, I was sceptical about becoming vegetarian.","zh":"起初，我對成為素食者感到懷疑。"},{"en":"Sceptical means doubtful or not easily convinced.","zh":"懷疑的意思是不太相信或不容易被說服。"},{"en":"A person may be sceptical about vegetarian meals if they think they will not be filling.","zh":"如果一個人以為素食不會飽肚，他可能對素食膳食感到懷疑。"},{"en":"Being sceptical can be useful if it leads to honest testing.","zh":"如果懷疑能引向誠實測試，它也可以有用。"},{"en":"The writer starts sceptical but becomes more confident through experience.","zh":"作者一開始懷疑，但透過經驗變得更有信心。"}],"source":"2025 Q5.pdf","sourcePage":2},{"front":"treated meat as","meaning":"把肉視為","examples":[{"en":"I had always treated meat as the centre of a proper meal.","zh":"我一直把肉視為一頓像樣飯的中心。"},{"en":"To treat meat as something means to regard meat in that particular way.","zh":"把肉視為某物，意思是以某種特定方式看待肉類。"},{"en":"Some families treat meat as the most important part of dinner.","zh":"有些家庭把肉視為晚餐最重要的部分。"},{"en":"Treating meat as essential can make vegetarian food seem incomplete.","zh":"把肉視為必要，會令素食看起來不完整。"},{"en":"The experiment challenges the writer’s old way of seeing meals.","zh":"這個實驗挑戰了作者對膳食的舊看法。"}],"source":"2025 Q5.pdf","sourcePage":2},{"front":"the centre of a proper meal","meaning":"正式一餐的中心","examples":[{"en":"I had always treated meat as the centre of a proper meal.","zh":"我一直把肉視為正式一餐的中心。"},{"en":"The centre of a proper meal means the main part that makes a meal feel complete.","zh":"正式一餐的中心意思是令一餐感覺完整的主要部分。"},{"en":"For many people, rice, vegetables, and soup feel incomplete without meat at the centre.","zh":"對很多人來說，如果沒有肉在中心，飯、菜和湯都像不完整。"},{"en":"The experiment shows that a proper meal can have other centres.","zh":"這個實驗顯示，一頓像樣的飯也可以有其他中心。"},{"en":"Tofu, beans, mushrooms, and pasta can also make a meal satisfying.","zh":"豆腐、豆類、蘑菇和意粉也可以令一餐令人滿足。"}],"source":"2025 Q5.pdf","sourcePage":2},{"front":"a proper meal","meaning":"一頓像樣的飯","examples":[{"en":"Meat used to feel like the centre of a proper meal.","zh":"肉以前感覺像一頓像樣的飯的中心。"},{"en":"A proper meal is a meal that feels complete, balanced, and satisfying.","zh":"一頓像樣的飯是感覺完整、均衡和令人滿足的一餐。"},{"en":"A proper meal does not always need meat if it includes enough nutrition and variety.","zh":"如果有足夠營養和變化，一頓像樣的飯不一定需要肉。"},{"en":"The writer learns that vegetables and beans can form a proper meal too.","zh":"作者學到蔬菜和豆類也可以組成一頓像樣的飯。"},{"en":"What counts as a proper meal can change when habits change.","zh":"當習慣改變，甚麼算是一頓像樣的飯也會改變。"}],"source":"2025 Q5.pdf","sourcePage":2},{"front":"find out whether","meaning":"查明是否","examples":[{"en":"I wanted to find out whether a vegetarian lifestyle was sustainable.","zh":"我想查明素食生活方式是否可持續。"},{"en":"To find out whether means to discover if something is true or possible.","zh":"查明是否意思是找出某事是否真實或可行。"},{"en":"A student may try cycling to school to find out whether it saves time.","zh":"學生可能試著踩單車上學，以查明是否能節省時間。"},{"en":"The writer uses the week to test an idea instead of only guessing.","zh":"作者用這一星期測試想法，而不是只靠猜測。"},{"en":"Finding out through experience can change doubt into confidence.","zh":"透過經驗查明真相，可以把懷疑變成信心。"}],"source":"2025 Q5.pdf","sourcePage":2},{"front":"vegetarian lifestyle","meaning":"素食生活方式","examples":[{"en":"I wanted to test whether a vegetarian lifestyle was sustainable.","zh":"我想測試素食生活方式是否可持續。"},{"en":"A vegetarian lifestyle is a way of living and eating that avoids meat.","zh":"素食生活方式是一種避免吃肉的生活和飲食方式。"},{"en":"A vegetarian lifestyle may include tofu, beans, vegetables, grains, fruit, and careful planning.","zh":"素食生活方式可能包括豆腐、豆類、蔬菜、穀物、水果和仔細規劃。"},{"en":"It becomes easier when people know tasty alternatives to meat.","zh":"當人們知道美味的肉類替代選擇時，它會變得較容易。"},{"en":"The writer discovers that a vegetarian lifestyle can be practical, not just fashionable.","zh":"作者發現素食生活方式可以實際，而不只是時髦。"}],"source":"2025 Q5.pdf","sourcePage":3},{"front":"genuinely sustainable","meaning":"真正可持續","examples":[{"en":"I wanted to know whether a vegetarian lifestyle was genuinely sustainable.","zh":"我想知道素食生活方式是否真正可持續。"},{"en":"Genuinely sustainable means truly possible to continue for a long time.","zh":"真正可持續意思是確實能長期繼續。"},{"en":"A diet is genuinely sustainable if it is healthy, affordable, and satisfying.","zh":"如果一種飲食健康、負擔得起又令人滿足，它就是真正可持續。"},{"en":"The writer tests sustainability by living the change for seven days.","zh":"作者透過七日實踐改變來測試可持續性。"},{"en":"The challenge shows that vegetarian meals can be repeated without feeling like sacrifice.","zh":"這個挑戰顯示素食膳食可以重複進行，而不感覺像犧牲。"}],"source":"2025 Q5.pdf","sourcePage":3},{"front":"merely fashionable","meaning":"只是時髦","examples":[{"en":"I wondered whether vegetarianism was sustainable or merely fashionable.","zh":"我想知道素食主義是可持續，還是只是時髦。"},{"en":"Merely fashionable means popular mainly because it is trendy, not because it is meaningful or useful.","zh":"只是時髦意思是主要因潮流而受歡迎，而不是因為有意義或有用。"},{"en":"A habit may be merely fashionable if people follow it without understanding why.","zh":"如果人們不明白原因就跟隨某習慣，那習慣可能只是時髦。"},{"en":"The writer wants to know whether vegetarianism has real value beyond trendiness.","zh":"作者想知道素食主義是否在潮流以外有真正價值。"},{"en":"By the end of the week, it feels practical rather than merely fashionable.","zh":"到一星期結束時，它感覺是實際的，而不只是時髦。"}],"source":"2025 Q5.pdf","sourcePage":3},{"front":"now that","meaning":"既然現在","examples":[{"en":"Now that the week is over, I can speak with confidence.","zh":"既然現在這一星期已經結束，我可以有信心地說。"},{"en":"Now that means because the situation has changed or something has happened.","zh":"既然現在意思是因為情況已改變或某事已發生。"},{"en":"Now that the exam is over, students can reflect on their preparation.","zh":"既然現在考試已經結束，學生可以反思自己的準備。"},{"en":"This phrase connects a completed experience with a new conclusion.","zh":"這個短語把已完成的經歷和新的結論連接起來。"},{"en":"Now that the experiment is finished, the writer can judge it more fairly.","zh":"既然實驗完成了，作者可以更公平地判斷它。"}],"source":"2025 Q5.pdf","sourcePage":3},{"front":"with confidence","meaning":"有信心地","examples":[{"en":"I can say with confidence that the challenge changed me.","zh":"我可以有信心地說，這個挑戰改變了我。"},{"en":"With confidence means with certainty and belief in what one is saying.","zh":"有信心地意思是帶著確定和相信來說話。"},{"en":"After practising daily, a student may speak with confidence in class.","zh":"每天練習後，學生可能在課堂上有信心地發言。"},{"en":"Personal experience gives the writer confidence to make a stronger claim.","zh":"親身經歷令作者有信心提出更有力的說法。"},{"en":"He can speak with confidence because he tested vegetarianism himself.","zh":"他可以有信心地說，因為他親自測試了素食。"}],"source":"2025 Q5.pdf","sourcePage":3},{"front":"short challenge","meaning":"短暫挑戰","examples":[{"en":"This short challenge changed what I eat and how I think.","zh":"這個短暫挑戰改變了我吃甚麼和如何思考。"},{"en":"A short challenge is a brief task or test that asks someone to change behaviour.","zh":"短暫挑戰是要求某人改變行為的短期任務或測試。"},{"en":"A seven-day vegetarian challenge can be short but still powerful.","zh":"七日素食挑戰可以短暫，但仍很有力量。"},{"en":"Short challenges can reveal habits that people normally ignore.","zh":"短暫挑戰可以揭示人們平時忽略的習慣。"},{"en":"The challenge is short in time but large in effect.","zh":"這個挑戰在時間上短暫，但影響很大。"}],"source":"2025 Q5.pdf","sourcePage":3},{"front":"not only…, but also…","meaning":"不只……而且……","examples":[{"en":"The challenge changed not only what I eat, but also how I think.","zh":"這個挑戰不只改變我吃甚麼，而且改變我如何思考。"},{"en":"Not only…, but also… connects two important effects or ideas.","zh":"不只……而且……連接兩個重要影響或想法。"},{"en":"The experiment affected not only my meals, but also my values.","zh":"這個實驗不只影響我的膳食，而且影響我的價值觀。"},{"en":"This structure helps show that the change is wider than expected.","zh":"這個結構幫助顯示改變比預期更廣。"},{"en":"It makes the sentence stronger by adding a second important result.","zh":"它透過加入第二個重要結果令句子更有力。"}],"source":"2025 Q5.pdf","sourcePage":3},{"front":"continue being a vegetarian","meaning":"繼續做素食者","examples":[{"en":"I will continue being a vegetarian.","zh":"我會繼續做素食者。"},{"en":"To continue being a vegetarian means to keep avoiding meat after the experiment ends.","zh":"繼續做素食者意思是在實驗結束後仍繼續避免吃肉。"},{"en":"A person may continue being vegetarian after discovering enough satisfying meals.","zh":"一個人發現足夠令人滿足的膳食後，可能會繼續做素食者。"},{"en":"Continuing shows that the week was not just a temporary performance.","zh":"繼續下去顯示這一星期不只是暫時表現。"},{"en":"The writer continues because the lifestyle now feels practical and meaningful.","zh":"作者繼續，因為這種生活方式現在感覺實際而有意義。"}],"source":"2025 Q5.pdf","sourcePage":3},{"front":"the experience has shown me that","meaning":"這次經歷令我明白","examples":[{"en":"The experience has shown me that vegetarianism is practical.","zh":"這次經歷令我明白素食主義是實際的。"},{"en":"The experience has shown me that means I learned something through living through it.","zh":"這次經歷令我明白某事，意思是我透過親身經歷學到某事。"},{"en":"The week has shown me that habits can change faster than expected.","zh":"這一星期令我明白習慣可以比預期更快改變。"},{"en":"This phrase gives personal evidence for the writer’s conclusion.","zh":"這個短語為作者結論提供個人證據。"},{"en":"The experience shows him more than claims or articles could.","zh":"這次經歷讓他學到的，比一些說法或文章更多。"}],"source":"2025 Q5.pdf","sourcePage":3},{"front":"eye-opening","meaning":"令人眼界大開","examples":[{"en":"The experiment was healthier and more eye-opening than I had imagined.","zh":"這個實驗比我想像中更健康，也更令人眼界大開。"},{"en":"Eye-opening means surprising in a way that makes someone understand more.","zh":"令人眼界大開意思是令人驚訝，並令人體會更多。"},{"en":"Cooking without meat can be eye-opening if it reveals many new ingredients.","zh":"如果不吃肉煮食讓人發現許多新食材，它可以令人眼界大開。"},{"en":"An eye-opening experience changes how people see ordinary habits.","zh":"令人眼界大開的經歷會改變人看待日常習慣的方式。"},{"en":"For the writer, the week opens his eyes to nutrition and consequence.","zh":"對作者來說，這一星期令他在營養和後果方面眼界大開。"}],"source":"2025 Q5.pdf","sourcePage":3},{"front":"far more practical than","meaning":"遠比……實際","examples":[{"en":"Vegetarianism was far more practical than I had imagined.","zh":"素食主義遠比我想像中實際。"},{"en":"Far more practical than means much easier or more useful than expected.","zh":"遠比……實際意思是比預期容易或有用得多。"},{"en":"Cooking vegetarian lunches was far more practical than buying fast food every day.","zh":"煮素食午餐遠比每天買快餐實際。"},{"en":"The writer discovers that practical problems were smaller than his fear.","zh":"作者發現實際困難比他的恐懼小。"},{"en":"Vegetarianism feels practical because the meals are filling and simple to prepare.","zh":"素食感覺實際，因為膳食飽肚又容易準備。"}],"source":"2025 Q5.pdf","sourcePage":4},{"front":"than I had imagined","meaning":"比我想像中","examples":[{"en":"The lifestyle was more practical than I had imagined.","zh":"這種生活方式比我想像中更實際。"},{"en":"Than I had imagined means compared with what I expected before.","zh":"比我想像中意思是與我之前預期相比。"},{"en":"The recipe was easier than I had imagined.","zh":"這個食譜比我想像中更容易。"},{"en":"This phrase shows that experience corrected an earlier assumption.","zh":"這個短語顯示經驗糾正了早前假設。"},{"en":"The writer’s week was better and more manageable than he had expected.","zh":"作者這一星期比他想像中更好，也更容易應付。"}],"source":"2025 Q5.pdf","sourcePage":4},{"front":"the first lesson I learnt","meaning":"我學到的第一課","examples":[{"en":"The first lesson I learnt was about my eating habits.","zh":"我學到的第一課是關於自己的飲食習慣。"},{"en":"The first lesson I learnt means the earliest important thing I understood from the experience.","zh":"我學到的第一課意思是我從經歷中最早明白的重要事情。"},{"en":"The first lesson I learnt from cooking was that preparation saves time.","zh":"我從煮食中學到的第一課是準備能節省時間。"},{"en":"This phrase helps organise reflection after a challenge.","zh":"這個短語幫助整理挑戰後的反思。"},{"en":"The writer’s first lesson is that many food choices were automatic.","zh":"作者學到的第一課是許多食物選擇其實出於習慣。"}],"source":"2025 Q5.pdf","sourcePage":4},{"front":"eating habits","meaning":"飲食習慣","examples":[{"en":"My eating habits had been automatic rather than necessary.","zh":"我的飲食習慣一直出於慣性，而不是必要。"},{"en":"Eating habits are regular ways of choosing, preparing, and eating food.","zh":"飲食習慣是選擇、準備和進食食物的固定方式。"},{"en":"Eating the same lunch every day can become an eating habit.","zh":"每天吃同一款午餐可以成為飲食習慣。"},{"en":"Habits shape meals even when people think they are making free choices.","zh":"即使人們以為自己自由選擇，習慣仍會塑造膳食。"},{"en":"The experiment makes the writer notice and question his eating habits.","zh":"這個實驗令作者注意並質疑自己的飲食習慣。"}],"source":"2025 Q5.pdf","sourcePage":4},{"front":"automatic rather than necessary","meaning":"出於習慣而非必要","examples":[{"en":"Many of my eating habits had been automatic rather than necessary.","zh":"我的許多飲食習慣一直出於習慣而非必要。"},{"en":"Automatic rather than necessary means done from habit, not because it is truly needed.","zh":"出於習慣而非必要意思是因慣性而做，不是因為真正需要。"},{"en":"Ordering meat at lunch may be automatic rather than necessary.","zh":"午餐點肉可能是出於習慣而非必要。"},{"en":"When choices are automatic, people may stop asking why they make them.","zh":"當選擇變成自動，人們可能不再問自己為何這樣選。"},{"en":"The writer learns that meat was often routine, not real need.","zh":"作者明白肉類很多時候只是慣例，而不是真正需要。"}],"source":"2025 Q5.pdf","sourcePage":4},{"front":"stood in front of","meaning":"站在……前","examples":[{"en":"On the first day, I stood in front of the refrigerator.","zh":"第一天，我站在雪櫃前。"},{"en":"To stand in front of something means to be positioned facing it.","zh":"站在某物前意思是面向它站著。"},{"en":"A hungry student may stand in front of the fridge wondering what to eat.","zh":"肚餓學生可能站在雪櫃前，想著吃甚麼。"},{"en":"Standing there shows hesitation and uncertainty at the start of the challenge.","zh":"站在那裏顯示挑戰開始時的猶豫和不確定。"},{"en":"The fridge is full, but the writer’s old habits make him feel lost.","zh":"雪櫃很滿，但作者的舊習慣令他感到迷失。"}],"source":"2025 Q5.pdf","sourcePage":4},{"front":"refrigerator","meaning":"雪櫃","examples":[{"en":"I stood in front of the refrigerator for nearly five minutes.","zh":"我在雪櫃前站了差不多五分鐘。"},{"en":"A refrigerator is a machine that keeps food cold.","zh":"雪櫃是用來保持食物低溫的機器。"},{"en":"Families store vegetables, tofu, eggs, and leftovers in the refrigerator.","zh":"家庭會把蔬菜、豆腐、雞蛋和剩菜放進雪櫃。"},{"en":"The refrigerator becomes important because it shows there is food, just not the food the writer expected.","zh":"雪櫃變得重要，因為它顯示有食物，只是不是作者預期的食物。"},{"en":"Looking into the refrigerator reveals how strongly meat shaped his meal planning.","zh":"看著雪櫃讓他發現肉類多麼深地塑造了自己的膳食安排。"}],"source":"2025 Q5.pdf","sourcePage":4},{"front":"nearly five minutes","meaning":"差不多五分鐘","examples":[{"en":"I stood in front of the refrigerator for nearly five minutes.","zh":"我在雪櫃前站了差不多五分鐘。"},{"en":"Nearly five minutes means almost five minutes.","zh":"差不多五分鐘意思是接近五分鐘。"},{"en":"A person may stare at a menu for nearly five minutes when they are unsure what to choose.","zh":"當一個人不知道選甚麼時，可能盯著餐牌差不多五分鐘。"},{"en":"The long pause shows how unprepared the writer feels without meat.","zh":"這個長停頓顯示作者在沒有肉時感到多麼毫無準備。"},{"en":"Nearly five minutes is a small detail that reveals a large habit.","zh":"差不多五分鐘是一個小細節，卻揭示了一個大習慣。"}],"source":"2025 Q5.pdf","sourcePage":4},{"front":"suddenly aware of","meaning":"突然意識到","examples":[{"en":"I was suddenly aware of how often I planned meals around meat.","zh":"我突然意識到自己多常圍繞肉類安排膳食。"},{"en":"Suddenly aware of means unexpectedly noticing or realising something clearly.","zh":"突然意識到意思是出乎意料地清楚注意或明白某事。"},{"en":"A student may become suddenly aware of how often they check their phone.","zh":"學生可能突然意識到自己多常查看手機。"},{"en":"Awareness is the first step toward changing a habit.","zh":"意識是改變習慣的第一步。"},{"en":"The writer suddenly sees that meat has been controlling his meal choices.","zh":"作者突然看見肉類一直在主導他的膳食選擇。"}],"source":"2025 Q5.pdf","sourcePage":4},{"front":"planned meals around","meaning":"圍繞……安排膳食","examples":[{"en":"I often planned meals around chicken, ham or beef.","zh":"我經常圍繞雞肉、火腿或牛肉安排膳食。"},{"en":"To plan meals around something means to make that food the main part of the meal.","zh":"圍繞某物安排膳食，意思是把那種食物作為一餐的主要部分。"},{"en":"A family may plan dinner around fish and then choose vegetables to match it.","zh":"家庭可能圍繞魚安排晚餐，再選配合的蔬菜。"},{"en":"Planning meals around meat can make plant-based food feel secondary.","zh":"圍繞肉類安排膳食會令植物性食物感覺次要。"},{"en":"The experiment teaches the writer to plan meals around flavour, nutrition, and variety instead.","zh":"這個實驗教作者改為圍繞味道、營養和變化安排膳食。"}],"source":"2025 Q5.pdf","sourcePage":4},{"front":"chicken, ham or beef","meaning":"雞肉、火腿或牛肉","examples":[{"en":"I often planned meals around chicken, ham or beef.","zh":"我經常圍繞雞肉、火腿或牛肉安排膳食。"},{"en":"Chicken, ham or beef are common meat choices in everyday meals.","zh":"雞肉、火腿或牛肉是日常膳食中常見的肉類選擇。"},{"en":"A sandwich, rice bowl, or pasta dish may often include chicken, ham or beef.","zh":"三文治、飯碗或意粉常可能包含雞肉、火腿或牛肉。"},{"en":"The list shows how ordinary and automatic meat had become for the writer.","zh":"這個列表顯示肉類對作者來說已變得多麼普通和自動。"},{"en":"Removing chicken, ham and beef forces him to think of other centres for meals.","zh":"去除雞肉、火腿和牛肉，迫使他思考膳食的其他中心。"}],"source":"2025 Q5.pdf","sourcePage":5},{"front":"without meat","meaning":"沒有肉的情況下","examples":[{"en":"Without meat, I felt oddly unprepared.","zh":"沒有肉的情況下，我奇怪地毫無準備。"},{"en":"Without meat means with no meat included in the meal or diet.","zh":"沒有肉的情況下意思是膳食或飲食中不包括肉類。"},{"en":"Some people feel a meal is incomplete without meat at first.","zh":"有些人一開始會覺得沒有肉的一餐不完整。"},{"en":"Feeling lost without meat shows how strongly habit shapes appetite.","zh":"沒有肉就感到迷失，顯示習慣多麼強烈地塑造食慾。"},{"en":"The writer later learns that meals without meat can still be satisfying.","zh":"作者後來學到沒有肉的一餐仍可以令人滿足。"}],"source":"2025 Q5.pdf","sourcePage":5},{"front":"oddly unprepared","meaning":"奇怪地毫無準備","examples":[{"en":"Without meat, I felt oddly unprepared.","zh":"沒有肉的情況下，我奇怪地毫無準備。"},{"en":"Oddly unprepared means strangely not ready, even though the situation may seem simple.","zh":"奇怪地毫無準備意思是雖然情況看似簡單，卻奇怪地沒有準備好。"},{"en":"A student may feel oddly unprepared when asked to cook without their usual ingredients.","zh":"當被要求不用平常食材煮食時，學生可能奇怪地毫無準備。"},{"en":"The feeling is odd because the kitchen is full of food.","zh":"這種感覺奇怪，因為廚房其實充滿食物。"},{"en":"This phrase reveals that the problem is not hunger, but habit.","zh":"這個短語揭示問題不是飢餓，而是習慣。"}],"source":"2025 Q5.pdf","sourcePage":5},{"front":"as if","meaning":"好像；彷彿","examples":[{"en":"I felt as if there were nothing to eat.","zh":"我感覺好像沒有東西可吃。"},{"en":"As if means like or as though something were true.","zh":"好像或彷彿意思是如同某事是真的一樣。"},{"en":"The fridge was full, but he looked at it as if it were empty.","zh":"雪櫃很滿，但他看著它，好像它是空的。"},{"en":"This phrase expresses feeling, not necessarily fact.","zh":"這個短語表達感受，不一定是事實。"},{"en":"The writer feels as if there is nothing to eat because meat is missing.","zh":"作者感覺好像沒有東西可吃，是因為肉類不見了。"}],"source":"2025 Q5.pdf","sourcePage":5},{"front":"nothing to eat","meaning":"沒有東西可吃","examples":[{"en":"I felt as if there were nothing to eat.","zh":"我感覺好像沒有東西可吃。"},{"en":"Nothing to eat means no food seems available or suitable.","zh":"沒有東西可吃意思是似乎沒有可用或合適的食物。"},{"en":"A person may say there is nothing to eat even when the kitchen is full.","zh":"即使廚房很滿，一個人也可能說沒有東西可吃。"},{"en":"This often means the person cannot see food that fits their habit.","zh":"這通常代表那個人看不見符合自己習慣的食物。"},{"en":"The writer learns that “nothing to eat” was really “nothing familiar to eat”.","zh":"作者學到「沒有東西可吃」其實是「沒有熟悉的東西可吃」。"}],"source":"2025 Q5.pdf","sourcePage":5},{"front":"even though","meaning":"即使","examples":[{"en":"The kitchen was full of food, even though I felt unprepared.","zh":"即使我感到毫無準備，廚房仍充滿食物。"},{"en":"Even though means although something is true.","zh":"即使意思是雖然某事是真的。"},{"en":"Even though the meal had no meat, it was still filling.","zh":"即使那餐沒有肉，它仍然很飽肚。"},{"en":"This phrase shows contrast between fact and feeling.","zh":"這個短語顯示事實和感受之間的對比。"},{"en":"Even though the writer had ingredients, he first lacked imagination.","zh":"即使作者有食材，他一開始缺少的是想像力。"}],"source":"2025 Q5.pdf","sourcePage":5},{"front":"full of","meaning":"充滿；有很多","examples":[{"en":"The kitchen was full of eggs, mushrooms, tofu, tomatoes and pasta.","zh":"廚房充滿雞蛋、蘑菇、豆腐、番茄和意粉。"},{"en":"Full of means containing many things or a large amount of something.","zh":"充滿意思是包含很多東西或大量某物。"},{"en":"A fridge full of vegetables can still feel empty to someone used to meat.","zh":"對習慣吃肉的人來說，充滿蔬菜的雪櫃仍可能感覺空空的。"},{"en":"Being full of ingredients gives the writer many possible meals.","zh":"有很多食材給作者許多可能的膳食選擇。"},{"en":"The phrase shows that the problem is not lack of food, but lack of habit.","zh":"這個短語顯示問題不是缺少食物，而是缺少習慣。"}],"source":"2025 Q5.pdf","sourcePage":5},{"front":"mushrooms","meaning":"蘑菇","examples":[{"en":"The kitchen was full of mushrooms, tofu and tomatoes.","zh":"廚房裏有很多蘑菇、豆腐和番茄。"},{"en":"Mushrooms are edible fungi often used in soups, pasta, rice bowls, and stir-fries.","zh":"蘑菇是可食用真菌，常用於湯、意粉、飯碗和炒菜。"},{"en":"Mushrooms can give vegetarian meals a rich taste and satisfying texture.","zh":"蘑菇可以為素食膳食帶來濃郁味道和令人滿足的口感。"},{"en":"A tomato-and-mushroom pasta can feel filling without meat.","zh":"番茄蘑菇意粉即使沒有肉，也可以令人飽足。"},{"en":"Mushrooms help the writer discover alternatives to his old meal centres.","zh":"蘑菇幫助作者發現舊有膳食中心以外的替代選擇。"}],"source":"2025 Q5.pdf","sourcePage":5},{"front":"tofu","meaning":"豆腐","examples":[{"en":"I used tofu to make a vegetarian rice bowl.","zh":"我用豆腐做了一個素食飯碗。"},{"en":"Tofu is a soft food made from soybeans and often used as a meat alternative.","zh":"豆腐是由黃豆製成的軟身食物，常用作肉類替代品。"},{"en":"Tofu can absorb sauces and flavours in many dishes.","zh":"豆腐可以吸收很多菜式中的醬汁和味道。"},{"en":"A tofu rice bowl can provide protein without using meat.","zh":"豆腐飯碗可以在不用肉的情況下提供蛋白質。"},{"en":"The writer uses tofu to make vegetarian eating feel practical and satisfying.","zh":"作者使用豆腐，令素食感覺實際而令人滿足。"}],"source":"2025 Q5.pdf","sourcePage":5},{"front":"that reaction taught me","meaning":"那個反應教曉我","examples":[{"en":"That reaction taught me something important.","zh":"那個反應教曉我一件重要的事。"},{"en":"That reaction taught me means my response helped me understand a lesson.","zh":"那個反應教曉我，意思是我的反應幫助我理解一課。"},{"en":"Feeling lost in front of a full fridge taught the writer about habit.","zh":"在滿滿的雪櫃前感到迷失，教作者明白習慣的力量。"},{"en":"Reactions can reveal beliefs that people do not usually notice.","zh":"反應可以揭示人們平時沒有注意的信念。"},{"en":"The writer’s confusion teaches him that his diet was less thoughtful than he assumed.","zh":"作者的困惑教他明白自己的飲食比想像中少了深思熟慮。"}],"source":"2025 Q5.pdf","sourcePage":5},{"front":"usual diet","meaning":"平常飲食","examples":[{"en":"My usual diet had been built on habit.","zh":"我的平常飲食一直建基於習慣。"},{"en":"A usual diet is the food a person normally eats.","zh":"平常飲食是一個人通常吃的食物。"},{"en":"A student’s usual diet may include takeaway lunches and late-night snacks.","zh":"學生的平常飲食可能包括外賣午餐和深夜小食。"},{"en":"The writer’s usual diet had meat at the centre almost automatically.","zh":"作者的平常飲食幾乎自動地把肉放在中心。"},{"en":"Changing the usual diet helps him notice choices he had stopped questioning.","zh":"改變平常飲食幫助他注意到自己已不再質疑的選擇。"}],"source":"2025 Q5.pdf","sourcePage":6},{"front":"built on thoughtful choice","meaning":"建基於深思熟慮的選擇","examples":[{"en":"My diet had not been built on thoughtful choice.","zh":"我的飲食並不是建基於深思熟慮的選擇。"},{"en":"Built on thoughtful choice means based on careful and conscious decisions.","zh":"建基於深思熟慮的選擇，意思是以仔細和有意識的決定為基礎。"},{"en":"A healthy meal plan should be built on thoughtful choice rather than habit alone.","zh":"健康膳食計劃應建基於深思熟慮的選擇，而不只是習慣。"},{"en":"The writer realises his old diet was built on convenience, not reflection.","zh":"作者意識到自己的舊飲食建基於方便，而不是反思。"},{"en":"After the experiment, he wants food choices to be more deliberate.","zh":"實驗後，他希望食物選擇變得更有意識。"}],"source":"2025 Q5.pdf","sourcePage":6},{"front":"thoughtful choice","meaning":"深思熟慮的選擇","examples":[{"en":"A good diet should be built on thoughtful choice.","zh":"良好飲食應建基於深思熟慮的選擇。"},{"en":"Thoughtful choice means a decision made with care, awareness, and purpose.","zh":"深思熟慮的選擇是帶著用心、意識和目的作出的決定。"},{"en":"Choosing tofu instead of a burger can be a thoughtful choice if it supports health goals.","zh":"如果選擇豆腐而不是漢堡能支持健康目標，這可以是深思熟慮的選擇。"},{"en":"Thoughtful choices make eating more meaningful and less automatic.","zh":"深思熟慮的選擇令進食更有意義，而不那麼自動。"},{"en":"The vegetarian week turns daily meals into thoughtful choices.","zh":"素食一星期把每日膳食變成深思熟慮的選擇。"}],"source":"2025 Q5.pdf","sourcePage":6},{"front":"once I forced myself to","meaning":"一旦我迫使自己","examples":[{"en":"Once I forced myself to think differently, the situation changed.","zh":"一旦我迫使自己換個方式思考，情況就改變了。"},{"en":"Once I forced myself to means as soon as I made myself do something difficult.","zh":"一旦我迫使自己做某事，意思是當我令自己做困難事情時。"},{"en":"Once I forced myself to cook, I realised vegetarian meals were not impossible.","zh":"一旦我迫使自己煮食，我就意識到素食膳食並非不可能。"},{"en":"Sometimes change begins only when habit is interrupted on purpose.","zh":"有時改變只有在習慣被刻意打斷時才開始。"},{"en":"The writer’s effort to think differently opens new possibilities.","zh":"作者迫使自己換個方式思考，打開了新的可能性。"}],"source":"2025 Q5.pdf","sourcePage":6},{"front":"think differently","meaning":"換個方式思考","examples":[{"en":"I forced myself to think differently about food.","zh":"我迫使自己換個方式思考食物。"},{"en":"To think differently means to change the way one understands or approaches something.","zh":"換個方式思考意思是改變理解或處理某事的方式。"},{"en":"A student may think differently about exercise after trying a sport they enjoy.","zh":"學生嘗試自己喜歡的運動後，可能會換個方式思考運動。"},{"en":"Thinking differently helps people see options hidden by habit.","zh":"換個方式思考幫助人看見被習慣隱藏的選項。"},{"en":"The writer thinks differently when he stops asking where the meat is.","zh":"當作者不再問肉在哪裏時，他就是換個方式思考。"}],"source":"2025 Q5.pdf","sourcePage":6},{"front":"changed quickly","meaning":"很快改變","examples":[{"en":"Once I thought differently, the situation changed quickly.","zh":"一旦我換個方式思考，情況就很快改變。"},{"en":"Changed quickly means became different in a short time.","zh":"很快改變意思是在短時間內變得不同。"},{"en":"The meal plan changed quickly when the writer discovered tofu and chickpeas.","zh":"當作者發現豆腐和鷹嘴豆後，膳食計劃很快改變。"},{"en":"A small mental shift can make practical changes happen faster.","zh":"小小心理轉變可以令實際改變更快發生。"},{"en":"The week shows that habits may change quickly when people experiment honestly.","zh":"這一星期顯示，只要人誠實實驗，習慣可以很快改變。"}],"source":"2025 Q5.pdf","sourcePage":6},{"front":"tomato-and-mushroom pasta","meaning":"番茄蘑菇意粉","examples":[{"en":"I tried a tomato-and-mushroom pasta on Tuesday.","zh":"星期二，我試了番茄蘑菇意粉。"},{"en":"Tomato-and-mushroom pasta is a pasta dish made with tomatoes and mushrooms instead of meat.","zh":"番茄蘑菇意粉是用番茄和蘑菇而不是肉類製成的意粉。"},{"en":"The dish can be colourful, simple, and filling.","zh":"這道菜可以色彩豐富、簡單又飽肚。"},{"en":"Trying this pasta helps the writer see vegetarian food as enjoyable.","zh":"嘗試這道意粉幫助作者把素食看成享受。"},{"en":"A familiar dish becomes new when meat is replaced with vegetables.","zh":"當肉被蔬菜取代，熟悉菜式也會變得新鮮。"}],"source":"2025 Q5.pdf","sourcePage":6},{"front":"tofu rice bowl","meaning":"豆腐飯碗","examples":[{"en":"I tried a tofu rice bowl on Wednesday.","zh":"星期三，我試了豆腐飯碗。"},{"en":"A tofu rice bowl is a meal with rice, tofu, and other vegetables or sauces in one bowl.","zh":"豆腐飯碗是一碗包含米飯、豆腐和其他蔬菜或醬汁的膳食。"},{"en":"A tofu rice bowl can be quick to prepare after school.","zh":"豆腐飯碗可以在放學後快速準備。"},{"en":"It gives the writer a satisfying alternative to meat-based rice dishes.","zh":"它給作者一個令人滿足的肉類飯碗替代選擇。"},{"en":"This dish shows that vegetarian meals can be practical and filling.","zh":"這道菜顯示素食膳食可以實際又飽肚。"}],"source":"2025 Q5.pdf","sourcePage":6},{"front":"chickpea curry","meaning":"鷹嘴豆咖喱","examples":[{"en":"I tried a chickpea curry on Thursday.","zh":"星期四，我試了鷹嘴豆咖喱。"},{"en":"Chickpea curry is a curry dish made with chickpeas, spices, and sauce.","zh":"鷹嘴豆咖喱是用鷹嘴豆、香料和醬汁製成的咖喱菜式。"},{"en":"Chickpeas can make curry filling because they contain protein and fibre.","zh":"鷹嘴豆含有蛋白質和纖維，所以可以令咖喱飽肚。"},{"en":"A chickpea curry may satisfy someone who worries vegetarian food is too light.","zh":"鷹嘴豆咖喱可能令擔心素食太清淡的人感到滿足。"},{"en":"This dish helps the writer discover that meat is not needed for a rich meal.","zh":"這道菜幫助作者發現濃郁一餐不一定需要肉。"}],"source":"2025 Q5.pdf","sourcePage":6},{"front":"to my surprise","meaning":"令我驚訝的是","examples":[{"en":"To my surprise, none of these meals felt like a sacrifice.","zh":"令我驚訝的是，這些素食餐沒有一餐感覺像犧牲。"},{"en":"To my surprise means unexpectedly or contrary to what I expected.","zh":"令我驚訝的是意思是出乎我的預期。"},{"en":"To my surprise, the vegetarian burger was more filling than I thought.","zh":"令我驚訝的是，素食漢堡比我想像中更飽肚。"},{"en":"This phrase shows that the writer’s old assumptions were challenged.","zh":"這個短語顯示作者的舊假設受到挑戰。"},{"en":"Surprise makes the experiment more persuasive because it comes from experience.","zh":"驚訝令實驗更有說服力，因為它來自親身經驗。"}],"source":"2025 Q5.pdf","sourcePage":6},{"front":"felt like a sacrifice","meaning":"感覺像犧牲","examples":[{"en":"None of these vegetarian meals felt like a sacrifice.","zh":"這些素食餐沒有一餐感覺像犧牲。"},{"en":"Felt like a sacrifice means seemed like giving up something valuable or enjoyable.","zh":"感覺像犧牲意思是似乎放棄了有價值或令人享受的東西。"},{"en":"A healthy meal does not feel like a sacrifice if it is tasty and satisfying.","zh":"如果健康膳食美味又令人滿足，它就不會感覺像犧牲。"},{"en":"The writer expected loss, but the meals gave colour and fullness.","zh":"作者原本預期失去，但膳食給了他色彩和飽足感。"},{"en":"The phrase shows that vegetarian food can feel positive, not punishing.","zh":"這個短語顯示素食可以感覺正面，而不是懲罰。"}],"source":"2025 Q5.pdf","sourcePage":7},{"front":"in fact","meaning":"事實上","examples":[{"en":"In fact, the meals were colourful and filling.","zh":"事實上，這些膳食色彩豐富又飽肚。"},{"en":"In fact introduces a truth that supports or corrects the previous idea.","zh":"事實上用來引出支持或糾正前一想法的真相。"},{"en":"I expected the soup to be weak; in fact, it was rich and satisfying.","zh":"我原以為湯會很淡；事實上，它濃郁又令人滿足。"},{"en":"This phrase helps the writer replace fear with evidence.","zh":"這個短語幫助作者用證據取代恐懼。"},{"en":"In fact, vegetarian meals can be fuller than people imagine.","zh":"事實上，素食膳食可以比人們想像中更飽足。"}],"source":"2025 Q5.pdf","sourcePage":7},{"front":"colourful, filling and satisfying","meaning":"色彩豐富、飽肚而令人滿足","examples":[{"en":"The meals were colourful, filling and satisfying.","zh":"這些膳食色彩豐富、飽肚而令人滿足。"},{"en":"Colourful, filling and satisfying means visually varied, able to make one full, and enjoyable.","zh":"色彩豐富、飽肚而令人滿足，意思是外觀多元、能令人飽足，而且令人享受。"},{"en":"A bowl with tofu, tomatoes, beans, and vegetables can be colourful and filling.","zh":"一碗有豆腐、番茄、豆類和蔬菜的飯可以色彩豐富又飽肚。"},{"en":"These qualities help vegetarian food feel attractive rather than limited.","zh":"這些特質令素食感覺吸引，而不是受限制。"},{"en":"The writer continues because the meals satisfy both body and mind.","zh":"作者繼續下去，因為這些膳食同時滿足身體和心靈。"}],"source":"2025 Q5.pdf","sourcePage":7},{"front":"filling","meaning":"飽肚的","examples":[{"en":"The vegetarian meals were filling.","zh":"這些素食餐很飽肚。"},{"en":"Filling means making someone feel full after eating.","zh":"飽肚的意思是吃完後令人感到飽足。"},{"en":"Beans, tofu, pasta, and potatoes can make vegetarian meals filling.","zh":"豆類、豆腐、意粉和薯仔可以令素食膳食很飽肚。"},{"en":"A filling lunch helps students stay focused in the afternoon.","zh":"飽肚的午餐幫助學生在下午保持專注。"},{"en":"The writer learns that meat is not the only food that can be filling.","zh":"作者學到肉不是唯一可以令人飽肚的食物。"}],"source":"2025 Q5.pdf","sourcePage":7},{"front":"satisfying","meaning":"令人滿足的","examples":[{"en":"The meals were satisfying.","zh":"這些膳食令人滿足。"},{"en":"Satisfying means giving a pleasant feeling of fullness, enjoyment, or completion.","zh":"令人滿足的意思是帶來飽足、享受或完整的愉快感覺。"},{"en":"A warm chickpea curry can be satisfying after a long school day.","zh":"漫長上學日後，一份熱鷹嘴豆咖喱可以令人滿足。"},{"en":"Food is satisfying when it meets both hunger and taste.","zh":"當食物同時滿足飢餓和味道需要時，它就是令人滿足的。"},{"en":"The writer’s meals become satisfying because they are planned with care.","zh":"作者的膳食因為被用心安排而變得令人滿足。"}],"source":"2025 Q5.pdf","sourcePage":7},{"front":"by the middle of the week","meaning":"到一星期中段時","examples":[{"en":"By the middle of the week, I no longer felt limited.","zh":"到一星期中段時，我不再感到受限制。"},{"en":"By the middle of the week means around Wednesday or halfway through the week.","zh":"到一星期中段時意思是大約星期三或一星期進行到一半時。"},{"en":"By the middle of the week, the writer had already tried several vegetarian meals.","zh":"到一星期中段時，作者已經試過幾款素食餐。"},{"en":"This phrase shows progress happening before the experiment ends.","zh":"這個短語顯示進步在實驗結束前已經發生。"},{"en":"Halfway through, the challenge begins to feel possible instead of restrictive.","zh":"到中段時，挑戰開始感覺可行，而不是限制。"}],"source":"2025 Q5.pdf","sourcePage":7},{"front":"no longer asked","meaning":"不再問","examples":[{"en":"By the middle of the week, I no longer asked what I could eat without meat.","zh":"到一星期中段時，我不再問沒有肉可以吃甚麼。"},{"en":"No longer asked means stopped asking something that used to be a concern.","zh":"不再問意思是停止提出以前擔心的問題。"},{"en":"After learning several recipes, he no longer asked whether vegetarian food could be filling.","zh":"學會幾個食譜後，他不再問素食是否可以飽肚。"},{"en":"This change shows growing confidence and imagination.","zh":"這種改變顯示信心和想像力增加。"},{"en":"The writer stops focusing on what is missing and starts noticing what is possible.","zh":"作者不再專注於缺少甚麼，而是開始注意可能性。"}],"source":"2025 Q5.pdf","sourcePage":7},{"front":"vegetarian dish","meaning":"素食菜式","examples":[{"en":"I began asking what interesting vegetarian dish I could make.","zh":"我開始問自己可以做甚麼有趣的素食菜式。"},{"en":"A vegetarian dish is a meal or part of a meal that does not contain meat.","zh":"素食菜式是不含肉類的一餐或一部分膳食。"},{"en":"Tofu rice bowls, mushroom pasta, and chickpea curry are vegetarian dishes.","zh":"豆腐飯碗、蘑菇意粉和鷹嘴豆咖喱都是素食菜式。"},{"en":"A good vegetarian dish can be colourful, nutritious, and satisfying.","zh":"好的素食菜式可以色彩豐富、有營養又令人滿足。"},{"en":"The writer begins to see vegetarian dishes as creative options.","zh":"作者開始把素食菜式看成有創意的選擇。"}],"source":"2025 Q5.pdf","sourcePage":7},{"front":"shift from limitation to possibility","meaning":"從限制轉向可能性","examples":[{"en":"The shift from limitation to possibility showed that the experiment was working.","zh":"從限制轉向可能性顯示這個實驗正在發揮作用。"},{"en":"A shift from limitation to possibility means changing from seeing restrictions to seeing options.","zh":"從限制轉向可能性意思是由看見限制，轉為看見選項。"},{"en":"The writer first saw no meat as a problem, then saw it as a chance to create new meals.","zh":"作者一開始把沒有肉視為問題，後來把它看成創造新膳食的機會。"},{"en":"This mental shift matters more than any single recipe.","zh":"這種心理轉變比任何單一食譜更重要。"},{"en":"The experiment works because it changes the writer’s imagination.","zh":"這個實驗成功，是因為它改變了作者的想像力。"}],"source":"2025 Q5.pdf","sourcePage":7},{"front":"limitation","meaning":"限制","examples":[{"en":"Vegetarian food no longer felt like a limitation.","zh":"素食不再感覺像限制。"},{"en":"Limitation means a restriction or something that seems to reduce choice.","zh":"限制意思是約束，或似乎減少選擇的東西。"},{"en":"At first, the writer saw no meat as a limitation.","zh":"起初，作者把沒有肉視為限制。"},{"en":"A limitation can become less frightening when people discover alternatives.","zh":"當人發現替代選擇時，限制可以變得不那麼可怕。"},{"en":"The challenge turns limitation into creativity.","zh":"這個挑戰把限制轉化為創意。"}],"source":"2025 Q5.pdf","sourcePage":7},{"front":"possibility","meaning":"可能性","examples":[{"en":"The experiment opened up a sense of possibility.","zh":"這個實驗打開了一種可能性。"},{"en":"Possibility means something that can happen or a new option that can be tried.","zh":"可能性意思是可能發生的事情，或可以嘗試的新選項。"},{"en":"A full fridge of vegetables becomes a place of possibility when the writer thinks differently.","zh":"當作者換個方式思考時，充滿蔬菜的雪櫃變成充滿可能性的地方。"},{"en":"Possibility grows when people stop depending on one default option.","zh":"當人停止依賴單一預設選項，可能性就會增加。"},{"en":"Vegetarian cooking gives the writer a new sense of possibility.","zh":"素食烹調給作者新的可能性感覺。"}],"source":"2025 Q5.pdf","sourcePage":8},{"front":"the first sign that","meaning":"……的第一個跡象","examples":[{"en":"That shift was the first sign that the experiment was working.","zh":"那個轉變是實驗正在發揮作用的第一個跡象。"},{"en":"The first sign that means the earliest evidence showing something is true.","zh":"……的第一個跡象意思是最早顯示某事真實的證據。"},{"en":"Feeling less limited was the first sign that the new habit could last.","zh":"感到較少受限制，是新習慣可能持續的第一個跡象。"},{"en":"Early signs can encourage people to continue a difficult change.","zh":"早期跡象可以鼓勵人繼續困難改變。"},{"en":"For the writer, curiosity about vegetarian dishes is the first sign of success.","zh":"對作者來說，對素食菜式產生好奇是成功的第一個跡象。"}],"source":"2025 Q5.pdf","sourcePage":8},{"front":"physically better","meaning":"身體上感覺更好","examples":[{"en":"The week made me feel physically better.","zh":"這一星期令我身體上感覺更好。"},{"en":"Physically better means healthier or more comfortable in the body.","zh":"身體上感覺更好意思是身體更健康或更舒服。"},{"en":"A person may feel physically better after eating lighter lunches and sleeping well.","zh":"一個人吃較清爽午餐並睡得好後，可能身體上感覺更好。"},{"en":"The writer notices improved energy and digestion during the week.","zh":"作者在這一星期注意到精力和消化改善。"},{"en":"Feeling physically better supports his decision to continue.","zh":"身體上感覺更好支持了他繼續下去的決定。"}],"source":"2025 Q5.pdf","sourcePage":8},{"front":"I am not claiming that","meaning":"我並不是聲稱","examples":[{"en":"I am not claiming that I became a super-athlete.","zh":"我並不是聲稱自己變成了超級運動員。"},{"en":"I am not claiming that means I am not saying something extreme or exaggerated is true.","zh":"我並不是聲稱某事，意思是我不是說某個極端或誇張說法是真的。"},{"en":"I am not claiming that one week can solve every health problem.","zh":"我並不是聲稱一星期可以解決所有健康問題。"},{"en":"This phrase makes the argument sound honest and moderate.","zh":"這個短語令論點聽起來誠實而適度。"},{"en":"The writer admits limits while still describing real benefits.","zh":"作者承認限制，同時仍描述真實好處。"}],"source":"2025 Q5.pdf","sourcePage":8},{"front":"transformed into","meaning":"變成","examples":[{"en":"I did not transform into a super-athlete within seven days.","zh":"我沒有在七日之內變成超級運動員。"},{"en":"To transform into something means to change completely into a different state or person.","zh":"變成某物意思是完全改變成另一種狀態或人物。"},{"en":"A person does not transform into a health expert after cooking one vegetarian meal.","zh":"一個人不會煮了一餐素食就變成健康專家。"},{"en":"Transformation usually takes time, repetition, and commitment.","zh":"轉變通常需要時間、重複和承諾。"},{"en":"The writer does not exaggerate; he describes noticeable but realistic change.","zh":"作者沒有誇張；他描述的是明顯但現實的改變。"}],"source":"2025 Q5.pdf","sourcePage":8},{"front":"super-athlete","meaning":"超級運動員","examples":[{"en":"I am not claiming that I became a super-athlete.","zh":"我並不是聲稱自己變成了超級運動員。"},{"en":"A super-athlete is an extremely fit or powerful sports performer.","zh":"超級運動員是極度健壯或能力很強的運動表現者。"},{"en":"Eating vegetarian for one week will not turn someone into a super-athlete.","zh":"吃素一星期不會把人變成超級運動員。"},{"en":"The phrase is humorous because it rejects an exaggerated health claim.","zh":"這個短語帶點幽默，因為它否定誇張的健康說法。"},{"en":"The writer wants to sound realistic, not magical.","zh":"作者想聽起來現實，而不是像魔法一樣。"}],"source":"2025 Q5.pdf","sourcePage":8},{"front":"within seven days","meaning":"七日之內","examples":[{"en":"The change happened within seven days.","zh":"改變在七日之內發生。"},{"en":"Within seven days means before the end of a one-week period.","zh":"七日之內意思是在一星期結束之前。"},{"en":"Within seven days, the writer noticed more energy after lunch.","zh":"七日之內，作者注意到午飯後更有精神。"},{"en":"Some habits can begin to shift within seven days, even if deeper change takes longer.","zh":"有些習慣可以在七日之內開始轉變，即使更深改變需要更長時間。"},{"en":"The phrase shows the change was quick but still limited.","zh":"這個短語顯示改變很快，但仍有限度。"}],"source":"2025 Q5.pdf","sourcePage":8},{"front":"the difference was noticeable","meaning":"差別很明顯","examples":[{"en":"The difference in my energy level was noticeable.","zh":"我的精力水平差別很明顯。"},{"en":"The difference was noticeable means the change could be clearly felt or seen.","zh":"差別很明顯意思是改變可以清楚感覺到或看見。"},{"en":"After lighter lunches, the writer’s afternoon energy became noticeable.","zh":"吃較清爽午餐後，作者下午的精力差別變得明顯。"},{"en":"Noticeable changes encourage people to continue new habits.","zh":"明顯改變會鼓勵人繼續新習慣。"},{"en":"The writer does not claim perfection, only a real difference he could feel.","zh":"作者不是聲稱完美，只是說出自己能感受到的真實差別。"}],"source":"2025 Q5.pdf","sourcePage":8},{"front":"sleepy and heavy","meaning":"昏昏欲睡而身體沉重","examples":[{"en":"After lunch, I usually feel sleepy and heavy.","zh":"午飯後，我通常感到昏昏欲睡而身體沉重。"},{"en":"Sleepy and heavy means tired, slow, and physically weighed down.","zh":"昏昏欲睡而身體沉重意思是疲倦、遲鈍，身體像被壓住。"},{"en":"A large oily meal may make a student feel sleepy and heavy in class.","zh":"一頓大型油膩餐可能令學生在課堂上昏昏欲睡而身體沉重。"},{"en":"This feeling can reduce concentration during the afternoon.","zh":"這種感覺會降低下午的專注力。"},{"en":"The vegetarian week helps the writer feel lighter instead.","zh":"素食一星期反而幫助作者感到更輕盈。"}],"source":"2025 Q5.pdf","sourcePage":8},{"front":"especially if","meaning":"尤其是如果","examples":[{"en":"I feel sleepy, especially if I have eaten fried meat.","zh":"我會感到昏昏欲睡，尤其是如果我吃了油炸肉類。"},{"en":"Especially if means particularly when a certain condition is true.","zh":"尤其是如果意思是特別在某條件成立時。"},{"en":"Students may feel tired after lunch, especially if the meal is oily.","zh":"學生午飯後可能感到疲倦，尤其是如果那餐很油膩。"},{"en":"This phrase highlights the condition that makes a problem stronger.","zh":"這個短語強調令問題更嚴重的條件。"},{"en":"For the writer, fried meat often makes afternoon tiredness worse.","zh":"對作者來說，油炸肉類常令下午疲倦更嚴重。"}],"source":"2025 Q5.pdf","sourcePage":8},{"front":"fried meat","meaning":"油炸肉類","examples":[{"en":"Fried meat often made me feel heavy after lunch.","zh":"油炸肉類常令我午飯後感到身體沉重。"},{"en":"Fried meat is meat cooked in hot oil.","zh":"油炸肉類是用熱油煮熟的肉。"},{"en":"Fried chicken or pork cutlets may taste good but feel heavy afterwards.","zh":"炸雞或吉列豬扒可能好吃，但之後令人感到沉重。"},{"en":"The writer links fried meat with afternoon sleepiness.","zh":"作者把油炸肉類和下午昏睡感連繫起來。"},{"en":"Avoiding fried meat helps him notice a lighter feeling during the week.","zh":"避免油炸肉類幫助他在這星期注意到較輕盈的感覺。"}],"source":"2025 Q5.pdf","sourcePage":9},{"front":"takeaway meal","meaning":"外賣餐","examples":[{"en":"A large takeaway meal often made me sleepy.","zh":"一份大型外賣餐常令我昏昏欲睡。"},{"en":"A takeaway meal is food bought from a restaurant and eaten elsewhere.","zh":"外賣餐是從餐廳買走並在其他地方吃的食物。"},{"en":"Busy students may grab a takeaway meal when they have little time.","zh":"忙碌學生沒有太多時間時，可能隨手買外賣餐。"},{"en":"Large takeaway meals can be oily, salty, and heavier than planned meals.","zh":"大型外賣餐可能油膩、鹹，並比計劃好的膳食更沉重。"},{"en":"Planning vegetarian meals helps the writer avoid careless takeaway choices.","zh":"安排素食餐幫助作者避免粗心的外賣選擇。"}],"source":"2025 Q5.pdf","sourcePage":9},{"front":"felt lighter and more alert","meaning":"感覺更輕盈、更精神","examples":[{"en":"During my vegetarian week, I felt lighter and more alert.","zh":"在素食一星期期間，我感覺更輕盈、更精神。"},{"en":"Felt lighter and more alert means felt less heavy and more awake or focused.","zh":"感覺更輕盈、更精神意思是身體不那麼沉重，並更清醒或專注。"},{"en":"After a balanced lunch, a student may feel lighter and more alert in class.","zh":"吃過均衡午餐後，學生在課堂上可能感覺更輕盈、更精神。"},{"en":"The writer connects this feeling with eating more vegetables, beans, and fruit.","zh":"作者把這種感覺與吃更多蔬菜、豆類和水果連繫起來。"},{"en":"Feeling alert helps him see vegetarianism as practical, not restrictive.","zh":"感到更精神幫助他把素食看成實際，而不是限制。"}],"source":"2025 Q5.pdf","sourcePage":9},{"front":"more alert","meaning":"更精神；更清醒","examples":[{"en":"I felt more alert in the afternoon.","zh":"我在下午感覺更精神。"},{"en":"More alert means more awake, focused, and ready to respond.","zh":"更精神或更清醒意思是更醒目、更專注，並更能反應。"},{"en":"A person may feel more alert after eating a lighter lunch.","zh":"一個人吃較清爽午餐後可能感覺更清醒。"},{"en":"Being alert helps students learn better and make fewer mistakes.","zh":"保持清醒幫助學生學得更好，也少犯錯。"},{"en":"The writer’s increased alertness becomes one benefit of the vegetarian week.","zh":"作者增加的精神成為素食一星期的一個好處。"}],"source":"2025 Q5.pdf","sourcePage":9},{"front":"in the afternoon","meaning":"在下午","examples":[{"en":"I felt lighter and more alert in the afternoon.","zh":"我在下午感覺更輕盈、更清醒。"},{"en":"In the afternoon means during the time after lunch and before evening.","zh":"在下午意思是午飯後到傍晚前的時間。"},{"en":"Many students lose energy in the afternoon after a heavy lunch.","zh":"許多學生吃過沉重午餐後，在下午會失去精力。"},{"en":"The writer notices that his afternoon energy changes during the experiment.","zh":"作者注意到實驗期間自己的下午精力改變。"},{"en":"Better afternoon focus makes the new diet feel worthwhile.","zh":"更好的下午專注力令新飲食感覺值得。"}],"source":"2025 Q5.pdf","sourcePage":9},{"front":"plan my meals more carefully","meaning":"更仔細地安排膳食","examples":[{"en":"I had to plan my meals more carefully.","zh":"我必須更仔細地安排膳食。"},{"en":"To plan meals more carefully means to think ahead about ingredients, nutrition, and timing.","zh":"更仔細地安排膳食意思是預先思考食材、營養和時間。"},{"en":"A vegetarian student may plan meals more carefully to include enough protein and fibre.","zh":"素食學生可能更仔細地安排膳食，以攝取足夠蛋白質和纖維。"},{"en":"Careful planning prevents people from grabbing unhealthy food in a hurry.","zh":"仔細安排可以防止人匆忙隨手買不健康食物。"},{"en":"The writer’s better planning leads to healthier meals.","zh":"作者更好的安排帶來更健康膳食。"}],"source":"2025 Q5.pdf","sourcePage":9},{"front":"ended up eating","meaning":"結果吃了","examples":[{"en":"I ended up eating more vegetables, beans and fruit than usual.","zh":"我結果吃了比平常更多蔬菜、豆類和水果。"},{"en":"Ended up eating means finally ate as a result, sometimes unexpectedly.","zh":"結果吃了意思是最後因某情況而吃了某些東西，有時出乎意料。"},{"en":"After planning lunches, a student may end up eating healthier food than before.","zh":"安排午餐後，學生結果可能比以前吃得更健康。"},{"en":"The writer did not simply avoid meat; he ended up adding better foods.","zh":"作者不只是避開肉類；他結果加入了更好的食物。"},{"en":"This result shows that vegetarianism changed the whole plate.","zh":"這個結果顯示素食改變了整個餐盤。"}],"source":"2025 Q5.pdf","sourcePage":9},{"front":"beans and fruit","meaning":"豆類和水果","examples":[{"en":"I ate more vegetables, beans and fruit than usual.","zh":"我吃了比平常更多蔬菜、豆類和水果。"},{"en":"Beans and fruit are plant-based foods that can add fibre, nutrients, and variety.","zh":"豆類和水果是植物性食物，可以增加纖維、營養和變化。"},{"en":"Beans can make meals filling, while fruit can provide freshness and sweetness.","zh":"豆類可以令膳食飽肚，而水果可以提供清新感和甜味。"},{"en":"Eating more beans and fruit helps replace careless meat-based choices.","zh":"吃更多豆類和水果有助取代粗心的肉類選擇。"},{"en":"The writer’s vegetarian week becomes healthier because his plate becomes more varied.","zh":"作者的素食一星期因餐盤更多元而變得更健康。"}],"source":"2025 Q5.pdf","sourcePage":9},{"front":"than usual","meaning":"比平常","examples":[{"en":"I ate more vegetables than usual.","zh":"我吃了比平常更多蔬菜。"},{"en":"Than usual means compared with what normally happens.","zh":"比平常意思是與通常情況相比。"},{"en":"During the experiment, the writer cooked at home more often than usual.","zh":"實驗期間，作者比平常更常在家煮食。"},{"en":"This phrase helps show a change from normal habits.","zh":"這個短語幫助顯示與平常習慣不同的改變。"},{"en":"Eating more vegetables than usual becomes one sign of improved nutrition.","zh":"比平常吃更多蔬菜，成為營養改善的一個跡象。"}],"source":"2025 Q5.pdf","sourcePage":9},{"front":"instead of grabbing","meaning":"而不是隨手買","examples":[{"en":"Instead of grabbing a quick burger, I chose healthier meals.","zh":"我選擇較健康的膳食，而不是隨手買一個快餐漢堡。"},{"en":"Instead of grabbing means rather than quickly buying or taking something without much thought.","zh":"而不是隨手買意思是不是快速而不多想地購買或拿取某物。"},{"en":"Instead of grabbing fried food, a student may prepare a tofu rice bowl.","zh":"學生可以準備豆腐飯碗，而不是隨手買油炸食物。"},{"en":"This phrase contrasts careless convenience with thoughtful choice.","zh":"這個短語把粗心方便和深思熟慮的選擇作對比。"},{"en":"The writer learns to pause before choosing the easiest option.","zh":"作者學會在選擇最方便選項前先停一停。"}],"source":"2025 Q5.pdf","sourcePage":9},{"front":"a quick burger","meaning":"一個快餐漢堡","examples":[{"en":"Instead of grabbing a quick burger, I chose meals richer in fibre.","zh":"我選擇纖維較多的膳食，而不是隨手買一個快餐漢堡。"},{"en":"A quick burger is a fast, convenient burger bought when someone is in a hurry.","zh":"一個快餐漢堡是人在趕時間時快速買來吃的方便漢堡。"},{"en":"A quick burger may solve hunger but may not be the most balanced choice.","zh":"快餐漢堡可以解決飢餓，但未必是最均衡選擇。"},{"en":"The writer used to rely on quick food instead of planning meals.","zh":"作者以前依賴快捷食物，而不是安排膳食。"},{"en":"Avoiding a quick burger helps him choose food with more fibre and less oil.","zh":"避開快餐漢堡幫助他選擇更多纖維、較少油的食物。"}],"source":"2025 Q5.pdf","sourcePage":10},{"front":"naturally richer in fibre","meaning":"天然含較多纖維","examples":[{"en":"The meals were naturally richer in fibre.","zh":"這些膳食天然含較多纖維。"},{"en":"Naturally richer in fibre means containing more fibre because of the ingredients, not because of artificial changes.","zh":"天然含較多纖維意思是因食材本身而含有更多纖維，而不是人工改變。"},{"en":"Meals with beans, vegetables, and fruit are often naturally richer in fibre.","zh":"含豆類、蔬菜和水果的膳食通常天然含較多纖維。"},{"en":"Fibre-rich meals can help digestion and fullness.","zh":"高纖膳食可以幫助消化和飽足感。"},{"en":"The writer feels better partly because his vegetarian meals contain more plant foods.","zh":"作者感覺更好，部分原因是他的素食餐含更多植物性食物。"}],"source":"2025 Q5.pdf","sourcePage":10},{"front":"fibre","meaning":"纖維","examples":[{"en":"Vegetarian meals are often richer in fibre.","zh":"素食膳食通常含有較多纖維。"},{"en":"Fibre is a part of plant foods that helps digestion and fullness.","zh":"纖維是植物性食物中的一部分，有助消化和飽足感。"},{"en":"Beans, vegetables, fruit, and whole grains can provide fibre.","zh":"豆類、蔬菜、水果和全穀物都可以提供纖維。"},{"en":"More fibre may help people feel less sluggish after meals.","zh":"更多纖維可能幫助人飯後較少感到遲鈍疲倦。"},{"en":"The writer’s fibre intake increases when he eats more plant-based food.","zh":"當作者吃更多植物性食物時，他的纖維攝取增加。"}],"source":"2025 Q5.pdf","sourcePage":10},{"front":"less oily","meaning":"較少油膩","examples":[{"en":"The vegetarian meals were less oily.","zh":"這些素食餐較少油膩。"},{"en":"Less oily means containing less oil or grease.","zh":"較少油膩意思是含較少油或油脂。"},{"en":"A steamed tofu dish may feel less oily than fried meat.","zh":"蒸豆腐菜式可能比油炸肉類較少油膩。"},{"en":"Less oily lunches can help people feel lighter in the afternoon.","zh":"較少油膩的午餐可以幫助人在下午感覺更輕盈。"},{"en":"The writer notices that less oily meals improve his comfort after eating.","zh":"作者注意到較少油膩的膳食改善了飯後舒適感。"}],"source":"2025 Q5.pdf","sourcePage":10},{"front":"as a result","meaning":"因此","examples":[{"en":"As a result, my digestion improved.","zh":"因此，我的消化改善了。"},{"en":"As a result means because of what happened before.","zh":"因此意思是由於之前發生的事情。"},{"en":"I ate more fibre; as a result, I felt less sluggish.","zh":"我吃了更多纖維；因此，我感覺較少疲倦遲鈍。"},{"en":"This phrase connects a cause with an effect.","zh":"這個短語把原因和結果連接起來。"},{"en":"The writer uses it to link better meal planning with physical improvement.","zh":"作者用它把更好的膳食安排和身體改善連繫起來。"}],"source":"2025 Q5.pdf","sourcePage":10},{"front":"digestion improved","meaning":"消化改善","examples":[{"en":"My digestion improved during the vegetarian week.","zh":"在素食一星期期間，我的消化改善了。"},{"en":"Digestion improved means the body processed food more comfortably or effectively.","zh":"消化改善意思是身體更舒服或更有效地處理食物。"},{"en":"Eating more fibre and less oily food may help digestion improve.","zh":"吃更多纖維和較少油膩食物可能有助消化改善。"},{"en":"Improved digestion can make a person feel lighter after meals.","zh":"消化改善可以令人飯後感覺更輕盈。"},{"en":"The writer sees digestion as one practical benefit of the experiment.","zh":"作者把消化改善視為實驗的一個實際好處。"}],"source":"2025 Q5.pdf","sourcePage":10},{"front":"less sluggish overall","meaning":"整體上較少疲倦遲鈍","examples":[{"en":"I felt less sluggish overall.","zh":"我整體上較少感到疲倦遲鈍。"},{"en":"Less sluggish overall means generally less slow, tired, or heavy.","zh":"整體上較少疲倦遲鈍意思是一般而言較不遲緩、疲倦或沉重。"},{"en":"After several lighter meals, a student may feel less sluggish during the day.","zh":"吃了幾餐較清爽膳食後，學生整天可能較少感到疲倦。"},{"en":"The phrase describes a broad improvement rather than one sudden miracle.","zh":"這個短語描述的是廣泛改善，而不是突然奇蹟。"},{"en":"Feeling less sluggish helps the writer believe the change is worth continuing.","zh":"較少感到遲鈍幫助作者相信這個改變值得繼續。"}],"source":"2025 Q5.pdf","sourcePage":10},{"front":"commented that","meaning":"評論說；表示","examples":[{"en":"My parents commented that I seemed energetic after school.","zh":"我的父母表示我放學後看起來很有活力。"},{"en":"Commented that means said or remarked that something appeared true.","zh":"評論說或表示意思是說出或提到某事看似真實。"},{"en":"A teacher commented that the student looked more focused than usual.","zh":"老師表示那位學生看起來比平常更專注。"},{"en":"Comments from others can confirm changes we feel ourselves.","zh":"他人的評論可以確認我們自己感受到的改變。"},{"en":"The parents’ comment supports the writer’s sense of improved energy.","zh":"父母的評論支持了作者精力改善的感受。"}],"source":"2025 Q5.pdf","sourcePage":10},{"front":"unusually energetic","meaning":"異常有活力","examples":[{"en":"My parents said I seemed unusually energetic after school.","zh":"我的父母說我放學後看起來異常有活力。"},{"en":"Unusually energetic means having more energy than expected or normal.","zh":"異常有活力意思是比預期或平常更有精力。"},{"en":"A student who usually naps after school may seem unusually energetic after a lighter lunch.","zh":"平時放學後午睡的學生，在吃較清爽午餐後可能顯得異常有活力。"},{"en":"This phrase shows that the change was noticeable to other people.","zh":"這個短語顯示改變明顯到其他人也注意到。"},{"en":"The writer’s energy surprises his parents because it differs from his usual pattern.","zh":"作者的精力令父母驚訝，因為它不同於他平常的模式。"}],"source":"2025 Q5.pdf","sourcePage":10},{"front":"after school","meaning":"放學後","examples":[{"en":"I seemed unusually energetic after school.","zh":"我放學後看起來異常有活力。"},{"en":"After school means after classes have finished for the day.","zh":"放學後意思是一天課堂結束之後。"},{"en":"Many students feel tired after school, especially after a heavy lunch.","zh":"許多學生放學後感到疲倦，尤其是吃過沉重午餐後。"},{"en":"Feeling energetic after school suggests the writer’s afternoon energy improved.","zh":"放學後仍有活力，暗示作者下午精力改善。"},{"en":"The phrase makes the health effect concrete in daily life.","zh":"這個短語把健康效果具體放在日常生活中。"}],"source":"2025 Q5.pdf","sourcePage":10},{"front":"made me realise that","meaning":"令我意識到","examples":[{"en":"This experience made me realise that vegetarianism is about nutrition.","zh":"這次經歷令我意識到素食主義關乎營養。"},{"en":"Made me realise that means caused me to understand something clearly.","zh":"令我意識到某事，意思是使我清楚明白某事。"},{"en":"Cooking for myself made me realise that planning matters.","zh":"自己煮食令我意識到規劃很重要。"},{"en":"The phrase shows a change in awareness after experience.","zh":"這個短語顯示經驗後的意識轉變。"},{"en":"The writer realises vegetarianism is not only about saying no to meat.","zh":"作者意識到素食主義不只是對肉說不。"}],"source":"2025 Q5.pdf","sourcePage":11},{"front":"not only about avoiding meat","meaning":"不只是關於避開肉類","examples":[{"en":"Vegetarianism is not only about avoiding meat.","zh":"素食主義不只是關於避開肉類。"},{"en":"Not only about avoiding meat means the idea includes more than simply not eating meat.","zh":"不只是關於避開肉類，意思是這個概念包括的不只是單純不吃肉。"},{"en":"Vegetarianism also involves nutrition, planning, and awareness.","zh":"素食主義也涉及營養、規劃和意識。"},{"en":"If people only avoid meat without balance, their diet may still be poor.","zh":"如果人只是避開肉類而沒有均衡飲食，他們的飲食仍可能很差。"},{"en":"The writer learns that good vegetarianism is active, not merely negative.","zh":"作者學到良好的素食是主動的，而不只是消極避開。"}],"source":"2025 Q5.pdf","sourcePage":11},{"front":"avoiding meat","meaning":"避開肉類","examples":[{"en":"Vegetarianism involves more than avoiding meat.","zh":"素食主義涉及的不只是避開肉類。"},{"en":"Avoiding meat means choosing not to eat meat products.","zh":"避開肉類意思是選擇不吃肉類產品。"},{"en":"A person avoiding meat may still need to plan protein, fibre, and vitamins carefully.","zh":"避開肉類的人仍可能需要仔細安排蛋白質、纖維和維他命。"},{"en":"Avoiding meat is only one part of a thoughtful vegetarian lifestyle.","zh":"避開肉類只是深思熟慮的素食生活方式其中一部分。"},{"en":"The writer moves from avoiding meat to building balanced meals.","zh":"作者由避開肉類，轉向建立均衡膳食。"}],"source":"2025 Q5.pdf","sourcePage":11},{"front":"becoming more deliberate about","meaning":"在……方面變得更有意識","examples":[{"en":"Vegetarianism is about becoming more deliberate about nutrition.","zh":"素食主義關乎在營養方面變得更有意識。"},{"en":"Becoming more deliberate about something means acting with more intention and careful thought.","zh":"在某方面變得更有意識，意思是更有目的和更仔細地行動。"},{"en":"A student becomes more deliberate about snacks when they plan fruit instead of crisps.","zh":"學生選擇水果而不是薯片時，就在小食方面變得更有意識。"},{"en":"Being deliberate helps people avoid automatic choices.","zh":"有意識地行動幫助人避免自動選擇。"},{"en":"The writer becomes more deliberate about what goes onto his plate.","zh":"作者對自己餐盤上放甚麼變得更有意識。"}],"source":"2025 Q5.pdf","sourcePage":11},{"front":"nutrition","meaning":"營養","examples":[{"en":"The experiment made me think more carefully about nutrition.","zh":"這個實驗令我更仔細思考營養。"},{"en":"Nutrition means the way food supports health through energy and nutrients.","zh":"營養是食物透過能量和養分支持健康的方式。"},{"en":"Beans, tofu, vegetables, and fruit can all be part of good nutrition.","zh":"豆類、豆腐、蔬菜和水果都可以成為良好營養的一部分。"},{"en":"Thinking about nutrition helps people build meals instead of just filling the stomach.","zh":"思考營養幫助人建立膳食，而不只是填飽肚子。"},{"en":"Vegetarianism becomes healthier when nutrition is planned carefully.","zh":"當營養被仔細安排時，素食主義會更健康。"}],"source":"2025 Q5.pdf","sourcePage":11},{"front":"stop relying on","meaning":"停止依賴","examples":[{"en":"People should stop relying on meat as the default option.","zh":"人們應停止依賴肉類作為預設選項。"},{"en":"To stop relying on something means to no longer depend on it automatically.","zh":"停止依賴某物意思是不再自動依靠它。"},{"en":"A student may stop relying on takeaway food by learning simple recipes.","zh":"學生學會簡單食譜後，可能停止依賴外賣。"},{"en":"Stopping reliance on meat opens space for beans, tofu, and vegetables.","zh":"停止依賴肉類，會為豆類、豆腐和蔬菜打開空間。"},{"en":"The writer stops relying on meat when he discovers other satisfying meals.","zh":"作者發現其他令人滿足的膳食後，就停止依賴肉類。"}],"source":"2025 Q5.pdf","sourcePage":11},{"front":"default option","meaning":"預設選項","examples":[{"en":"Meat had been my default option at meals.","zh":"肉類一直是我膳食中的預設選項。"},{"en":"A default option is the choice people make automatically unless they think differently.","zh":"預設選項是人在沒有換個方式思考時自動作出的選擇。"},{"en":"Ordering chicken rice may be a default option for someone who eats it every day.","zh":"對每天吃雞飯的人來說，點雞飯可能是預設選項。"},{"en":"Default options shape behaviour quietly because they feel normal.","zh":"預設選項因感覺正常而安靜地塑造行為。"},{"en":"The experiment helps the writer replace meat as his default option.","zh":"這個實驗幫助作者取代肉類作為預設選項。"}],"source":"2025 Q5.pdf","sourcePage":11},{"front":"pushed towards","meaning":"被推向","examples":[{"en":"Without meat, people are pushed towards a more balanced plate.","zh":"沒有肉時，人們會被推向更均衡的一餐。"},{"en":"Pushed towards means guided or forced in the direction of something.","zh":"被推向意思是被引導或迫使朝某個方向前進。"},{"en":"Removing meat pushed the writer towards beans, vegetables, and fruit.","zh":"去除肉類把作者推向豆類、蔬菜和水果。"},{"en":"Sometimes a restriction pushes people towards healthier creativity.","zh":"有時限制會把人推向更健康的創意。"},{"en":"The challenge pushes him away from habit and towards balance.","zh":"這個挑戰把他從習慣推向均衡。"}],"source":"2025 Q5.pdf","sourcePage":11},{"front":"a more balanced plate","meaning":"更均衡的一餐","examples":[{"en":"Vegetarian meals pushed me towards a more balanced plate.","zh":"素食餐把我推向更均衡的一餐。"},{"en":"A more balanced plate is a meal with a better mix of nutrients and food groups.","zh":"更均衡的一餐是營養和食物種類配搭更好的膳食。"},{"en":"A balanced plate may include vegetables, grains, protein, and fruit.","zh":"均衡一餐可能包括蔬菜、穀物、蛋白質和水果。"},{"en":"Meat-heavy meals may become less balanced if vegetables are ignored.","zh":"如果忽視蔬菜，以肉為主的膳食可能較不均衡。"},{"en":"The writer’s plate becomes more balanced when he adds beans, tofu, and vegetables.","zh":"當作者加入豆類、豆腐和蔬菜時，他的一餐變得更均衡。"}],"source":"2025 Q5.pdf","sourcePage":11},{"front":"the most powerful effect","meaning":"最強烈的影響","examples":[{"en":"The most powerful effect of the week was mental.","zh":"這一星期最強烈的影響是心理上的。"},{"en":"The most powerful effect means the strongest or most important result.","zh":"最強烈的影響意思是最有力或最重要的結果。"},{"en":"The most powerful effect of the challenge was not weight loss, but awareness.","zh":"這個挑戰最強烈的影響不是減重，而是意識。"},{"en":"Powerful effects can happen in thinking as much as in the body.","zh":"強烈影響可以發生在思想上，也可以發生在身體上。"},{"en":"The week changes the writer’s mind more deeply than he expected.","zh":"這一星期比作者預期更深地改變了他的想法。"}],"source":"2025 Q5.pdf","sourcePage":11},{"front":"mental rather than physical","meaning":"心理上而非身體上","examples":[{"en":"The most powerful effect was mental rather than physical.","zh":"最強烈的影響是心理上而非身體上。"},{"en":"Mental rather than physical means related to thoughts and attitudes more than the body.","zh":"心理上而非身體上意思是較關乎思想和態度，而不是身體。"},{"en":"The writer felt healthier, but the bigger change was how he understood food.","zh":"作者感到更健康，但更大的改變是他如何理解食物。"},{"en":"This phrase contrasts inner awareness with bodily feeling.","zh":"這個短語把內在意識和身體感覺作對比。"},{"en":"Vegetarianism changes his mind before it becomes a lasting lifestyle.","zh":"素食先改變他的思想，然後才成為持久生活方式。"}],"source":"2025 Q5.pdf","sourcePage":12},{"front":"even briefly","meaning":"即使只是短暫地","examples":[{"en":"Being vegetarian, even briefly, changed my thinking.","zh":"即使只是短暫地做素食者，也改變了我的想法。"},{"en":"Even briefly means even for a short time.","zh":"即使只是短暫地意思是即使只維持很短時間。"},{"en":"Trying a new habit even briefly can reveal hidden assumptions.","zh":"即使只是短暫地嘗試新習慣，也可以揭示隱藏假設。"},{"en":"A short experience can still be meaningful if it changes awareness.","zh":"如果短暫經歷改變意識，它仍可以有意義。"},{"en":"The writer’s brief vegetarian week has a lasting effect.","zh":"作者短暫的素食一星期帶來持久影響。"}],"source":"2025 Q5.pdf","sourcePage":12},{"front":"more aware of","meaning":"更意識到","examples":[{"en":"The week made me more aware of the consequences of my choices.","zh":"這一星期令我更意識到自己選擇的後果。"},{"en":"More aware of means better able to notice and understand something.","zh":"更意識到意思是更能注意和理解某事。"},{"en":"Reading about food production may make people more aware of environmental issues.","zh":"閱讀有關食物生產的內容，可能令人更意識到環境問題。"},{"en":"Awareness helps choices become deliberate rather than automatic.","zh":"意識幫助選擇變得有目的，而不是自動。"},{"en":"The writer becomes more aware of what each meal represents.","zh":"作者更意識到每一餐代表甚麼。"}],"source":"2025 Q5.pdf","sourcePage":12},{"front":"wider consequences","meaning":"更廣泛的後果","examples":[{"en":"Every meal has wider consequences.","zh":"每一餐都有更廣泛的後果。"},{"en":"Wider consequences are effects that go beyond the immediate situation.","zh":"更廣泛的後果是超越即時情況的影響。"},{"en":"A meal choice may affect health, animal welfare, and environmental resources.","zh":"一個膳食選擇可能影響健康、動物福利和環境資源。"},{"en":"Thinking about wider consequences makes eating feel more responsible.","zh":"思考更廣泛後果令進食感覺更有責任。"},{"en":"The writer learns that food choices reach beyond his own plate.","zh":"作者學到食物選擇超越自己的餐盤。"}],"source":"2025 Q5.pdf","sourcePage":12},{"front":"my choices","meaning":"我的選擇","examples":[{"en":"The experiment made me think about my choices.","zh":"這個實驗令我思考我的選擇。"},{"en":"My choices means the decisions I make in daily life.","zh":"我的選擇是指我在日常生活中作出的決定。"},{"en":"Choosing tofu instead of fried chicken is one of the writer’s choices.","zh":"選擇豆腐而不是炸雞，就是作者其中一個選擇。"},{"en":"Small choices can become powerful when repeated consistently.","zh":"小選擇若持續重複，可以變得有力量。"},{"en":"The experiment teaches the writer to own his choices instead of blaming habit.","zh":"這個實驗教作者承擔自己的選擇，而不是怪責習慣。"}],"source":"2025 Q5.pdf","sourcePage":12},{"front":"a quiet reminder","meaning":"默默的提醒","examples":[{"en":"Every meal became a quiet reminder.","zh":"每一餐都變成默默的提醒。"},{"en":"A quiet reminder is a gentle signal that makes someone remember something important.","zh":"默默的提醒是溫和地讓人記起重要事情的訊號。"},{"en":"A vegetable dish can become a quiet reminder of environmental responsibility.","zh":"蔬菜菜式可以成為環境責任的默默提醒。"},{"en":"Quiet reminders work because they appear in ordinary daily life.","zh":"默默提醒有效，因為它們出現在普通日常生活中。"},{"en":"For the writer, each meal quietly reminds him that food is never just food.","zh":"對作者來說，每一餐都默默提醒他食物從來不只是食物。"}],"source":"2025 Q5.pdf","sourcePage":12},{"front":"never just food","meaning":"從來不只是食物","examples":[{"en":"Food is never just food.","zh":"食物從來不只是食物。"},{"en":"Never just food means food always carries wider meanings and consequences.","zh":"從來不只是食物意思是食物總承載更廣泛的意義和後果。"},{"en":"A bowl of rice may connect to labour, resources, culture, and care.","zh":"一碗飯可能與勞力、資源、文化和關心有關。"},{"en":"This phrase makes a simple meal feel connected to larger issues.","zh":"這個短語令簡單一餐與更大議題連接起來。"},{"en":"The writer learns that eating is also a moral and environmental choice.","zh":"作者學到進食也是道德和環境選擇。"}],"source":"2025 Q5.pdf","sourcePage":12},{"front":"be linked to","meaning":"與……有關","examples":[{"en":"Food is linked to animal welfare and climate change.","zh":"食物與動物福利和氣候變化有關。"},{"en":"To be linked to something means to be connected with it.","zh":"與某事有關意思是與它有連繫。"},{"en":"Food choices are linked to health, cost, culture, and the environment.","zh":"食物選擇與健康、成本、文化和環境有關。"},{"en":"When people see these links, meals become more meaningful.","zh":"當人們看見這些連繫，膳食會變得更有意義。"},{"en":"The writer begins to notice what his diet is linked to beyond taste.","zh":"作者開始注意自己的飲食在味道以外還與甚麼有關。"}],"source":"2025 Q5.pdf","sourcePage":12},{"front":"animal welfare","meaning":"動物福利","examples":[{"en":"Food choices are linked to animal welfare.","zh":"食物選擇與動物福利有關。"},{"en":"Animal welfare means the health, comfort, and treatment of animals.","zh":"動物福利是指動物的健康、舒適和被對待方式。"},{"en":"People may eat less meat because they care about animal welfare.","zh":"人們可能因關心動物福利而少吃肉。"},{"en":"Thinking about animal welfare can make daily food choices more serious.","zh":"思考動物福利可以令日常食物選擇變得更嚴肅。"},{"en":"The writer’s vegetarian week makes this issue feel more personal.","zh":"作者的素食一星期令這個議題感覺更切身。"}],"source":"2025 Q5.pdf","sourcePage":12},{"front":"climate change","meaning":"氣候變化","examples":[{"en":"Food choices are linked to climate change.","zh":"食物選擇與氣候變化有關。"},{"en":"Climate change means long-term changes in global weather patterns and temperatures.","zh":"氣候變化是全球天氣模式和溫度的長期改變。"},{"en":"The writer thinks about climate change when he considers the resources behind meat production.","zh":"作者思考肉類生產背後的資源時，也想到氣候變化。"},{"en":"Climate issues can feel abstract until they connect with daily choices.","zh":"氣候議題可能感覺抽象，直到它們與日常選擇連接起來。"},{"en":"The experiment makes climate change feel closer to the dinner table.","zh":"這個實驗令氣候變化感覺更接近飯桌。"}],"source":"2025 Q5.pdf","sourcePage":12},{"front":"enormous resources","meaning":"大量資源","examples":[{"en":"Meat production can require enormous resources.","zh":"肉類生產可能需要大量資源。"},{"en":"Enormous resources means very large amounts of materials, energy, water, land, or labour.","zh":"大量資源意思是非常多的材料、能源、水、土地或勞力。"},{"en":"Producing food often requires resources that consumers do not see.","zh":"生產食物常需要消費者看不見的資源。"},{"en":"Thinking about enormous resources makes the writer value each meal more.","zh":"思考大量資源令作者更珍惜每一餐。"},{"en":"Eating less meat feels purposeful when he considers these hidden costs.","zh":"當他考慮這些隱藏成本，少吃肉就感覺有目的。"}],"source":"2025 Q5.pdf","sourcePage":13},{"front":"required to produce","meaning":"生產……所需","examples":[{"en":"Enormous resources are required to produce what we eat.","zh":"生產我們所吃的東西需要大量資源。"},{"en":"Required to produce means needed in order to make or create something.","zh":"生產某物所需，意思是製造或創造某物時需要的東西。"},{"en":"Water, land, feed, and energy may be required to produce food.","zh":"生產食物可能需要水、土地、飼料和能源。"},{"en":"The phrase reminds readers that meals do not appear without cost.","zh":"這個短語提醒讀者，膳食不會毫無成本地出現。"},{"en":"The writer becomes more careful when he thinks about what is required to produce food.","zh":"作者思考生產食物所需的東西時，變得更謹慎。"}],"source":"2025 Q5.pdf","sourcePage":13},{"front":"before this challenge","meaning":"在這次挑戰之前","examples":[{"en":"Before this challenge, environmental issues felt abstract.","zh":"在這次挑戰之前，環境議題感覺很抽象。"},{"en":"Before this challenge means before the vegetarian experiment began.","zh":"在這次挑戰之前意思是在素食實驗開始之前。"},{"en":"Before this challenge, the writer cared about the environment but felt distant from it.","zh":"在這次挑戰之前，作者關心環境，但感覺它離自己很遠。"},{"en":"The phrase marks the old way of thinking before personal experience changed it.","zh":"這個短語標示親身經歷改變之前的舊思維。"},{"en":"After the challenge, environmental issues become connected to daily meals.","zh":"挑戰之後，環境議題與每日膳食連接起來。"}],"source":"2025 Q5.pdf","sourcePage":13},{"front":"felt abstract","meaning":"感覺抽象","examples":[{"en":"Those issues had felt abstract to me.","zh":"那些議題以前對我來說感覺抽象。"},{"en":"Felt abstract means seemed distant, theoretical, or hard to connect with daily life.","zh":"感覺抽象意思是顯得遙遠、理論化，或難以與日常生活連接。"},{"en":"Climate change may feel abstract until people see how their choices contribute to it.","zh":"氣候變化可能感覺抽象，直到人們看見自己的選擇如何造成影響。"},{"en":"Abstract issues become clearer when linked to simple actions.","zh":"抽象議題與簡單行動連接後會變得更清楚。"},{"en":"The experiment turns broad concerns into personal decisions.","zh":"這個實驗把廣泛關注轉化為個人決定。"}],"source":"2025 Q5.pdf","sourcePage":13},{"front":"worthy of concern","meaning":"值得關注","examples":[{"en":"The issues seemed worthy of concern, but distant.","zh":"這些議題看似值得關注，但很遙遠。"},{"en":"Worthy of concern means deserving attention, care, or worry.","zh":"值得關注意思是值得注意、關心或擔憂。"},{"en":"Environmental harm is worthy of concern even when it feels far away.","zh":"即使環境傷害感覺遙遠，它仍然值得關注。"},{"en":"The writer knew the issues mattered before he felt personally involved.","zh":"作者在感到親身相關之前，已知道這些議題重要。"},{"en":"The challenge moves the issue from worthy of concern to part of daily choice.","zh":"這個挑戰把議題由值得關注，推向日常選擇的一部分。"}],"source":"2025 Q5.pdf","sourcePage":13},{"front":"distant","meaning":"遙遠的","examples":[{"en":"Those problems felt distant before the challenge.","zh":"在挑戰之前，那些問題感覺很遙遠。"},{"en":"Distant means far away physically, emotionally, or personally.","zh":"遙遠的意思是在身體上、情感上或個人關係上很遠。"},{"en":"A global problem can feel distant if it does not seem to affect daily life.","zh":"如果全球問題似乎不影響日常生活，它可以感覺很遙遠。"},{"en":"The vegetarian week makes distant issues feel closer.","zh":"素食一星期令遙遠議題感覺更貼近。"},{"en":"Food choices help the writer connect distant problems with his own actions.","zh":"食物選擇幫助作者把遙遠問題與自己的行動連接起來。"}],"source":"2025 Q5.pdf","sourcePage":13},{"front":"made them personal","meaning":"令它們變得切身","examples":[{"en":"This week made those issues personal.","zh":"這一星期令那些議題變得切身。"},{"en":"Made them personal means caused broad issues to feel connected to one’s own life.","zh":"令它們變得切身意思是令廣泛議題感覺與自己的生活有關。"},{"en":"Choosing a vegetable dish made environmental responsibility personal for the writer.","zh":"選擇蔬菜菜式令環境責任對作者變得切身。"},{"en":"Issues become personal when people see their role in them.","zh":"當人看見自己在議題中的角色，議題就會變得切身。"},{"en":"The experiment makes climate and animal welfare part of the writer’s everyday decisions.","zh":"這個實驗令氣候和動物福利成為作者日常決定的一部分。"}],"source":"2025 Q5.pdf","sourcePage":13},{"front":"each time","meaning":"每一次","examples":[{"en":"Each time I chose a vegetable dish, I felt purposeful.","zh":"每一次我選擇蔬菜菜式，我都感到有目的。"},{"en":"Each time means every occasion when something happens.","zh":"每一次意思是某事發生的每個時候。"},{"en":"Each time the writer avoided meat, he thought more carefully about his choice.","zh":"每一次作者避開肉類，他都更仔細思考自己的選擇。"},{"en":"Repeated small choices can create a stronger habit.","zh":"重複的小選擇可以建立更強的習慣。"},{"en":"Each time matters because the decision becomes less accidental.","zh":"每一次都重要，因為決定變得不再偶然。"}],"source":"2025 Q5.pdf","sourcePage":13},{"front":"chose a vegetable dish over a meat one","meaning":"選擇蔬菜菜式而非肉類菜式","examples":[{"en":"I chose a vegetable dish over a meat one.","zh":"我選擇蔬菜菜式而非肉類菜式。"},{"en":"To choose one thing over another means to prefer and select it instead of the other option.","zh":"選擇一物而非另一物，意思是偏好並選取前者，而不是後者。"},{"en":"A student may choose tofu curry over fried chicken for lunch.","zh":"學生午餐可能選擇豆腐咖喱，而非炸雞。"},{"en":"Choosing vegetables over meat can feel small but meaningful.","zh":"選擇蔬菜而非肉類可以感覺細小但有意義。"},{"en":"The writer’s repeated choices build a new sense of purpose.","zh":"作者重複的選擇建立了新的目的感。"}],"source":"2025 Q5.pdf","sourcePage":13},{"front":"small but meaningful decision","meaning":"細小但有意義的決定","examples":[{"en":"Each vegetarian meal felt like a small but meaningful decision.","zh":"每一餐素食都感覺像細小但有意義的決定。"},{"en":"A small but meaningful decision is a minor choice that still carries value or purpose.","zh":"細小但有意義的決定是看似小但仍有價值或目的的選擇。"},{"en":"Bringing a reusable bottle is a small but meaningful decision.","zh":"帶可重用水樽是一個細小但有意義的決定。"},{"en":"Small choices become meaningful when they match a person’s values.","zh":"當小選擇配合個人價值，它們就變得有意義。"},{"en":"The writer learns that everyday meals can carry responsibility.","zh":"作者學到日常膳食可以承載責任。"}],"source":"2025 Q5.pdf","sourcePage":13},{"front":"rather than merely","meaning":"而不是只是","examples":[{"en":"I was making a decision rather than merely following a trend.","zh":"我是在作出決定，而不是只是跟風。"},{"en":"Rather than merely means instead of only doing something shallow or simple.","zh":"而不是只是意思是不是只做某種膚淺或簡單的事情。"},{"en":"The writer wants to eat thoughtfully rather than merely copy fashionable habits.","zh":"作者想有思考地進食，而不是只是模仿時髦習慣。"},{"en":"This phrase contrasts real purpose with empty imitation.","zh":"這個短語把真正目的和空洞模仿作對比。"},{"en":"Vegetarianism becomes meaningful when it is chosen consciously.","zh":"當素食被有意識地選擇，它就變得有意義。"}],"source":"2025 Q5.pdf","sourcePage":14},{"front":"following a trend","meaning":"跟風","examples":[{"en":"I did not want to be merely following a trend.","zh":"我不想只是跟風。"},{"en":"Following a trend means doing something mainly because it is popular.","zh":"跟風意思是主要因某事流行而跟著做。"},{"en":"A person may follow a trend without understanding its deeper reasons.","zh":"一個人可能在不理解深層原因下跟風。"},{"en":"The writer wants vegetarianism to be a thoughtful choice, not fashion.","zh":"作者希望素食是深思熟慮的選擇，而不是潮流。"},{"en":"Experience helps him move beyond following a trend.","zh":"經驗幫助他超越跟風。"}],"source":"2025 Q5.pdf","sourcePage":14},{"front":"argue that","meaning":"認為；主張","examples":[{"en":"Some people may argue that one person’s diet makes no difference.","zh":"有些人可能認為一個人的飲食沒有真正分別。"},{"en":"To argue that means to claim something and give reasons for it.","zh":"認為或主張某事，意思是提出某個說法並給予理由。"},{"en":"Critics may argue that individual action is too small to matter.","zh":"批評者可能認為個人行動太小，沒有重要性。"},{"en":"The writer answers this argument by pointing to collective impact.","zh":"作者透過指出集體影響來回應這個論點。"},{"en":"This phrase introduces an opposing view fairly.","zh":"這個短語公平地引出反方觀點。"}],"source":"2025 Q5.pdf","sourcePage":14},{"front":"makes no real difference","meaning":"沒有真正分別","examples":[{"en":"Some people think one person’s diet makes no real difference.","zh":"有些人認為一個人的飲食沒有真正分別。"},{"en":"Makes no real difference means has no meaningful effect.","zh":"沒有真正分別意思是沒有有意義的影響。"},{"en":"A person may feel their recycling makes no real difference if others do not join.","zh":"如果其他人不參與，一個人可能覺得自己回收沒有真正分別。"},{"en":"The writer disagrees because many small choices can add up.","zh":"作者不同意，因為許多小選擇可以累積起來。"},{"en":"One choice may seem small, but repeated choices can matter.","zh":"一個選擇可能看似微小，但重複的選擇可以重要。"}],"source":"2025 Q5.pdf","sourcePage":14},{"front":"social change","meaning":"社會改變","examples":[{"en":"Social change rarely begins with grand gestures.","zh":"社會改變很少始於大動作。"},{"en":"Social change means a shift in how people in society think, behave, or organise life.","zh":"社會改變是社會中人們思想、行為或生活組織方式的轉變。"},{"en":"Eating less meat can be part of social change if many people do it consistently.","zh":"如果許多人持續少吃肉，這可以成為社會改變的一部分。"},{"en":"Social change often begins with ordinary decisions repeated by many people.","zh":"社會改變常由許多人重複的平凡決定開始。"},{"en":"The writer sees his diet as a small part of a larger movement.","zh":"作者把自己的飲食視為更大運動中的一小部分。"}],"source":"2025 Q5.pdf","sourcePage":14},{"front":"rarely begins with","meaning":"很少始於","examples":[{"en":"Social change rarely begins with grand gestures.","zh":"社會改變很少始於宏大姿態。"},{"en":"Rarely begins with means does not often start from something.","zh":"很少始於意思是不常從某事開始。"},{"en":"Lasting health change rarely begins with one dramatic speech.","zh":"持久健康改變很少始於一次戲劇性的演講。"},{"en":"Many changes begin with quiet, repeated choices instead.","zh":"許多改變反而由安靜而重複的選擇開始。"},{"en":"This phrase challenges the idea that only big actions matter.","zh":"這個短語挑戰只有大行動才重要的想法。"}],"source":"2025 Q5.pdf","sourcePage":14},{"front":"grand gestures","meaning":"大動作；宏大姿態","examples":[{"en":"Social change rarely begins with grand gestures.","zh":"社會改變很少始於大動作。"},{"en":"Grand gestures are large, dramatic actions meant to attract attention.","zh":"大動作或宏大姿態是旨在吸引注意的大型、戲劇性行動。"},{"en":"A public campaign can be a grand gesture, but daily habits still matter.","zh":"公眾運動可以是大動作，但每日習慣仍然重要。"},{"en":"Grand gestures may inspire people, but they do not replace consistent action.","zh":"大動作可能啟發人，但不能取代持續行動。"},{"en":"The writer values ordinary meals more than dramatic declarations.","zh":"作者重視普通膳食，多於戲劇性的宣告。"}],"source":"2025 Q5.pdf","sourcePage":14},{"front":"ordinary decisions","meaning":"平凡決定","examples":[{"en":"Social change begins when people make ordinary decisions consistently.","zh":"當人們持續作出平凡決定時，社會改變便開始。"},{"en":"Ordinary decisions are small everyday choices.","zh":"平凡決定是日常生活中的小選擇。"},{"en":"Choosing a vegetable dish for lunch is an ordinary decision.","zh":"午餐選擇蔬菜菜式是一個平凡決定。"},{"en":"Ordinary decisions matter when many people repeat them over time.","zh":"當許多人長期重複平凡決定，它們就很重要。"},{"en":"The writer finds purpose in small choices that once seemed unimportant.","zh":"作者在曾經看似不重要的小選擇中找到目的感。"}],"source":"2025 Q5.pdf","sourcePage":14},{"front":"consistently","meaning":"持續地","examples":[{"en":"Ordinary people can make ordinary decisions consistently.","zh":"普通人可以持續地作出平凡決定。"},{"en":"Consistently means regularly and repeatedly over time.","zh":"持續地意思是有規律並長時間重複地。"},{"en":"Eating vegetarian meals a few times a week consistently can create real change.","zh":"每星期幾次持續地吃素食餐，可以創造真實改變。"},{"en":"Consistency turns a small action into a habit.","zh":"持續性把小行動變成習慣。"},{"en":"The writer understands that steady choices may matter more than one dramatic act.","zh":"作者明白穩定選擇可能比一次戲劇性行動更重要。"}],"source":"2025 Q5.pdf","sourcePage":14},{"front":"thousands of people","meaning":"數以千計的人","examples":[{"en":"If thousands of people ate less meat, the impact would be significant.","zh":"如果數以千計的人少吃肉，影響會很顯著。"},{"en":"Thousands of people means a very large number of individuals.","zh":"數以千計的人意思是非常多的個人。"},{"en":"One person’s choice may seem small, but thousands of people choosing together can matter.","zh":"一個人的選擇可能看似微小，但數以千計的人一起選擇就會重要。"},{"en":"Environmental impact grows when many people change habits at the same time.","zh":"當許多人同時改變習慣，環境影響就會增加。"},{"en":"The phrase helps explain why individual decisions can become collective power.","zh":"這個短語幫助解釋個人決定如何變成集體力量。"}],"source":"2025 Q5.pdf","sourcePage":14},{"front":"a few times a week","meaning":"每星期幾次","examples":[{"en":"People could eat less meat a few times a week.","zh":"人們可以每星期幾次少吃肉。"},{"en":"A few times a week means several times within one week.","zh":"每星期幾次意思是在一星期內數次。"},{"en":"A family may cook vegetarian dinners a few times a week without becoming fully vegetarian.","zh":"一個家庭可以每星期幾次煮素食晚餐，而不必完全成為素食者。"},{"en":"This approach feels practical because it does not require perfect change.","zh":"這種做法感覺實際，因為它不要求完美改變。"},{"en":"Small repeated reductions can still create collective impact.","zh":"小而重複的減少仍可以創造集體影響。"}],"source":"2025 Q5.pdf","sourcePage":15},{"front":"collective impact","meaning":"集體影響","examples":[{"en":"The collective impact would be significant.","zh":"集體影響會很顯著。"},{"en":"Collective impact is the combined effect of many people’s actions.","zh":"集體影響是許多人行動加起來的共同效果。"},{"en":"One vegetarian lunch is small, but many lunches create collective impact.","zh":"一份素食午餐很小，但許多份午餐會創造集體影響。"},{"en":"Collective impact helps the writer see purpose in personal choices.","zh":"集體影響幫助作者在個人選擇中看見目的。"},{"en":"Social change grows when individual actions add up.","zh":"當個人行動累積起來，社會改變就會成長。"}],"source":"2025 Q5.pdf","sourcePage":15},{"front":"significant","meaning":"顯著的","examples":[{"en":"The impact of many small choices could be significant.","zh":"許多小選擇的影響可以是顯著的。"},{"en":"Significant means important, noticeable, or meaningful.","zh":"顯著的意思是重要、明顯或有意義。"},{"en":"A small diet change can become significant when repeated by many people.","zh":"小小飲食改變若被許多人重複，可以變得顯著。"},{"en":"The writer realises that ordinary meals may have significant consequences.","zh":"作者意識到普通膳食可能有顯著後果。"},{"en":"Significant change often begins with choices that look modest at first.","zh":"顯著改變常始於一開始看似普通的選擇。"}],"source":"2025 Q5.pdf","sourcePage":15},{"front":"gave my experiment","meaning":"給予我的實驗","examples":[{"en":"Realising that gave my experiment a sense of purpose.","zh":"意識到這一點給予我的實驗一種目的感。"},{"en":"Gave my experiment means added something to the meaning or feeling of the experiment.","zh":"給予我的實驗意思是為實驗的意義或感覺加入某東西。"},{"en":"Understanding environmental impact gave the challenge deeper value.","zh":"理解環境影響給這個挑戰更深價值。"},{"en":"The experiment stops being only personal when it connects to society.","zh":"當實驗與社會連接時，它不再只是個人的。"},{"en":"The writer’s new understanding gives the week moral weight.","zh":"作者的新理解給這一星期道德重量。"}],"source":"2025 Q5.pdf","sourcePage":15},{"front":"a sense of purpose","meaning":"目的感","examples":[{"en":"The experiment gained a sense of purpose.","zh":"這個實驗獲得了目的感。"},{"en":"A sense of purpose is the feeling that an action has meaning and direction.","zh":"目的感是覺得一個行動有意義和方向的感覺。"},{"en":"A student may gain a sense of purpose when volunteering helps real people.","zh":"當義工服務幫助到真人時，學生可能獲得目的感。"},{"en":"The writer feels purposeful because his meals connect to wider consequences.","zh":"作者感到有目的，因為他的膳食與更廣泛後果連接起來。"},{"en":"This purpose helps the vegetarian week continue beyond seven days.","zh":"這種目的感幫助素食一星期延續到七日之後。"}],"source":"2025 Q5.pdf","sourcePage":15},{"front":"had not expected","meaning":"我沒有預料到","examples":[{"en":"I gained a sense of purpose that I had not expected.","zh":"我獲得了一種自己沒有預料到的目的感。"},{"en":"Had not expected means did not think something would happen.","zh":"沒有預料到意思是沒有想過某事會發生。"},{"en":"The writer had not expected a simple diet test to affect his values.","zh":"作者沒有預料到簡單飲食測試會影響他的價值觀。"},{"en":"Unexpected lessons often make experiments more memorable.","zh":"意想不到的教訓常令實驗更難忘。"},{"en":"The sense of purpose surprises him because he began with doubt.","zh":"目的感令他驚訝，因為他起初帶著懷疑。"}],"source":"2025 Q5.pdf","sourcePage":15},{"front":"of course","meaning":"當然","examples":[{"en":"Of course, the week was not perfect.","zh":"當然，這一星期並不完美。"},{"en":"Of course means naturally, certainly, or as expected.","zh":"當然意思是自然地、確實地或如預期地。"},{"en":"Of course, changing a diet can be inconvenient at first.","zh":"當然，改變飲食一開始可能不方便。"},{"en":"This phrase helps the writer admit difficulties honestly.","zh":"這個短語幫助作者誠實承認困難。"},{"en":"It keeps the reflection balanced rather than overly positive.","zh":"它令反思保持平衡，而不是過度正面。"}],"source":"2025 Q5.pdf","sourcePage":15},{"front":"not perfect","meaning":"並不完美","examples":[{"en":"The vegetarian week was not perfect.","zh":"素食一星期並不完美。"},{"en":"Not perfect means having problems, difficulties, or flaws.","zh":"並不完美意思是有問題、困難或缺點。"},{"en":"A challenge can be meaningful even if it is not perfect.","zh":"即使挑戰並不完美，它仍可以有意義。"},{"en":"The writer faced inconvenience, cravings, and tempting smells.","zh":"作者面對不便、口腹之慾和誘人的氣味。"},{"en":"Admitting imperfection makes his conclusion more believable.","zh":"承認不完美令他的結論更可信。"}],"source":"2025 Q5.pdf","sourcePage":15},{"front":"eating out","meaning":"外出用膳","examples":[{"en":"Eating out was sometimes inconvenient.","zh":"外出用膳有時不方便。"},{"en":"Eating out means having meals at restaurants or cafés instead of at home.","zh":"外出用膳意思是在餐廳或咖啡店吃飯，而不是在家中。"},{"en":"A vegetarian may need to check menus carefully when eating out.","zh":"素食者外出用膳時可能需要仔細查看餐牌。"},{"en":"Eating out can be harder if a restaurant has few meat-free options.","zh":"如果餐廳很少無肉選項，外出用膳可能較困難。"},{"en":"The writer learns that inconvenience is not the same as impossibility.","zh":"作者學到不方便不等於不可能。"}],"source":"2025 Q5.pdf","sourcePage":15},{"front":"inconvenient","meaning":"不方便","examples":[{"en":"Eating out was sometimes inconvenient during the experiment.","zh":"在實驗期間，外出用膳有時不方便。"},{"en":"Inconvenient means causing difficulty, trouble, or extra effort.","zh":"不方便意思是造成困難、麻煩或額外努力。"},{"en":"Reading every menu carefully can feel inconvenient when friends are hungry.","zh":"當朋友都很餓時，仔細看每份餐牌可能感覺不方便。"},{"en":"Inconvenience does not mean a habit cannot continue.","zh":"不方便不代表一個習慣不能繼續。"},{"en":"The benefits of the week make the inconvenience feel minor.","zh":"這一星期的好處令那些不便顯得很小。"}],"source":"2025 Q5.pdf","sourcePage":15},{"front":"read menus more carefully","meaning":"更仔細地看餐牌","examples":[{"en":"I had to read menus more carefully than before.","zh":"我必須比以前更仔細地看餐牌。"},{"en":"To read menus more carefully means to examine food choices and ingredients with more attention.","zh":"更仔細地看餐牌意思是更留心檢查食物選擇和食材。"},{"en":"A vegetarian diner reads menus carefully to avoid meat-based dishes.","zh":"素食食客會仔細看餐牌，以避開含肉菜式。"},{"en":"Careful menu reading can reveal options that are easy to miss.","zh":"仔細看餐牌可以發現容易錯過的選項。"},{"en":"The writer’s new habit makes eating out more deliberate.","zh":"作者的新習慣令外出用膳變得更有意識。"}],"source":"2025 Q5.pdf","sourcePage":16},{"front":"than before","meaning":"比以前","examples":[{"en":"I read menus more carefully than before.","zh":"我比以前更仔細地看餐牌。"},{"en":"Than before means compared with an earlier time.","zh":"比以前意思是與較早時間相比。"},{"en":"After the challenge began, the writer checked ingredients more carefully than before.","zh":"挑戰開始後，作者比以前更仔細檢查食材。"},{"en":"This phrase shows a change in behaviour.","zh":"這個短語顯示行為上的改變。"},{"en":"The writer becomes more mindful than before because he must make deliberate choices.","zh":"作者比以前更有意識，因為他必須作出有目的的選擇。"}],"source":"2025 Q5.pdf","sourcePage":16},{"front":"there were moments when","meaning":"有些時候","examples":[{"en":"There were moments when the smell of fried chicken nearly defeated me.","zh":"有些時候，炸雞的氣味幾乎擊敗了我的決心。"},{"en":"There were moments when means there were particular times when something happened.","zh":"有些時候意思是有某些特定時刻發生某事。"},{"en":"There were moments when the writer missed old food habits strongly.","zh":"有些時候，作者強烈想念舊有飲食習慣。"},{"en":"This phrase admits difficulty without saying the whole challenge failed.","zh":"這個短語承認困難，但沒有說整個挑戰失敗。"},{"en":"It makes the reflection honest and human.","zh":"它令反思誠實而有人情味。"}],"source":"2025 Q5.pdf","sourcePage":16},{"front":"fried chicken","meaning":"炸雞","examples":[{"en":"The smell of fried chicken nearly defeated my resolve.","zh":"炸雞的氣味幾乎擊敗我的決心。"},{"en":"Fried chicken is chicken cooked in hot oil until crisp.","zh":"炸雞是用熱油炸至香脆的雞肉。"},{"en":"Fried chicken can be tempting because it is familiar, salty, and fragrant.","zh":"炸雞因熟悉、鹹香和氣味吸引而很誘人。"},{"en":"The smell tests the writer’s vegetarian promise.","zh":"那股氣味考驗作者的素食承諾。"},{"en":"Resisting fried chicken helps him see that cravings are not genuine need.","zh":"抵抗炸雞幫助他明白口腹之慾不是真正需要。"}],"source":"2025 Q5.pdf","sourcePage":16},{"front":"defeated my resolve","meaning":"擊敗我的決心","examples":[{"en":"The smell of fried chicken nearly defeated my resolve.","zh":"炸雞的氣味幾乎擊敗我的決心。"},{"en":"Defeated my resolve means almost broke my determination to continue.","zh":"擊敗我的決心意思是幾乎打破我繼續下去的意志。"},{"en":"A tempting dessert may defeat someone’s resolve to avoid sugar.","zh":"誘人的甜品可能擊敗某人避開糖的決心。"},{"en":"The writer’s resolve is tested by smell, memory, and habit.","zh":"作者的決心受到氣味、記憶和習慣考驗。"},{"en":"He continues because the benefits are stronger than the craving.","zh":"他繼續下去，因為好處比口腹之慾更強。"}],"source":"2025 Q5.pdf","sourcePage":16},{"front":"resolve","meaning":"決心","examples":[{"en":"My resolve was tested by the smell of fried chicken.","zh":"我的決心受到炸雞氣味考驗。"},{"en":"Resolve means strong determination to do something.","zh":"決心意思是做某事的強烈意志。"},{"en":"A student’s resolve is tested when friends invite them to quit studying early.","zh":"當朋友邀請學生提早停止溫習時，學生的決心會受到考驗。"},{"en":"Resolve becomes stronger when people pass difficult moments.","zh":"人們渡過困難時刻後，決心會變得更強。"},{"en":"The writer’s resolve grows because he realises temptation is temporary.","zh":"作者的決心增強，因為他意識到誘惑是暫時的。"}],"source":"2025 Q5.pdf","sourcePage":16},{"front":"minor compared with","meaning":"與……相比是小事","examples":[{"en":"Those difficulties were minor compared with the benefits.","zh":"那些困難與好處相比是小事。"},{"en":"Minor compared with means small or less important when placed beside something else.","zh":"與某事相比是小事，意思是與另一事物並列時顯得較小或較不重要。"},{"en":"Reading menus carefully is minor compared with feeling healthier.","zh":"更仔細看餐牌與感覺更健康相比是小事。"},{"en":"This phrase helps weigh problems against gains.","zh":"這個短語幫助衡量問題和收穫。"},{"en":"The writer admits inconvenience but decides the benefits matter more.","zh":"作者承認不便，但認為好處更重要。"}],"source":"2025 Q5.pdf","sourcePage":16},{"front":"benefits I gained","meaning":"我得到的好處","examples":[{"en":"The benefits I gained were greater than the difficulties.","zh":"我得到的好處比困難更大。"},{"en":"Benefits I gained means the advantages or good results I received from the experience.","zh":"我得到的好處是指我從經歷中獲得的優勢或好結果。"},{"en":"The writer gained better energy, improved digestion, and stronger awareness.","zh":"作者得到更好精力、改善消化和更強意識。"},{"en":"These benefits make the temporary difficulty worthwhile.","zh":"這些好處令短暫困難變得值得。"},{"en":"The phrase shows why he chooses to continue the vegetarian lifestyle.","zh":"這個短語顯示他為何選擇繼續素食生活方式。"}],"source":"2025 Q5.pdf","sourcePage":16},{"front":"not the same as","meaning":"不等於","examples":[{"en":"Inconvenience is not the same as impossibility.","zh":"不方便不等於不可能。"},{"en":"Not the same as means two things should not be confused.","zh":"不等於意思是兩件事不應被混淆。"},{"en":"Feeling hungry for fried chicken is not the same as needing it.","zh":"想吃炸雞不等於真正需要它。"},{"en":"This phrase helps correct an exaggerated excuse.","zh":"這個短語幫助糾正誇張藉口。"},{"en":"The writer uses it to separate difficulty from defeat.","zh":"作者用它區分困難和失敗。"}],"source":"2025 Q5.pdf","sourcePage":16},{"front":"impossibility","meaning":"不可能","examples":[{"en":"Inconvenience is not the same as impossibility.","zh":"不方便不等於不可能。"},{"en":"Impossibility means something cannot be done.","zh":"不可能意思是某事無法做到。"},{"en":"Finding vegetarian food outside may be inconvenient, but it is not impossibility.","zh":"在外面找素食可能不方便，但不是不可能。"},{"en":"People may call things impossible when they are only unfamiliar.","zh":"人們可能把不熟悉的事情稱為不可能。"},{"en":"The writer proves the challenge is possible through daily practice.","zh":"作者透過每日實踐證明這個挑戰是可能的。"}],"source":"2025 Q5.pdf","sourcePage":16},{"front":"cravings","meaning":"口腹之慾","examples":[{"en":"Cravings are not the same as genuine need.","zh":"口腹之慾不等於真正需要。"},{"en":"Cravings are strong desires for a particular food or experience.","zh":"口腹之慾是對某種食物或經驗的強烈渴望。"},{"en":"The smell of fried chicken can create cravings.","zh":"炸雞氣味可以引起口腹之慾。"},{"en":"Cravings feel powerful, but they often pass after time or a good meal.","zh":"口腹之慾感覺強烈，但常在一段時間或一頓好飯後消退。"},{"en":"The writer learns not to confuse craving with necessity.","zh":"作者學到不要把口腹之慾和必要混淆。"}],"source":"2025 Q5.pdf","sourcePage":17},{"front":"genuine need","meaning":"真正需要","examples":[{"en":"Cravings are not the same as genuine need.","zh":"口腹之慾不等於真正需要。"},{"en":"Genuine need means something truly necessary, not merely desired.","zh":"真正需要意思是真正必要的東西，而不只是想要。"},{"en":"A person may want a burger, but their genuine need may be a filling meal.","zh":"一個人可能想吃漢堡，但真正需要可能是一頓飽肚的飯。"},{"en":"Understanding genuine need helps people make wiser choices.","zh":"理解真正需要幫助人作出更明智選擇。"},{"en":"The writer realises that meat was often a habit, not a genuine need.","zh":"作者意識到肉類很多時只是習慣，而不是真正需要。"}],"source":"2025 Q5.pdf","sourcePage":17},{"front":"if anything","meaning":"反而；真要說的話","examples":[{"en":"If anything, the challenge proved that excuses can be weak.","zh":"真要說的話，這個挑戰證明藉口可以很薄弱。"},{"en":"If anything means if we judge the situation carefully, the opposite or a stronger point is true.","zh":"反而或真要說的話，意思是如果仔細判斷，真正情況可能相反或更強。"},{"en":"The week did not prove vegetarianism impossible; if anything, it proved it was manageable.","zh":"這一星期沒有證明素食不可能；反而證明它可管理。"},{"en":"This phrase helps reverse a negative expectation.","zh":"這個短語幫助扭轉負面預期。"},{"en":"The writer uses it to show that difficulties actually strengthened his conclusion.","zh":"作者用它顯示困難其實加強了他的結論。"}],"source":"2025 Q5.pdf","sourcePage":17},{"front":"proved that","meaning":"證明","examples":[{"en":"The challenge proved that many excuses are weaker than they seem.","zh":"這個挑戰證明許多藉口比看起來更站不住腳。"},{"en":"Proved that means showed clearly that something is true.","zh":"證明某事意思是清楚顯示某事是真的。"},{"en":"The experiment proved that vegetarian meals can be filling.","zh":"這個實驗證明素食餐可以飽肚。"},{"en":"Personal experience can prove something more strongly than theory alone.","zh":"親身經驗比單靠理論更能有力地證明某事。"},{"en":"The writer’s week proves that change is often more possible than expected.","zh":"作者這一星期證明改變常比預期更可能。"}],"source":"2025 Q5.pdf","sourcePage":17},{"front":"excuses people give","meaning":"人們提出的藉口","examples":[{"en":"The excuses people give for not changing their diets may be weak.","zh":"人們為不改變飲食而提出的藉口可能很薄弱。"},{"en":"Excuses people give are reasons people offer to avoid doing something difficult.","zh":"人們提出的藉口，是人們為避免做困難事情而給出的理由。"},{"en":"“I have nothing to eat without meat” can be one excuse people give.","zh":"「沒有肉就沒有東西可吃」可以是人們提出的一個藉口。"},{"en":"Some excuses sound reasonable until experience tests them.","zh":"有些藉口在經驗測試之前聽起來合理。"},{"en":"The writer discovers that his own excuses were weaker than they seemed.","zh":"作者發現自己的藉口比看起來更站不住腳。"}],"source":"2025 Q5.pdf","sourcePage":17},{"front":"changing their diets","meaning":"改變飲食習慣","examples":[{"en":"Some people give excuses for not changing their diets.","zh":"有些人為不改變飲食習慣提出藉口。"},{"en":"Changing their diets means altering what they usually eat.","zh":"改變飲食習慣意思是改變自己通常吃的東西。"},{"en":"People may change their diets by reducing meat, sugar, or fried food.","zh":"人們可以透過減少肉、糖或油炸食物來改變飲食。"},{"en":"Diet change can be difficult because food is tied to habit and comfort.","zh":"改變飲食可以困難，因為食物與習慣和安慰有關。"},{"en":"The writer shows that changing a diet can begin with one week.","zh":"作者顯示改變飲食可以由一星期開始。"}],"source":"2025 Q5.pdf","sourcePage":17},{"front":"weaker than they seem","meaning":"比看起來更站不住腳","examples":[{"en":"Many excuses are weaker than they seem.","zh":"許多藉口比看起來更站不住腳。"},{"en":"Weaker than they seem means less convincing or less true than they first appear.","zh":"比看起來更站不住腳意思是比最初看來更不具說服力或更不真實。"},{"en":"“Vegetarian food is never filling” may be weaker than it seems after someone tries chickpea curry.","zh":"「素食從不飽肚」這個說法，在人試過鷹嘴豆咖喱後可能比看起來更站不住腳。"},{"en":"Experience can expose weak excuses.","zh":"經驗可以揭露薄弱藉口。"},{"en":"The writer learns that difficulty does not equal impossibility.","zh":"作者學到困難不等於不可能。"}],"source":"2025 Q5.pdf","sourcePage":17},{"front":"looking back","meaning":"回望起來","examples":[{"en":"Looking back, this experiment was meaningful.","zh":"回望起來，這個實驗很有意義。"},{"en":"Looking back means thinking about a past experience after it has happened.","zh":"回望起來意思是在某經歷發生後回想它。"},{"en":"Looking back, the writer sees the week as more than a diet test.","zh":"回望起來，作者把這一星期看成不只是飲食測試。"},{"en":"Reflection helps people understand what a challenge really taught them.","zh":"反思幫助人理解挑戰真正教會了自己甚麼。"},{"en":"Looking back, he realises the experiment changed both body and mind.","zh":"回望起來，他意識到這個實驗改變了身體和思想。"}],"source":"2025 Q5.pdf","sourcePage":17},{"front":"done exactly what","meaning":"正正做到","examples":[{"en":"This experiment has done exactly what a meaningful challenge should do.","zh":"這個實驗正正做到一個有意義挑戰應做到的事。"},{"en":"Done exactly what means achieved precisely the thing expected or needed.","zh":"正正做到意思是準確達成預期或需要的事情。"},{"en":"A good project has done exactly what it should if it teaches skills and confidence.","zh":"如果一個好項目教會技能和信心，它就正正做到應做的事。"},{"en":"The experiment works because it forces questioning, discovery, and growth.","zh":"這個實驗有效，因為它迫使人質疑、發現和成長。"},{"en":"This phrase shows the writer’s clear judgement after reflection.","zh":"這個短語顯示作者反思後有清晰判斷。"}],"source":"2025 Q5.pdf","sourcePage":17},{"front":"meaningful challenge","meaning":"有意義的挑戰","examples":[{"en":"A meaningful challenge should make people question assumptions.","zh":"有意義的挑戰應令人質疑假設。"},{"en":"A meaningful challenge is a difficult task that teaches something valuable.","zh":"有意義的挑戰是教會人有價值事情的困難任務。"},{"en":"Trying vegetarianism for a week can be meaningful if it changes how someone thinks.","zh":"如果嘗試素食一星期能改變人的想法，它可以是有意義的挑戰。"},{"en":"Meaningful challenges are not always dramatic; some happen at the dinner table.","zh":"有意義的挑戰不一定戲劇化；有些發生在飯桌上。"},{"en":"The writer’s challenge is meaningful because it leads to lasting choice.","zh":"作者的挑戰有意義，因為它帶來持久選擇。"}],"source":"2025 Q5.pdf","sourcePage":17},{"front":"forced me to","meaning":"迫使我","examples":[{"en":"The experiment forced me to question assumptions.","zh":"這個實驗迫使我質疑假設。"},{"en":"Forced me to means made me do something, especially something uncomfortable or necessary.","zh":"迫使我做某事，意思是令我做某件不舒服或必要的事。"},{"en":"The empty feeling in front of the fridge forced the writer to think differently.","zh":"站在雪櫃前的空虛感迫使作者換個方式思考。"},{"en":"Challenges force people to notice habits they usually ignore.","zh":"挑戰會迫使人注意平時忽略的習慣。"},{"en":"The experiment forced him to become more deliberate about food.","zh":"這個實驗迫使他在食物方面變得更有意識。"}],"source":"2025 Q5.pdf","sourcePage":18},{"front":"question assumptions","meaning":"質疑假設","examples":[{"en":"The experiment forced me to question assumptions about food.","zh":"這個實驗迫使我質疑關於食物的假設。"},{"en":"To question assumptions means to examine beliefs that people usually accept without proof.","zh":"質疑假設意思是檢視人們通常沒有證據也接受的信念。"},{"en":"The writer questioned the assumption that a proper meal needs meat.","zh":"作者質疑一頓像樣的飯必須有肉這個假設。"},{"en":"Questioning assumptions can open new choices.","zh":"質疑假設可以打開新選擇。"},{"en":"The challenge teaches him that old habits are not the same as truth.","zh":"這個挑戰教他舊習慣不等於真理。"}],"source":"2025 Q5.pdf","sourcePage":18},{"front":"discover alternatives","meaning":"發現替代選擇","examples":[{"en":"The challenge helped me discover alternatives to meat.","zh":"這個挑戰幫助我發現肉類的替代選擇。"},{"en":"To discover alternatives means to find other choices that can replace the usual one.","zh":"發現替代選擇意思是找到可以取代平常選項的其他選擇。"},{"en":"The writer discovered tofu, mushrooms, and chickpeas as alternatives.","zh":"作者發現豆腐、蘑菇和鷹嘴豆作為替代選擇。"},{"en":"Alternatives reduce fear because people no longer feel trapped.","zh":"替代選擇能減少恐懼，因為人們不再感到被困住。"},{"en":"Discovering alternatives turns vegetarianism from limitation into possibility.","zh":"發現替代選擇把素食由限制轉化為可能性。"}],"source":"2025 Q5.pdf","sourcePage":18},{"front":"grow from the process","meaning":"從過程中成長","examples":[{"en":"I grew from the process of changing my diet.","zh":"我從改變飲食習慣的過程中成長。"},{"en":"To grow from the process means to become wiser, stronger, or more aware through the experience.","zh":"從過程中成長意思是透過經歷變得更有智慧、更堅強或更有意識。"},{"en":"A student may grow from the process of learning to cook independently.","zh":"學生可能從學習獨立煮食的過程中成長。"},{"en":"Growth often happens during the struggle, not only after success.","zh":"成長常發生在掙扎中，而不只是在成功後。"},{"en":"The writer grows because the process changes how he thinks about food.","zh":"作者成長，因為這個過程改變了他對食物的想法。"}],"source":"2025 Q5.pdf","sourcePage":18},{"front":"decided to continue","meaning":"決定繼續","examples":[{"en":"I have decided to continue being a vegetarian.","zh":"我已決定繼續做素食者。"},{"en":"Decided to continue means made a choice to keep doing something.","zh":"決定繼續意思是作出選擇，繼續做某事。"},{"en":"After the experiment, the writer decided to continue because the benefits felt real.","zh":"實驗後，作者決定繼續，因為好處感覺真實。"},{"en":"Continuing shows that the week was not just a passing interest.","zh":"繼續下去顯示這一星期不只是短暫興趣。"},{"en":"This decision turns a temporary test into a lasting habit.","zh":"這個決定把暫時性測試變成持久習慣。"}],"source":"2025 Q5.pdf","sourcePage":18},{"front":"morally superior","meaning":"道德上較優越","examples":[{"en":"I am not continuing because it makes me morally superior.","zh":"我繼續下去，不是因為它令我道德上較優越。"},{"en":"Morally superior means believing oneself to be better or more ethical than others.","zh":"道德上較優越意思是相信自己比別人更好或更有道德。"},{"en":"The writer does not want vegetarianism to become a way of looking down on people.","zh":"作者不希望素食主義變成看低別人的方式。"},{"en":"Good choices should create responsibility, not arrogance.","zh":"好選擇應創造責任，而不是傲慢。"},{"en":"He continues because he feels more conscious, not because he feels better than others.","zh":"他繼續是因為自己更有意識，而不是覺得比別人優越。"}],"source":"2025 Q5.pdf","sourcePage":18},{"front":"more conscious","meaning":"更有意識","examples":[{"en":"Vegetarianism makes me more conscious about food choices.","zh":"素食主義令我對食物選擇更有意識。"},{"en":"More conscious means more aware, thoughtful, and deliberate.","zh":"更有意識意思是更清楚、更有思考和更有目的。"},{"en":"A person becomes more conscious when they read ingredients before buying food.","zh":"一個人購買食物前閱讀食材時，就變得更有意識。"},{"en":"Conscious eating helps people connect taste with health and values.","zh":"有意識地進食幫助人把味道與健康和價值連接起來。"},{"en":"The writer feels more conscious because he now thinks before choosing.","zh":"作者感到更有意識，因為他現在選擇前會先思考。"}],"source":"2025 Q5.pdf","sourcePage":18},{"front":"more responsible","meaning":"更負責任","examples":[{"en":"The lifestyle makes me feel more responsible.","zh":"這種生活方式令我感到更負責任。"},{"en":"More responsible means more willing to consider the effects of one’s actions.","zh":"更負責任意思是更願意考慮自己行動的影響。"},{"en":"A person feels more responsible when they understand how choices affect others.","zh":"當一個人明白選擇如何影響他人，就會感到更負責任。"},{"en":"Vegetarianism makes the writer think about health, animals, and the environment.","zh":"素食主義令作者思考健康、動物和環境。"},{"en":"Responsibility turns food from private preference into thoughtful action.","zh":"責任感把食物由私人喜好轉化為有思考的行動。"}],"source":"2025 Q5.pdf","sourcePage":18},{"front":"what began as","meaning":"起初是……的事","examples":[{"en":"What began as a temporary test has become a lasting choice.","zh":"起初是暫時性測試的事，已變成持久的選擇。"},{"en":"What began as means something started in a certain way before changing later.","zh":"起初是某事，意思是某物以某種方式開始，後來有所改變。"},{"en":"What began as curiosity can become commitment after real experience.","zh":"起初是好奇的事，在真實經驗後可以變成承諾。"},{"en":"This phrase shows development from a small beginning to a bigger result.","zh":"這個短語顯示由小開始發展成更大結果。"},{"en":"The writer’s experiment began casually but ended with a serious decision.","zh":"作者的實驗起初很隨意，但最終成為認真決定。"}],"source":"2025 Q5.pdf","sourcePage":18},{"front":"temporary test","meaning":"暫時性測試","examples":[{"en":"The experiment began as a temporary test.","zh":"這個實驗起初是暫時性測試。"},{"en":"A temporary test is a short trial that is not expected to last forever.","zh":"暫時性測試是短期試驗，一開始不預期永遠持續。"},{"en":"Trying vegetarianism for one week can begin as a temporary test.","zh":"試行素食一星期可以由暫時性測試開始。"},{"en":"Temporary tests are useful because they let people experiment without fear.","zh":"暫時性測試很有用，因為它讓人不太害怕地嘗試。"},{"en":"This temporary test becomes important because it changes the writer’s values.","zh":"這個暫時性測試變得重要，因為它改變了作者的價值觀。"}],"source":"2025 Q5.pdf","sourcePage":18},{"front":"lasting choice","meaning":"持久的選擇","examples":[{"en":"The temporary test has become a lasting choice.","zh":"這個暫時性測試已變成持久的選擇。"},{"en":"A lasting choice is a decision that continues beyond the original moment.","zh":"持久的選擇是會延續到原本時刻之後的決定。"},{"en":"A one-week habit can become a lasting choice if it improves daily life.","zh":"如果一星期習慣改善日常生活，它可以變成持久的選擇。"},{"en":"Lasting choices usually need both practical benefits and personal meaning.","zh":"持久選擇通常需要實際好處和個人意義。"},{"en":"Vegetarianism becomes a lasting choice because the writer feels healthier and more aware.","zh":"素食成為持久選擇，因為作者感到更健康和更有意識。"}],"source":"2025 Q5.pdf","sourcePage":19},{"front":"curious about","meaning":"對……好奇","examples":[{"en":"If you are curious about vegetarianism, try it for a week.","zh":"如果你對素食主義好奇，就試行一星期。"},{"en":"Curious about means interested in learning more about something.","zh":"對某事好奇意思是有興趣了解更多。"},{"en":"A student curious about cooking may start with one simple recipe.","zh":"對煮食好奇的學生可能由一個簡單食譜開始。"},{"en":"Curiosity can be the first step toward meaningful change.","zh":"好奇心可以是有意義改變的第一步。"},{"en":"The writer invites curious readers to test vegetarianism for themselves.","zh":"作者邀請好奇的讀者親自測試素食主義。"}],"source":"2025 Q5.pdf","sourcePage":19},{"front":"vegetarianism","meaning":"素食主義","examples":[{"en":"Vegetarianism may be more practical than many people imagine.","zh":"素食主義可能比許多人想像中更實際。"},{"en":"Vegetarianism is the practice or belief of avoiding meat in one’s diet.","zh":"素食主義是在飲食中避免肉類的做法或信念。"},{"en":"Some people choose vegetarianism for health, environment, animals, or personal values.","zh":"有些人因健康、環境、動物或個人價值而選擇素食主義。"},{"en":"Vegetarianism becomes easier when meals are planned with nutrition and variety.","zh":"當膳食以營養和變化來安排，素食主義會變得更容易。"},{"en":"The writer discovers vegetarianism through experience rather than fashion.","zh":"作者透過經驗而不是潮流發現素食主義。"}],"source":"2025 Q5.pdf","sourcePage":19},{"front":"my advice is simple","meaning":"我的建議很簡單","examples":[{"en":"My advice is simple: try vegetarianism for a week.","zh":"我的建議很簡單：試行素食一星期。"},{"en":"My advice is simple means the suggestion is clear and easy to understand.","zh":"我的建議很簡單意思是建議清楚而容易理解。"},{"en":"My advice is simple: start with one vegetarian meal, not a perfect lifestyle.","zh":"我的建議很簡單：由一餐素食開始，而不是追求完美生活方式。"},{"en":"Simple advice can be powerful when it is practical.","zh":"簡單建議如果實際，就可以很有力量。"},{"en":"The writer’s advice is simple because his own change began with seven days.","zh":"作者的建議很簡單，因為他自己的改變由七日開始。"}],"source":"2025 Q5.pdf","sourcePage":19},{"front":"try it for a week","meaning":"試行一星期","examples":[{"en":"Try vegetarianism for a week.","zh":"試行素食一星期。"},{"en":"Try it for a week means test something for seven days before judging it.","zh":"試行一星期意思是在判斷之前先測試七日。"},{"en":"A person unsure about vegetarian meals can try them for a week.","zh":"對素食餐不確定的人可以試行一星期。"},{"en":"Trying for a short period reduces fear of permanent change.","zh":"短期嘗試能減少對永久改變的恐懼。"},{"en":"The writer believes one week is enough to challenge old assumptions.","zh":"作者相信一星期已足以挑戰舊假設。"}],"source":"2025 Q5.pdf","sourcePage":19},{"front":"begin with doubt","meaning":"帶著懷疑開始","examples":[{"en":"You may begin with doubt, as I did.","zh":"你可能會像我一樣，帶著懷疑開始。"},{"en":"Begin with doubt means start while feeling unsure or sceptical.","zh":"帶著懷疑開始意思是在不確定或懷疑的情況下開始。"},{"en":"A person may begin with doubt but become confident after real experience.","zh":"一個人可能帶著懷疑開始，但在真實經驗後變得有信心。"},{"en":"Doubt is not failure; it can be the starting point of honest testing.","zh":"懷疑不是失敗；它可以是誠實測試的起點。"},{"en":"The writer reassures readers that scepticism is normal.","zh":"作者安慰讀者，懷疑是正常的。"}],"source":"2025 Q5.pdf","sourcePage":19},{"front":"as I did","meaning":"就像我一樣","examples":[{"en":"You may begin with doubt, as I did.","zh":"你可能帶著懷疑開始，就像我一樣。"},{"en":"As I did means in the same way that I did.","zh":"就像我一樣意思是以和我相同的方式。"},{"en":"You may feel unprepared at first, as I did.","zh":"你一開始可能感到毫無準備，就像我一樣。"},{"en":"This phrase makes the advice personal and friendly.","zh":"這個短語令建議更個人化和友善。"},{"en":"The writer uses his own doubt to encourage readers who feel the same.","zh":"作者用自己的懷疑鼓勵有相同感受的讀者。"}],"source":"2025 Q5.pdf","sourcePage":19},{"front":"end up discovering","meaning":"最後發現","examples":[{"en":"You might end up discovering that the change is needed.","zh":"你可能最後發現這個改變是需要的。"},{"en":"End up discovering means finally find out something, often unexpectedly.","zh":"最後發現意思是最終知道某事，通常出乎意料。"},{"en":"A person may end up discovering that vegetarian meals are easier than expected.","zh":"一個人可能最後發現素食膳食比預期更容易。"},{"en":"Trying something directly can lead to discoveries that advice alone cannot give.","zh":"親自嘗試某事可以帶來單靠建議無法給予的發現。"},{"en":"The writer hopes readers will discover their own need for change.","zh":"作者希望讀者會發現自己也需要改變。"}],"source":"2025 Q5.pdf","sourcePage":19},{"front":"the change you feared","meaning":"你所害怕的改變","examples":[{"en":"The change you feared may be the one you needed.","zh":"你所害怕的改變，可能正是你需要的改變。"},{"en":"The change you feared means the change that made you worried or resistant.","zh":"你所害怕的改變意思是令你擔心或抗拒的改變。"},{"en":"A student may fear changing their diet because they expect hunger or inconvenience.","zh":"學生可能害怕改變飲食，因為他們預期會肚餓或不方便。"},{"en":"Fear can make useful change look more difficult than it is.","zh":"恐懼會令有用改變看起來比實際更困難。"},{"en":"The writer learns that the feared change can become a welcome choice.","zh":"作者學到害怕的改變可以變成受歡迎的選擇。"}],"source":"2025 Q5.pdf","sourcePage":19},{"front":"needed most","meaning":"最需要的","examples":[{"en":"The change you feared may be the one you needed most.","zh":"你所害怕的改變，可能正是你最需要的。"},{"en":"Needed most means most necessary or most helpful.","zh":"最需要的意思是最必要或最有幫助的。"},{"en":"A person may fear planning meals, but that may be what they need most for better health.","zh":"一個人可能害怕安排膳食，但這可能是他為了改善健康最需要的事。"},{"en":"The phrase gives the ending a hopeful lesson.","zh":"這個短語令結尾帶有希望的教訓。"},{"en":"The writer suggests that discomfort may point toward the growth we need most.","zh":"作者暗示不舒服的感覺可能指向我們最需要的成長。"}],"source":"2025 Q5.pdf","sourcePage":19}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
Object.assign(window.EDMUND_FLASHCARD_SEED,window.EDMUND_DSE_WRITING_PART_B_2025_SEED);
